fn row_supports_terminal(shell: &ShellState, row: &BrowserRow) -> bool {
    match row.kind {
        BrowserRowKind::Session => true,
        BrowserRowKind::Document => {
            row.document_kind == Some(WorkspaceDocumentKind::TerminalRecipe)
                || shell.server.session_supports_terminal(&row.full_path)
        }
        _ => false,
    }
}
fn active_viewport_shows_terminal_theme(snapshot: &RenderSnapshot) -> bool {
    snapshot.active_view_mode == WorkspaceViewMode::Terminal
}
/// Whether the titlebar's Web View ↔ Terminal toggle should appear for the active
/// session. It is a libyggterm-spec affordance shown ONLY when a session truly has
/// BOTH surfaces: an agent CLI (Codex / Claude Code) renders its JSONL transcript
/// as the Web View and its PTY as the Terminal, so it gets the toggle. A plain
/// shell has only a terminal.
///
/// ⚠ It used to read `snapshot.active_session`, a struct that is `None` whenever
/// the live-session list has not caught up with `active_session_path` — so the
/// toggle VANISHED on a session that plainly had both surfaces (live-caught on a
/// Claude Code session, 2026-07-25: `visibility:hidden` while the viewport was
/// showing that very session). The kind carried on the snapshot's active row is
/// the same answer without the second lookup that can lag.
fn active_session_offers_view_toggle(snapshot: &RenderSnapshot) -> bool {
    if let Some(session) = snapshot.active_session.as_ref() {
        return session.kind.offers_rendered_view();
    }
    // No live-session record yet: fall back to the kind the active ROW carries,
    // which the sidebar already resolved.
    snapshot
        .active_session_kind
        .is_some_and(SessionKind::offers_rendered_view)
}
/// What the titlebar's ONE surface-switch slot is showing.
///
/// The slot (`.yggterm-titlebar-view-toggle`) is the single home of "what is
/// this session's viewport showing". It used to answer only for agent CLIs, so
/// a libyggterm app's document surface grew its OWN Document|Terminal pill —
/// two of them, in fact, both `position:absolute` over a viewport that had
/// reserved no space for them, so the pill drew straight over the first line of
/// the document it was meant to control. There is now one switch, in the slot
/// that already existed for exactly this question.
#[derive(Clone, PartialEq, Eq, Debug)]
enum TitlebarSurfaceSwitch {
    /// Nothing to switch. The slot keeps its footprint so the rest of the
    /// titlebar does not shuffle, but it is hidden and inert.
    None,
    /// An agent CLI's rendered view ↔ its terminal. No payload: which segment
    /// is active is `active_view_mode`, and a copy here could only disagree
    /// with it.
    Rendered,
    /// A libyggterm app's document surface ↔ the terminal the app runs in, or custom app segments.
    Document {
        document_visible: bool,
        custom: Option<AppTitlebarSwitch>,
    },
}
/// Decide which switch the titlebar slot shows for the active session.
///
/// A declared document surface WINS over the rendered-view toggle: the session
/// is a shell hosting an app, and the app's surface is the thing in the
/// viewport. `SessionKind` deliberately declines to answer this — see
/// `SessionKind::offers_rendered_view`, whose test says in as many words that
/// "an app that declares a viewport pane is the caller's question, not the
/// kind's". This is that caller.
fn titlebar_surface_switch(snapshot: &RenderSnapshot) -> TitlebarSurfaceSwitch {
    if let Some(surface) = snapshot
        .active_session_path
        .as_deref()
        .and_then(|path| snapshot.document_surfaces.get(path))
    {
        let custom = surface.schema.as_ref().and_then(|s| s.schema.titlebar_switch.clone());
        if let Some(c) = &custom {
            if c.segments.is_empty() {
                return TitlebarSurfaceSwitch::None;
            }
        }
        return TitlebarSurfaceSwitch::Document {
            document_visible: surface.pane.visible,
            custom,
        };
    }
    if active_session_offers_view_toggle(snapshot) {
        return TitlebarSurfaceSwitch::Rendered;
    }
    TitlebarSurfaceSwitch::None
}
/// Where toasts land — decided by the viewport they would cover.
///
/// DESIGN.md's default is "horizontally centered near the top", and that is
/// right over a terminal, where the prompt and the newest output live at the
/// BOTTOM. Over a document the top of the viewport is the title and the first
/// line the user is reading, so the stack moves to the far bottom corner —
/// the corner on the rail's edge, because the mirror moves everything
/// directional with its edge.
///
/// Narrow on purpose: only a VISIBLE document surface moves the toasts. A web
/// surface keeps the top-centre anchor (it already has the
/// `data-covers-web-surface` input-hole machinery built around that position),
/// and so does the start page.
fn toast_anchor(snapshot: &RenderSnapshot) -> ToastAnchor {
    let document_owns_viewport = snapshot
        .active_session_path
        .as_deref()
        .and_then(|path| snapshot.document_surfaces.get(path))
        .is_some_and(|surface| surface.pane.visible);
    if !document_owns_viewport {
        return ToastAnchor::TopCenter;
    }
    match snapshot.settings.chrome_orientation.edge(ChromeSlot::Rail) {
        SidebarEdge::Left => ToastAnchor::BottomLeft,
        SidebarEdge::Right => ToastAnchor::BottomRight,
    }
}
fn rendered_surface_noun(session: &ManagedSessionView) -> &'static str {
    if session.kind == SessionKind::Document {
        match metadata_value(session, "Kind").as_str() {
            "terminal recipe" => "recipe",
            "note" => "paper",
            _ => "document",
        }
    } else {
        "web view"
    }
}
fn rendered_surface_title(session: &ManagedSessionView) -> &'static str {
    if session.kind == SessionKind::Document {
        match metadata_value(session, "Kind").as_str() {
            "terminal recipe" => "Recipe",
            "note" => "Paper",
            _ => "Document",
        }
    } else {
        "Web View"
    }
}
fn row_surface_noun(row: &BrowserRow, prefer_terminal: bool) -> &'static str {
    if prefer_terminal {
        "terminal"
    } else if let Some(kind) = row.document_kind {
        match kind {
            yggterm_core::WorkspaceDocumentKind::Note => "paper",
            yggterm_core::WorkspaceDocumentKind::TerminalRecipe => "recipe",
        }
    } else {
        "web view"
    }
}
#[derive(Clone, PartialEq, Eq)]
struct SearchCommandSuggestion {
    command: String,
    description: String,
}
// The ALT+ KeyTips accelerator map is owned by `command_registry`; the shell
// resolves a typed sequence through the in-force `Keymap` and dispatches the
// resulting `ShellCommand` via `execute_shell_command`. There is no shell-local
// copy of the letter→action table (SSOT = the registry).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TreeSelectionMode {
    Replace,
    ExtendRange,
    Toggle,
}

fn tree_selection_mode_for_modifiers(modifiers: Modifiers) -> TreeSelectionMode {
    if modifiers.contains(Modifiers::SHIFT) {
        TreeSelectionMode::ExtendRange
    } else if modifiers.contains(Modifiers::CONTROL) || modifiers.contains(Modifiers::META) {
        TreeSelectionMode::Toggle
    } else {
        TreeSelectionMode::Replace
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CopyRegenerationMode {
    Title,
    Summary,
    Copy,
}
#[derive(Debug, Clone, Copy, PartialEq)]
struct ContextMenuPlacement {
    left: Option<f64>,
    top: Option<f64>,
    right: Option<f64>,
    bottom: Option<f64>,
    /// How tall the menu may actually be AT THIS ANCHOR, in CSS px.
    ///
    /// The surface used to cap itself with `max-height:calc(100vh - 24px)`,
    /// which silently assumes the menu starts at the top of the window. A menu
    /// anchored partway down is then allowed to be a full viewport tall and
    /// runs off the bottom edge — taking its own scrollbar with it, so the
    /// overflow is real but UNREACHABLE (user report: the profile dropdown,
    /// ~30 entries, anchored at y≈108 in a 1200px window, was cut off with no
    /// way to scroll). The placement already knows the window, the margin and
    /// the anchor, so it is the only thing that CAN answer this — and the box
    /// disagreeing with the placement math is precisely the bug class
    /// `context_menu_surface_style` says it exists to prevent.
    max_height: f64,
}
#[derive(Clone)]
struct CopyGenerationTarget {
    session_path: String,
    session_id: String,
    cwd: String,
    title: String,
    source_updated_at: Option<OffsetDateTime>,
    remote_context: Option<String>,
    /// Routing only — deliberately NOT the whole `RemoteMachineSnapshot`. The
    /// copy scan builds one target per scanned session, and carrying the
    /// machine's session list here deep-copied every session on the machine
    /// into every target (measured: 1.75 MB x 644 targets per scan on the live
    /// host). The one thing the scan read out of that list now rides
    /// `cached_summary` below, copied from the session the target IS.
    remote_machine: Option<RemoteMachineRef>,
    /// The summary the remote host already generated for THIS session, copied
    /// at target construction from the same record that gave us
    /// `session_path`. Read it from anywhere else and a target can end up
    /// paired with another session's summary, which decides "summary missing"
    /// wrongly and burns an LLM call.
    cached_summary: Option<String>,
    storage_path: Option<String>,
}
