    fn restore_active_preview_if_snapshot_regressed(
        &mut self,
        previous_active_session: Option<ManagedSessionView>,
    ) {
        let Some(previous_active_session) = previous_active_session else {
            return;
        };
        if self.server.active_view_mode() != WorkspaceViewMode::Rendered {
            return;
        }
        if previous_active_session.preview.blocks.is_empty() {
            return;
        }
        let Some(active_path) = self.server.active_session_path().map(str::to_string) else {
            return;
        };
        if active_path != previous_active_session.session_path {
            return;
        }
        let _ = self.server.restore_session_preview_if_empty(
            &active_path,
            previous_active_session.preview,
            previous_active_session.rendered_sections,
        );
    }
    fn mark_active_remote_preview_dirty_if_needed(&mut self) {
        if self.server.active_view_mode() != WorkspaceViewMode::Rendered {
            return;
        }
        let Some(session) = self.server.active_session().cloned() else {
            return;
        };
        if !session_preview_syncs_from_remote(&session.session_path) {
            return;
        }
        if !remote_preview_needs_refresh(&session) {
            return;
        }
        self.remote_preview_dirty_epoch
            .insert(session.session_path, current_millis());
    }
    fn seed_dynamic_top_level_expansions(&mut self) {
        let mut paths = Vec::new();
        let has_promoted_live_sessions = self
            .server
            .live_sessions()
            .iter()
            .any(|session| is_promoted_live_session(session))
            || self.retained_terminal_session_paths.iter().any(|path| {
                self.terminal_session_is_retained_live(path) && is_hot_terminal_sidebar_path(path)
            });
        if has_promoted_live_sessions {
            paths.push("__live_sessions__".to_string());
        }
        paths.extend(self.active_session_visibility_paths());
        // Auto-seeding never overrides an explicit user collapse (persisted
        // across restarts); an explicit open via ensure_session_path_visible
        // still reveals.
        paths.retain(|path| !self.user_collapsed_synthetic_paths.contains(path));
        self.browser.ensure_expanded_paths(paths);
        self.sync_browser_settings();
    }
    fn ensure_active_session_visible(&mut self) {
        self.ensure_active_session_expanded();
        self.sync_active_session_selection();
        self.sync_browser_settings();
    }
    fn ensure_session_path_visible(&mut self, session_path: &str) {
        if is_hot_terminal_sidebar_path(session_path)
            || self.server.live_sessions().iter().any(|session| {
                session.session_path == session_path && is_promoted_live_session(session)
            })
        {
            self.browser
                .ensure_expanded_paths(vec!["__live_sessions__".to_string()]);
        }
        self.browser.ensure_visible_path(session_path);
    }
    fn retain_terminal_session_path(&mut self, session_path: &str) -> u64 {
        let limit_to_active_session = linux_limit_live_terminal_retention();
        let active_terminal_path = if limit_to_active_session
            && self.server.active_view_mode() == WorkspaceViewMode::Terminal
        {
            self.server
                .active_session_path()
                .filter(|path| self.server.session_supports_terminal(path))
                .map(str::to_string)
        } else {
            None
        };
        // HOT-tier Phase 3: record this activation at the front of the MRU and
        // compute the bounded pre-mount keep-set. Under the limit-to-active
        // policy this keeps the top-N recently-used hosts mounted+warm so
        // switching among them reuses the live host (no remount). Disabled by
        // YGGTERM_DISABLE_HOT_PREMOUNT.
        let premount_paths = if limit_to_active_session && hot_premount_enabled() {
            self.note_terminal_activation_mru(session_path);
            self.compute_hot_premount_keep_set(active_terminal_path.as_deref())
        } else {
            HashSet::new()
        };
        retain_terminal_session_path_for_policy(
            &mut self.retained_terminal_session_paths,
            &mut self.terminal_mount_epochs,
            session_path,
            limit_to_active_session,
            active_terminal_path.as_deref(),
            &premount_paths,
        )
    }
    /// Move `session_path` to the front of the activation MRU (most-recent
    /// first), de-duplicating and trimming so the list never grows unbounded.
    fn note_terminal_activation_mru(&mut self, session_path: &str) {
        self.terminal_activation_mru
            .retain(|path| path != session_path);
        self.terminal_activation_mru
            .insert(0, session_path.to_string());
        // Keep a little headroom past the cap so an evicted-then-revisited
        // session is still ranked by recency, but bound total growth.
        let max_tracked = hot_premount_retained_cap().saturating_mul(4).max(8);
        self.terminal_activation_mru.truncate(max_tracked);
    }
    /// The bounded set of session paths to keep mounted under limit-to-active
    /// retention: the active path plus the most-recently-used mountable
    /// neighbors, capped at `HOT_PREMOUNT_RETAINED_CAP`. Only sessions that can
    /// actually render a terminal host are kept, so dead/non-terminal rows are
    /// never pinned into the retained set.
    fn compute_hot_premount_keep_set(&self, active_terminal_path: Option<&str>) -> HashSet<String> {
        let mut keep = HashSet::new();
        if let Some(active) = active_terminal_path {
            keep.insert(active.to_string());
        }
        for path in &self.terminal_activation_mru {
            if keep.len() >= hot_premount_retained_cap() {
                break;
            }
            if keep.contains(path) {
                continue;
            }
            if self.terminal_session_is_premount_mountable(path) {
                keep.insert(path.clone());
            }
        }
        keep
    }
    /// Whether a session can host a live terminal surface right now — the same
    /// mountability test the retained-render path uses. Gates which MRU entries
    /// are eligible to stay pre-mounted.
    fn terminal_session_is_premount_mountable(&self, session_path: &str) -> bool {
        self.server.session_supports_terminal(session_path)
            || self.cached_hot_session_views.contains_key(session_path)
            || self.server.live_sessions().iter().any(|session| {
                session.session_path == session_path
                    && is_live_local_stored_codex_terminal_session(session)
            })
    }
    /// Apply a WorkingFlags poll result (the working-dot lag fix): patch the
    /// live sessions' `working` in place and run the same finished-working edge
    /// detection the snapshot applies use. Returns true when anything changed
    /// (so the caller re-renders). Full snapshot applies remain the SSOT for
    /// everything else; this only keeps ONE field fresh while a focused
    /// terminal defers background refreshes for 10-45s at a time.
    fn apply_working_flags_poll(&mut self, flags: &[(String, bool)]) -> bool {
        let changed = self.server.apply_live_session_working_flags(flags);
        if changed.is_empty() {
            return false;
        }
        self.notify_finished_working_sessions("working_flags_poll");
        true
    }
    fn refresh_cached_hot_session_views(&mut self) {
        for session in self.server.live_session_views().iter() {
            self.cached_hot_session_views
                .insert(session.session_path.clone(), (*session).clone());
        }
        if let Some(session) = self.server.active_session().cloned() {
            self.cached_hot_session_views
                .insert(session.session_path.clone(), session);
        }
    }
    fn prune_cached_hot_session_views(&mut self) {
        let mut keep_paths = self
            .server
            .live_session_views()
            .iter()
            .map(|session| session.session_path.clone())
            .collect::<HashSet<_>>();
        if let Some(active_path) = self.server.active_session_path() {
            keep_paths.insert(active_path.to_string());
        }
        keep_paths.extend(self.retained_terminal_session_paths.iter().cloned());
        self.cached_hot_session_views
            .retain(|session_path, _| keep_paths.contains(session_path));
    }
    fn cached_hot_session_view(&self, session_path: &str) -> Option<ManagedSessionView> {
        self.cached_hot_session_views.get(session_path).cloned()
    }
    fn sync_live_terminal_retention(&mut self) {
        let limit_to_active_session = linux_limit_live_terminal_retention();
        let active_terminal_path = if self.server.active_view_mode() == WorkspaceViewMode::Terminal
        {
            self.server.active_session_path().map(str::to_string)
        } else {
            None
        };
        let mut keep_paths = if limit_to_active_session {
            HashSet::new()
        } else {
            self.server
                .live_sessions()
                .iter()
                .filter(|session| {
                    let session_path = session.session_path.as_str();
                    let active_terminal = active_terminal_path.as_deref() == Some(session_path);
                    let has_current_render_state =
                        self.terminal_session_has_current_render_state(session_path);
                    ((active_terminal || has_current_render_state)
                        && is_promoted_live_session(session)
                        && self.server.session_supports_terminal(&session.session_path))
                        || (has_current_render_state
                            && is_live_local_stored_codex_terminal_session(session))
                })
                .map(|session| session.session_path.clone())
                .collect::<HashSet<_>>()
        };
        if let Some(active_path) = self.server.active_session_path()
            && self.server.session_supports_terminal(active_path)
            && (self.server.active_view_mode() == WorkspaceViewMode::Terminal
                || keep_paths.contains(active_path))
        {
            keep_paths.insert(active_path.to_string());
        }
        self.retained_terminal_session_paths
            .retain(|session_path| keep_paths.contains(session_path));
        self.terminal_mount_epochs
            .retain(|session_path, _| keep_paths.contains(session_path));
        for session_path in keep_paths {
            self.retain_terminal_session_path(&session_path);
        }
    }
    fn terminal_session_has_current_render_state(&self, session_path: &str) -> bool {
        self.terminal_session_host_id(session_path).is_some()
            || self.terminal_resume_ready_paths.contains(session_path)
            || self.terminal_session_has_ready_attempt(session_path)
            || self
                .terminal_bootstrap_lease_by_session
                .contains_key(session_path)
            || self
                .terminal_bootstrap_owner_by_session
                .contains_key(session_path)
    }
    fn request_background_copy_scan_if_unscheduled(&mut self) {
        if self.next_background_copy_scan_after_ms == 0 {
            self.next_background_copy_scan_after_ms = current_millis();
        }
    }
    fn reset_passive_copy_generation_gate(&mut self) {
        let suspended = !implicit_copy_generation_enabled();
        self.passive_copy_suspended = suspended;
        PASSIVE_COPY_SUSPENDED.store(suspended, Ordering::Relaxed);
    }
    fn bump_terminal_mount_epoch_for_session(&mut self, session_path: &str) -> u64 {
        // DIAGNOSTIC (hot-switch latency #milestone): every remount goes through
        // an epoch bump. Log the hot-reveal sub-conditions so we can see WHY the
        // switch-back didn't take the reveal path. See
        // [[finding-hot-switch-latency-remount]]. Cheap + one event per bump.
        if std::env::var("YGGTERM_TRACE_HOT_REVEAL").is_ok()
            && let Ok(home) = resolve_yggterm_home()
        {
            let had_host_epoch = self.terminal_mount_epochs.contains_key(session_path);
            append_trace_event(
                &home,
                "ui",
                "hot_reveal_diag",
                "mount_epoch_bump",
                json!({
                    "session_path": session_path,
                    "prev_epoch": self.terminal_mount_epochs.get(session_path).copied(),
                    "had_host_epoch": had_host_epoch,
                    "was_ever_ready": self.terminal_session_was_ever_ready(session_path),
                    "reached_ready_set": self.terminal_sessions_reached_ready.contains(session_path),
                    "daemon_owns_runtime": self.daemon_owns_session_runtime(session_path),
                    "attach_in_flight": self.terminal_attach_in_flight.contains(session_path),
                    "in_reveal_grace": self.terminal_session_in_reveal_grace(session_path),
                    "retained": self.retained_terminal_session_paths.contains(session_path),
                    "empty_surface": self.latest_terminal_open_attempt_has_empty_surface(session_path),
                    "is_retained_live": self.terminal_session_is_retained_live(session_path),
                }),
            );
        }
        let epoch = self
            .terminal_mount_epochs
            .entry(session_path.to_string())
            .or_insert(0);
        *epoch = epoch.saturating_add(1).max(1);
        *epoch
    }
    /// Decide the mount epoch when (re)opening the ACTIVE session's terminal
    /// host. Returns `(epoch, reused_live_host, settled_futile)`.
    ///
    /// `reused_live_host` reuses the existing live host with no epoch bump (the
    /// hot/reveal path). `settled_futile` ALSO reuses the existing host with no
    /// bump, but for a different reason: the session is NOT retained-live yet
    /// has been cold-remounted repeatedly without ever settling, so further
    /// cold remounts are futile churn that just re-seed the viewport on every
    /// periodic open re-assert — the idle "blink" loop. A live session whose
    /// open-attempt never latches Ready never satisfies
    /// `terminal_session_is_retained_live`, so without this cap each re-assert
    /// bumps the epoch and tears the host down before any attempt can complete.
    /// Reusing the existing host lets such a session finally settle. A healthy
    /// reveal reaches Ready well within the futile window and clears the streak,
    /// so it always takes the cold-mount path on first reveal. The
    /// retained_fault_recovery path bumps the epoch directly (not through here),
    /// so genuine fault recovery is unaffected. See
    /// [[finding-cc-blink-dead-session-remount-loop]].
    fn resolve_active_open_mount_epoch(
        &mut self,
        session_path: &str,
        now_ms: u64,
    ) -> (u64, bool, bool) {
        if self.terminal_session_is_retained_live(session_path) {
            self.terminal_cold_remount_count.remove(session_path);
            self.terminal_cold_remount_since_ms.remove(session_path);
            return (self.retain_terminal_session_path(session_path), true, false);
        }
        let already_mounted = self.terminal_session_host_id(session_path).is_some();
        // Idle "blink" loop: a periodic open re-assert (the 15s background refresh)
        // of a session that is ALREADY mounted, previously reached Ready, and whose
        // daemon still owns the PTY must REVEAL the existing host (stable epoch),
        // not cold-remount it — a cold remount re-seeds the viewport = a visible
        // flash every 15s (measured: open-gaps clustered at exactly 15.0s, each a
        // bootstrap_reset -> reconstruct -> snapshot_restore -> repaint). The
        // retained_live fast-path above clears this only within the reveal-grace
        // window; once that expires a healthy backgrounded/re-asserted host drops
        // out of retained_live yet stays perfectly revealable. This path is ONLY
        // the periodic re-assert — genuine fault recovery bumps the epoch directly
        // elsewhere — so reusing the host here cannot suppress a real remount.
        // See [[finding-cc-blink-dead-session-remount-loop]].
        if already_mounted
            && self.terminal_session_was_ever_ready(session_path)
            && self.daemon_owns_session_runtime(session_path)
            && !self.terminal_attach_in_flight.contains(session_path)
        {
            self.terminal_cold_remount_count.remove(session_path);
            self.terminal_cold_remount_since_ms.remove(session_path);
            return (self.retain_terminal_session_path(session_path), true, false);
        }
        // A mount whose attach is STILL SETTLING is not a cold-remount
        // candidate. The re-assert that lands right after an open request
        // completes (the `latest_open_request_id` bump re-runs the mount-key
        // effect) used to fall through here — the reveal path above requires
        // `was_ever_ready`, which a session being born cannot satisfy — and
        // tear down the in-flight mount ~0.6s after it was constructed:
        // measured as epoch N then N+1 on virtually every session birth and
        // cross-pathway switch (the "each reveal constructs twice" blink).
        // Genuine fault recovery bumps the epoch directly, never through this
        // resolver, so reusing the settling host here cannot mask a fault; a
        // hung attach ages past its recovery budget and the next re-assert
        // cold-remounts normally.
        if already_mounted
            && self.terminal_attach_in_flight.contains(session_path)
            && self
                .latest_terminal_open_attempt_for_path(session_path)
                .is_some_and(|attempt| {
                    attempt.latched_failure_reason.is_none()
                        && matches!(
                            attempt.state,
                            TerminalOpenAttemptState::Pending
                                | TerminalOpenAttemptState::Recovering
                        )
                        && now_ms.saturating_sub(attempt.started_at_ms)
                            < retained_fault_recovery_rearm_after_ms(attempt)
                })
        {
            return (self.retain_terminal_session_path(session_path), true, false);
        }
        let count = self
            .terminal_cold_remount_count
            .get(session_path)
            .copied()
            .unwrap_or(0);
        let since_ms = *self
            .terminal_cold_remount_since_ms
            .entry(session_path.to_string())
            .or_insert(now_ms);
        if already_mounted
            && count >= TERMINAL_FUTILE_COLD_REMOUNT_COUNT
            && now_ms.saturating_sub(since_ms) >= TERMINAL_FUTILE_COLD_REMOUNT_MS
        {
            return (self.retain_terminal_session_path(session_path), false, true);
        }
        self.terminal_cold_remount_count
            .insert(session_path.to_string(), count.saturating_add(1));
        (
            self.bump_terminal_mount_epoch_for_session(session_path),
            false,
            false,
        )
    }
    fn terminal_session_host_id(&self, session_path: &str) -> Option<String> {
        self.terminal_mount_epochs
            .get(session_path)
            .copied()
            .map(|epoch| terminal_mount_host_id(session_path, epoch))
    }
    fn terminal_session_uses_remote_runtime(&self, session_path: &str) -> bool {
        if session_path_names_remote_runtime_by_scheme(session_path) {
            return true;
        }
        if self.server.active_session_path() == Some(session_path)
            && self
                .server
                .active_session()
                .is_some_and(|session| session.source == SessionSource::LiveSsh)
        {
            return true;
        }
        self.server.live_sessions().iter().any(|session| {
            session.session_path == session_path && session.source == SessionSource::LiveSsh
        }) || self
            .cached_hot_session_views
            .get(session_path)
            .is_some_and(|session| session.source == SessionSource::LiveSsh)
    }
    fn active_remote_terminal_session_pending_runtime_launch(&self, session_path: &str) -> bool {
        self.server.active_view_mode() == WorkspaceViewMode::Terminal
            && self.server.active_session_path() == Some(session_path)
            && self.terminal_session_uses_remote_runtime(session_path)
            && self.server.active_session().is_some_and(|session| {
                matches!(
                    session.launch_phase,
                    yggterm_server::TerminalLaunchPhase::Queued
                        | yggterm_server::TerminalLaunchPhase::BridgePending
                        | yggterm_server::TerminalLaunchPhase::RemoteBootstrap
                )
            })
    }
    /// Sticky "this host was hot (reached ready) at least once and isn't a dead
    /// shell". Combines the per-life sticky set with the latest-attempt history
    /// so hot-reveal recognition survives a cold-recovery attempt superseding
    /// the original ready attempt.
    fn terminal_session_was_ever_ready(&self, session_path: &str) -> bool {
        self.terminal_sessions_reached_ready.contains(session_path)
            || self.terminal_session_has_ready_history(session_path)
    }
    /// True while a freshly-revealed retained host is inside its reveal grace
    /// window (opened on switch activation). See `terminal_reveal_grace_until_ms`.
    fn terminal_session_in_reveal_grace(&self, session_path: &str) -> bool {
        self.terminal_reveal_grace_until_ms
            .get(session_path)
            .copied()
            .is_some_and(|until_ms| current_millis() < until_ms)
    }
    /// A host that reached ready, still holds its mount epoch, and whose daemon
    /// still owns the PTY can be REVEALED on switch-back (reuse the live host,
    /// no remount) — independent of a stale `attach_in_flight` marker left by a
    /// prior open. This is the single predicate both the render's reveal
    /// recognition (`hot_reveal_reusable`) and the open-path re-arm use, so they
    /// can never disagree about whether a switch is a reveal or a remount.
    /// See [[finding-hot-switch-latency-remount]].
    fn terminal_session_host_reusable_for_reveal(&self, session_path: &str) -> bool {
        self.terminal_session_host_id(session_path).is_some()
            && self.terminal_session_was_ever_ready(session_path)
            && self.daemon_owns_session_runtime(session_path)
    }
    // ---- Split-view groups ([[campaign-split-view-groups]]) ----
    //
    // The `split_groups` field is the SSOT. Everything below DERIVES from it;
    // there is no per-session split flag. `active_session_path` keeps its exact
    // single-focus meaning — it names the FOCUSED pane. A group merely declares
    // which sessions are co-visible with it. That split of duties is what lets
    // the whole delicate single-active-session render machinery stay intact:
    // the focused pane behaves exactly as today, and only two predicates widen
    // to cover its co-visible siblings (`terminal_active_visible_for_session`
    // for reads/recovery, and the viewport's pane-rect layout).

    /// The group a session belongs to, if any. A session is in at most one
    /// group (enforced at creation: a member already in a group is refused).
    fn split_group_for_session(&self, session_path: &str) -> Option<&SplitGroup> {
        self.split_groups
            .iter()
            .find(|group| group.contains(session_path))
    }

    /// The group that owns the currently active (focused) session — i.e. the
    /// split is the active surface. `None` when the active surface is a lone
    /// session or not a terminal. This is the gate that turns the viewport into
    /// a multi-pane surface.
    fn active_split_group(&self) -> Option<&SplitGroup> {
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal {
            return None;
        }
        let active = self.server.active_session_path()?;
        self.split_group_for_session(active)
    }

    /// Is `session_path` a co-visible pane of the ACTIVE split group? True for
    /// the focused pane and its siblings alike. Promotes a retained host into
    /// the VISIBLE tier (full reads, foreground recovery — never a background
    /// host) so a split never reintroduces the killed blink class.
    fn session_is_visible_split_pane(&self, session_path: &str) -> bool {
        self.active_split_group()
            .is_some_and(|group| group.contains(session_path))
    }

    fn split_group_by_id_mut(&mut self, group_id: &str) -> Option<&mut SplitGroup> {
        self.split_groups
            .iter_mut()
            .find(|group| group.group_id == group_id)
    }

    /// Persist the split-group SSOT into settings and write to disk. Called
    /// after every structural or ratio change so a built workspace survives a
    /// restart ([[campaign-split-view-groups]] persistence).
    fn persist_split_groups(&mut self) {
        self.settings.split_groups = self.split_groups.clone();
        self.persist_settings();
    }

    /// Drop groups whose members no longer resolve to a known session (a member
    /// was closed elsewhere, or the persisted file references a session this
    /// host does not have). A group is kept only while it still binds ≥2 live
    /// members; a group collapsing to one member is dissolved back to a lone
    /// session (its survivor's pre-group keep-alive restored). Returns true if
    /// anything changed.
    fn prune_stale_split_groups(&mut self, known_paths: &HashSet<String>) -> bool {
        if self.split_groups.is_empty() {
            return false;
        }
        let mut changed = false;
        let mut restore: Vec<(String, bool)> = Vec::new();
        self.split_groups.retain_mut(|group| {
            let before = group.members.len();
            group
                .members
                .retain(|member| known_paths.contains(member.session.as_str()));
            if group.members.len() != before {
                changed = true;
                if group.active_pane >= group.members.len() {
                    group.active_pane = group.members.len().saturating_sub(1);
                }
            }
            if group.members.len() >= 2 {
                true
            } else {
                // Dissolving: hand back the survivor's pre-group keep-alive.
                for member in &group.members {
                    if let Some(prior) = group.prior_keep_alive.get(&member.session) {
                        restore.push((member.session.clone(), *prior));
                    }
                }
                changed = true;
                false
            }
        });
        for (path, prior) in restore {
            // Only step DOWN — never revoke a keep-alive the daemon still holds
            // for another reason; grouping only ever forced it on.
            if !prior {
                mark_live_session_keep_alive_locally(self, &path, false);
            }
        }
        if changed {
            self.persist_split_groups();
        }
        changed
    }

    /// Drop split panes PINNED to a web view that no longer exists — the tab
    /// was closed or the whole surface retired ([[campaign-libyggterm]] Phase
    /// 3). Terminal-view panes are untouched (session liveness is
    /// `prune_stale_split_groups`' job). A group collapsing below 2 panes
    /// dissolves; keep-alive restore mirrors the stale-prune path (local-only
    /// step-down — grouping only ever forced keep-alive ON).
    fn prune_web_view_panes(&mut self) {
        if self.split_groups.is_empty() {
            return;
        }
        let live_web_tabs: HashMap<String, Vec<u64>> = self
            .web_surfaces
            .iter()
            .filter(|(_, surface)| surface.picker.is_none())
            .map(|(path, surface)| {
                (
                    path.clone(),
                    surface.tabs.iter().map(|tab| tab.id).collect(),
                )
            })
            .collect();
        let mut changed = false;
        let mut restore: Vec<(String, bool)> = Vec::new();
        self.split_groups.retain_mut(|group| {
            let before = group.members.len();
            group.members.retain(|member| match &member.view {
                SplitMemberView::Web { tab } => live_web_tabs
                    .get(&member.session)
                    .is_some_and(|tabs| tabs.contains(tab)),
                _ => true,
            });
            if group.members.len() != before {
                changed = true;
                if group.active_pane >= group.members.len() {
                    group.active_pane = group.members.len().saturating_sub(1);
                }
            }
            if group.members.len() >= 2 {
                true
            } else {
                for member in group.member_sessions() {
                    if let Some(prior) = group.prior_keep_alive.get(member) {
                        restore.push((member.to_string(), *prior));
                    }
                }
                changed = true;
                false
            }
        });
        for (path, prior) in restore {
            if !prior {
                mark_live_session_keep_alive_locally(self, &path, false);
            }
        }
        if changed {
            self.persist_split_groups();
        }
    }

    /// Prune split groups against the sessions this GUI currently knows about.
    /// The "known" set is generous on purpose — live + retained + cached-hot +
    /// active — so a member merely absent from ONE partial snapshot is not
    /// mistaken for a closed session (the transient-gap false-prune the render
    /// rules warn about). Only a member gone from ALL of them is dropped.
    fn prune_split_groups_against_live(&mut self) {
        if self.split_groups.is_empty() {
            return;
        }
        let mut known: HashSet<String> = HashSet::new();
        for session in self.server.live_sessions() {
            known.insert(normalize_live_session_path(&session.session_path));
            known.insert(session.session_path.clone());
        }
        for path in &self.retained_terminal_session_paths {
            known.insert(path.clone());
        }
        for path in self.cached_hot_session_views.keys() {
            known.insert(path.clone());
        }
        if let Some(active) = self.server.active_session_path() {
            known.insert(active.to_string());
        }
        self.prune_stale_split_groups(&known);
        // Pinned web panes are SESSION-LIFETIME (tab restore re-mints ids, so
        // a persisted pin has no durable referent): a pin whose surface or
        // tab is gone — including across a GUI restart — dissolves here.
        self.prune_web_view_panes();
    }

    fn terminal_session_is_retained_live(&self, session_path: &str) -> bool {
        let retained = self.retained_terminal_session_paths.contains(session_path);
        let active_remote_terminal_session = self.server.active_view_mode()
            == WorkspaceViewMode::Terminal
            && self.server.active_session_path() == Some(session_path)
            && self.terminal_session_uses_remote_runtime(session_path);
        let non_prompt_recovering_attempt = self
            .latest_terminal_open_attempt_for_path(session_path)
            .is_some_and(|attempt| {
                matches!(attempt.state, TerminalOpenAttemptState::Recovering)
                    && remote_retained_surface_fault_should_invalidate(
                        attempt.last_observed_reason.as_deref(),
                    )
            });
        // During a reveal grace, a "recovering" attempt is the spurious one a
        // prior switch left behind (or one the watchdog raced in on the benign
        // empty-surface signal). If the host previously reached ready and the
        // daemon still owns the PTY, treat the switch-back as a REVEAL and let
        // the host be reused, rather than honoring that stale recovery.
        let reveal_eligible = self.terminal_session_in_reveal_grace(session_path)
            && self.terminal_session_was_ever_ready(session_path)
            && self.daemon_owns_session_runtime(session_path)
            && !self.terminal_attach_in_flight.contains(session_path);
        let active_remote_recovering_runtime = active_remote_terminal_session
            && self.active_remote_terminal_session_pending_runtime_launch(session_path);
        if (non_prompt_recovering_attempt && !reveal_eligible) || active_remote_recovering_runtime {
            return false;
        }
        let bootstrap_in_progress = self
            .terminal_bootstrap_lease_by_session
            .contains_key(session_path)
            || self
                .terminal_bootstrap_owner_by_session
                .contains_key(session_path);
        let has_host_epoch = self.terminal_session_host_id(session_path).is_some();
        // HOT reveal on switch-back: a retained host that previously reached
        // ready and whose daemon PTY still exists can be revealed/reused
        // (same epoch, no remount) instead of cold-remounted. While a host is
        // HIDDEN its transient `resume_ready`/ready-attempt flags clear (or the
        // attempt gains a spurious "xterm surface is empty" problem), which used
        // to make the two clauses below false on every switch-back -> a cold
        // remount + retained_fault_recovery that re-pulled scrollback. Unlike
        // those flags, `ready_history` is STICKY (set once the host reached
        // ready, survives hide) and only true when the host is not
        // latched-failed; gating on `daemon_owns_session_runtime` ensures we
        // never reveal a host whose PTY is actually gone (that still falls
        // through to recovery). See memory
        // [[followups-switch-hotness-update-friction]].
        // A host that reached ready, still has its mount epoch, and whose
        // daemon still owns the PTY is REUSABLE on switch-back — reveal it.
        // We deliberately do NOT require `!attach_in_flight` here: an open/
        // switch sets `attach_in_flight` for the target, and a prior attach's
        // flag lingers across hide (it is retained because the session is in
        // the keep-set), so requiring its absence made every switch-back read
        // as "not reusable" -> cold remount (the ~1s js-init that dominated
        // hot-switch latency). `daemon_owns_session_runtime` already guarantees
        // the PTY is live, so a stale in-flight marker must not block the
        // reveal. See [[finding-hot-switch-latency-remount]] (#milestone).
        let hot_reveal_reusable = self.terminal_session_host_reusable_for_reveal(session_path);
        retained
            && (((self.terminal_resume_ready_paths.contains(session_path)
                || self.terminal_session_has_ready_attempt(session_path))
                && !self.terminal_attach_in_flight.contains(session_path))
                || (!active_remote_terminal_session && bootstrap_in_progress && has_host_epoch)
                || hot_reveal_reusable)
    }
    fn rearm_unready_remote_terminal_bootstrap_for_open(&mut self, session_path: &str) -> bool {
        if !self.terminal_session_uses_remote_runtime(session_path) {
            return false;
        }
        let active_remote_recovering_runtime =
            self.active_remote_terminal_session_pending_runtime_launch(session_path);
        let has_pending_attach_state = self.terminal_attach_in_flight.contains(session_path)
            || self
                .terminal_bootstrap_owner_by_session
                .contains_key(session_path)
            || self
                .terminal_bootstrap_lease_by_session
                .contains_key(session_path);
        // Reuse a retained, daemon-owned, previously-ready host on switch-back
        // instead of remounting it. `is_retained_live` now recognizes such a
        // host even while a stale `attach_in_flight` marker lingers; drop that
        // stale marker so the reveal path engages cleanly (no epoch bump, no
        // ~1s remount). See [[finding-hot-switch-latency-remount]] (#milestone).
        if self.terminal_session_host_reusable_for_reveal(session_path) {
            // Reusable retained host: drop any stale in-flight attach marker so
            // the reveal path engages cleanly, and DON'T remount (no epoch bump).
            if has_pending_attach_state {
                self.terminal_attach_in_flight.remove(session_path);
            }
            return false;
        }
        if (self.terminal_session_is_retained_live(session_path) && !has_pending_attach_state)
            || (!has_pending_attach_state
                && !active_remote_recovering_runtime
                && self.terminal_session_has_ready_attempt(session_path))
        {
            return false;
        }
        let had_inflight = self.terminal_attach_in_flight.remove(session_path);
        let had_owner = self
            .terminal_bootstrap_owner_by_session
            .remove(session_path)
            .is_some();
        let had_lease = self
            .terminal_bootstrap_lease_by_session
            .remove(session_path)
            .is_some();
        let had_ready = self.terminal_resume_ready_paths.remove(session_path);
        let had_host = self.terminal_session_host_id(session_path).is_some();
        if !(had_inflight || had_owner || had_lease || had_ready || had_host) {
            return false;
        }
        let _ = self.bump_terminal_mount_epoch_for_session(session_path);
        if self.server.active_view_mode() == WorkspaceViewMode::Terminal
            && self.server.active_session_path() == Some(session_path)
        {
            self.active_terminal_host_id = self.terminal_session_host_id(session_path);
        }
        true
    }
    fn rearm_active_remote_runtime_recovery_after_snapshot(&mut self) -> bool {
        let Some(active_path) = self.server.active_session_path().map(str::to_string) else {
            return false;
        };
        if !self.active_remote_terminal_session_pending_runtime_launch(&active_path) {
            return false;
        }
        // Stale-phase blink loop: `launch_phase` can stick at RemoteBootstrap on
        // a fully-usable remote CC session (finding-cold-cc-reattach-phase-stuck),
        // and this rearm runs after EVERY snapshot apply (15s refresh). Acting on
        // the stale phase label alone cold-remounted a healthy active session
        // every 15s forever (observed live: mount epoch 12 -> 39+ at exactly
        // 15.3s cadence, each a bootstrap_reset + re-seed flash, while the
        // faithful pixel showed a perfectly rendered session). The PTY-ownership
        // truth outranks the phase label: a mounted host that reached ready and
        // whose PTY the daemon AFFIRMATIVELY owns (per the latest runtime status
        // — a missing status stays on the recovery path, unlike the fail-open
        // reveal predicate) has nothing for a remount to recover. A genuine
        // pending launch (PTY gone / never ready) still falls through.
        let daemon_affirmatively_owns_runtime =
            self.latest_runtime_status.as_ref().is_some_and(|status| {
                let runtime_key = self.server.terminal_runtime_key_for_path(&active_path);
                status
                    .owned_terminal_session_keys
                    .iter()
                    .chain(status.preserved_terminal_owner_keys.iter())
                    .any(|key| key == &runtime_key)
            });
        if daemon_affirmatively_owns_runtime
            && self.terminal_session_host_id(&active_path).is_some()
            && self.terminal_session_was_ever_ready(&active_path)
        {
            return false;
        }
        self.invalidate_retained_remote_non_prompt_surface(&active_path, None)
    }
    fn terminal_session_should_render_retained(&self, session_path: &str) -> bool {
        self.retained_terminal_session_paths.contains(session_path)
            && (self.server.session_supports_terminal(session_path)
                || self.cached_hot_session_views.contains_key(session_path)
                || self.server.live_sessions().iter().any(|session| {
                    session.session_path == session_path
                        && is_live_local_stored_codex_terminal_session(session)
                }))
    }
    fn terminal_session_has_ready_attempt(&self, session_path: &str) -> bool {
        self.latest_terminal_open_attempt_for_path(session_path)
            .is_some_and(|attempt| {
                matches!(attempt.state, TerminalOpenAttemptState::Ready)
                    && attempt.latched_failure_reason.is_none()
                    && (attempt.observations == 0
                        || (attempt.last_observed_ready && attempt.last_surface_problem.is_none()))
            })
    }
    fn terminal_session_has_observed_ready_attempt(&self, session_path: &str) -> bool {
        self.latest_terminal_open_attempt_for_path(session_path)
            .is_some_and(|attempt| {
                matches!(attempt.state, TerminalOpenAttemptState::Ready)
                    && attempt.latched_failure_reason.is_none()
                    && attempt.observations > 0
                    && attempt.last_observed_ready
                    && attempt.last_surface_problem.is_none()
            })
    }
    fn terminal_session_has_ready_history(&self, session_path: &str) -> bool {
        self.latest_terminal_open_attempt_for_path(session_path)
            .is_some_and(|attempt| {
                attempt.ready_at_ms.is_some() && attempt.latched_failure_reason.is_none()
            })
    }
    fn terminal_session_has_meaningful_resume_output(&self, session_path: &str) -> bool {
        self.latest_terminal_open_attempt_for_path(session_path)
            .is_some_and(|attempt| {
                attempt.first_meaningful_output_at_ms.is_some()
                    && attempt.latched_failure_reason.is_none()
                    && attempt.last_surface_problem.is_none()
            })
    }
    fn terminal_session_should_suppress_initial_resume_notice(&self, session_path: &str) -> bool {
        self.terminal_resume_ready_paths.contains(session_path)
            || self.terminal_session_has_ready_history(session_path)
            || self.terminal_session_has_meaningful_resume_output(session_path)
    }
    fn terminal_session_is_active_ready_focus_target(&self, session_path: &str) -> bool {
        self.server.active_view_mode() == WorkspaceViewMode::Terminal
            && self.server.active_session_path() == Some(session_path)
            && self.server.session_supports_terminal(session_path)
            && !self.active_remote_terminal_session_pending_runtime_launch(session_path)
            && !self.terminal_attach_in_flight.contains(session_path)
            && (self.terminal_resume_ready_paths.contains(session_path)
                || self.terminal_session_has_ready_attempt(session_path))
    }
    fn terminal_session_ready_for_daemon_retained_replay(&self, session_path: &str) -> bool {
        let resume_job_key = terminal_resume_notification_job_key(session_path);
        self.terminal_session_has_observed_ready_attempt(session_path)
            && !self.terminal_attach_in_flight.contains(session_path)
            && !self.notifications.iter().any(|notification| {
                notification.job_key.as_deref() == Some(resume_job_key.as_str())
            })
    }
    fn retained_fault_invalidation_ready_settle_suppression(
        &self,
        session_path: &str,
        fault_reason: Option<&str>,
        now_ms: u64,
    ) -> Option<(String, u64)> {
        if !retained_fault_reason_can_wait_for_ready_settle(fault_reason) {
            return None;
        }
        if !self.terminal_resume_ready_paths.contains(session_path)
            || self.terminal_attach_in_flight.contains(session_path)
        {
            return None;
        }
        let attempt = self.latest_terminal_open_attempt_for_path(session_path)?;
        if attempt.source != "retained_fault_recovery"
            || !matches!(attempt.state, TerminalOpenAttemptState::Ready)
            || attempt.latched_failure_reason.is_some()
            || attempt.last_surface_problem.is_some()
        {
            return None;
        }
        let ready_at_ms = attempt.ready_at_ms?;
        let ready_elapsed_ms = now_ms.saturating_sub(ready_at_ms);
        if ready_elapsed_ms > RETAINED_FAULT_READY_SETTLE_GRACE_MS {
            return None;
        }
        Some((attempt.attempt_id.clone(), ready_elapsed_ms))
    }
    /// Per [[spec-xterm-gating-ux]]: a gate is unsatisfiable if the resource
    /// behind it is GONE. `owned_terminal_session_keys` is the daemon's
    /// manifest of PTYs it actually OWNS right now. A session sitting in
    /// `preserved_terminal_owner_keys` without being owned is a leftover
    /// pointing at a previous-daemon PID that may or may not still exist —
    /// the live-guihost failure mode where 13 of 15 sessions were stuck because
    /// the previous owner daemon died. Treat ownership as the source of
    /// truth; preserved-only state is not enough to keep retrying.
    fn daemon_owns_session_runtime(&self, session_path: &str) -> bool {
        let Some(runtime_status) = self.latest_runtime_status.as_ref() else {
            // Without a runtime status snapshot we can't prove the PTY is
            // gone — fall through to the existing recovery flow.
            return true;
        };
        let runtime_key = self.server.terminal_runtime_key_for_path(session_path);
        // The daemon "owns" a runtime for reveal purposes if it holds the PTY
        // directly (owned) OR proxies it through a live preserved-owner (an
        // older daemon that survived a hot-update swap). After a daemon swap,
        // re-resumed sessions land in preserved_terminal_owner_keys, not owned;
        // checking only `owned` made hot_reveal_reusable false for those, so
        // every switch-back cold-REMOUNTED (epoch churn / ~30s recovery / DOM
        // leak on big sessions like samplenotes) instead of revealing. Both lists
        // reflect a LIVE PTY, so either qualifies for a same-epoch reveal.
        // See [[finding-hot-switch-latency-remount]] / [[bug-class-old-daemon-never-retires]].
        runtime_status
            .owned_terminal_session_keys
            .iter()
            .chain(runtime_status.preserved_terminal_owner_keys.iter())
            .any(|key| key == &runtime_key)
    }
    /// Returns true if the GUI has spawned enough retained_fault_recovery
    /// attempts for this session that further attempts are clearly futile.
    /// Used as the precondition before latching — never latch on the first
    /// fault detection, because the daemon may simply not have caught up yet.
    /// We count distinct RFR attempts (not just Failed-state ones) because
    /// the recovery state machine often replaces a stuck attempt before it
    /// transitions to Failed, so a strict "must reach Failed" check never
    /// fires in the runaway-loop case the spec is targeting.
    fn retained_fault_recovery_has_prior_failure(&self, session_path: &str) -> bool {
        const FUTILE_ATTEMPT_THRESHOLD: usize = 3;
        let rfr_attempts = self
            .terminal_open_attempts
            .values()
            .filter(|attempt| {
                attempt.session_path == session_path
                    && attempt.source == "retained_fault_recovery"
            })
            .count();
        rfr_attempts >= FUTILE_ATTEMPT_THRESHOLD
    }
    fn latch_retained_fault_recovery_lost_pty(&mut self, session_path: &str, reason: &str) {
        if !self
            .retained_fault_recovery_lost_pty_sessions
            .insert(session_path.to_string())
        {
            // Already latched — don't re-emit telemetry per poll.
            return;
        }
        // Stop the toast loop: replace the "Restoring..." progress toast with
        // a one-shot info-tone "Session lost" so the user sees a stable
        // state instead of flicker.
        let job_key = terminal_resume_notification_job_key(session_path);
        self.clear_job_notification(&job_key);
        // End-of-loop reading for the user-gated-time histogram.
        let loop_duration_ms = self.finish_retained_fault_recovery_loop(session_path, "latched");
        self.record_terminal_contract_telemetry(
            "retained_fault_recovery_lost_pty_latched",
            "warn",
            session_path,
            reason,
            json!({
                "active_session_path": self.server.active_session_path(),
                "runtime_key": self.server.terminal_runtime_key_for_path(session_path),
                "loop_duration_ms": loop_duration_ms,
            }),
        );
    }
    /// Cleared on user-initiated open so a future fault gets a fresh shot.
    fn clear_retained_fault_recovery_lost_pty_latch(&mut self, session_path: &str) {
        self.retained_fault_recovery_lost_pty_sessions
            .remove(session_path);
    }
    /// HOT-tier pre-attach per [[spec-xterm-gating-ux]] Phase 2: returns
    /// the next batch of live keep-alive codex sessions to background-warm
    /// so that the user's next click finds them daemon-owned (HOT). Picks
    /// top-N most-recently-used in live_session_order that are NOT already
    /// owned, NOT currently warming, NOT in cooldown, and NOT the active
    /// session itself (which is already being attached). Updates internal
    /// in-flight + cooldown bookkeeping for the returned set; callers must
    /// follow up by issuing TerminalEnsure RPCs to the daemon.
    ///
    /// Per the spec's hot/cold philosophy: when the yggterm client window
    /// is in background, the user isn't paying attention to switch
    /// latency — we should NOT burn SSH/CPU/network keeping sessions
    /// HOT. Returning empty here lets sessions naturally cool (the
    /// daemon's idle-shutdown will release them after its own timeout),
    /// then the next foreground gesture triggers re-warming on the very
    /// next 5s tick. Same gating applies to `app_control_backgrounded`
    /// which is the explicit headless-mode background signal.
    fn tick_hot_warmer(&mut self, now_ms: u64) -> Vec<String> {
        if !self.effective_window_focused()
            || (self.app_control_backgrounded && !self.app_control_force_foreground)
        {
            return Vec::new();
        }
        if self.next_hot_warm_check_at_ms > now_ms {
            return Vec::new();
        }
        self.next_hot_warm_check_at_ms = now_ms.saturating_add(HOT_WARM_CHECK_INTERVAL_MS);
        let available = HOT_WARM_MAX_CONCURRENT.saturating_sub(self.hot_warming_in_flight.len());
        if available == 0 {
            return Vec::new();
        }
        // Snapshot the keep-alive Codex sessions in live order, then filter.
        // live_sessions() returns most-recently-used first.
        let live_sessions = self.server.live_sessions().clone();
        let active_path = self.server.active_session_path().map(str::to_string);
        let mut candidates: Vec<String> = Vec::new();
        for session in live_sessions.iter().take(HOT_WARM_TOP_N * 4) {
            if candidates.len() >= available {
                break;
            }
            if session.kind != SessionKind::Codex {
                continue;
            }
            if !live_session_keep_alive(&session) {
                continue;
            }
            let path = &session.session_path;
            if Some(path.as_str()) == active_path.as_deref() {
                continue;
            }
            if self.hot_warming_in_flight.contains(path) {
                continue;
            }
            if self.daemon_owns_session_runtime(path) {
                // Already HOT — no warm needed.
                continue;
            }
            if let Some(last_attempt) = self.last_hot_warm_attempt_at_ms.get(path)
                && now_ms.saturating_sub(*last_attempt) < HOT_WARM_COOLDOWN_MS
            {
                continue;
            }
            if self
                .retained_fault_recovery_lost_pty_sessions
                .contains(path)
            {
                // Latched sessions are intentionally NOT warmed — they were
                // failing for a reason.
                continue;
            }
            candidates.push(path.clone());
        }
        for path in &candidates {
            self.hot_warming_in_flight.insert(path.clone());
            self.last_hot_warm_attempt_at_ms.insert(path.clone(), now_ms);
        }
        candidates
    }
    /// Called when a background warm attempt completes (success or failure),
    /// releasing the in-flight slot so the next tick can warm a different
    /// candidate.
    fn finish_hot_warm(&mut self, session_path: &str) {
        self.hot_warming_in_flight.remove(session_path);
    }
    /// Per [[spec-xterm-gating-ux]] 3-tier model: closes the HOT or COLD
    /// switch-latency gate that was armed at user-driven open and records
    /// the duration into the appropriate histogram. Idempotent — only the
    /// first call for a given armed open records a sample (subsequent calls
    /// during the same attempt's ready-transitions are no-ops).
    fn finish_session_switch_gate(&mut self, session_path: &str) -> Option<u64> {
        let (armed_at_ms, tier) = self.switch_arm_ms_by_session.remove(session_path)?;
        let now_ms = current_millis();
        let elapsed_ms = now_ms.saturating_sub(armed_at_ms);
        let kind = match tier {
            SessionWarmthTier::Hot => GateKind::HotSessionSwitch,
            SessionWarmthTier::Cold => GateKind::ColdSessionSwitch,
        };
        self.xterm_gate_metrics
            .record_clear(kind, elapsed_ms, now_ms);
        Some(elapsed_ms)
    }
    /// Records the duration of an in-progress retained_fault_recovery loop
    /// into the [[spec-xterm-gating-ux]] gate-metrics histogram. Reason is
    /// trace-only; the histogram doesn't slice by it. Returns the elapsed
    /// duration so callers can include it in their telemetry payload.
    fn finish_retained_fault_recovery_loop(
        &mut self,
        session_path: &str,
        _reason: &'static str,
    ) -> Option<u64> {
        let armed_at_ms = self
            .retained_fault_recovery_loop_armed_at_ms
            .remove(session_path)?;
        let now_ms = current_millis();
        let elapsed_ms = now_ms.saturating_sub(armed_at_ms);
        self.xterm_gate_metrics.record_clear(
            GateKind::RetainedFaultRecoveryLoop,
            elapsed_ms,
            now_ms,
        );
        Some(elapsed_ms)
    }
    fn invalidate_retained_remote_non_prompt_surface(
        &mut self,
        session_path: &str,
        fault_reason: Option<&str>,
    ) -> bool {
        if !self.terminal_session_uses_remote_runtime(session_path) {
            return false;
        }
        let now_ms = current_millis();
        if let Some((attempt_id, ready_elapsed_ms)) = self
            .retained_fault_invalidation_ready_settle_suppression(
                session_path,
                fault_reason,
                now_ms,
            )
        {
            let reason = fault_reason.unwrap_or("retained fault during ready settle");
            let suppression_key = format!("{session_path}:{attempt_id}:{reason}");
            if self
                .last_retained_fault_invalidation_suppression_key
                .as_deref()
                != Some(suppression_key.as_str())
            {
                self.last_retained_fault_invalidation_suppression_key = Some(suppression_key);
                self.record_terminal_contract_telemetry(
                    "retained_fault_recovery_suppressed_after_ready",
                    "info",
                    session_path,
                    reason,
                    json!({
                        "attempt_id": attempt_id,
                        "ready_elapsed_ms": ready_elapsed_ms,
                        "settle_grace_ms": RETAINED_FAULT_READY_SETTLE_GRACE_MS,
                        "terminal_resume_ready": true,
                        "terminal_attach_in_flight": false,
                    }),
                );
            }
            return false;
        }
        // HOT switch-back reveal grace: a host that previously reached ready and
        // whose daemon still owns the PTY, reporting the benign empty-surface
        // signal within its reveal grace, is a transient repaint gap on reveal —
        // NOT a fault. Defer recovery so the existing host is revealed (scrollback
        // intact) instead of cold-remounted; the activation repaint fills it. If
        // it is STILL faulting after the grace expires, recovery proceeds
        // normally on the next tick. Genuine non-empty faults (transport errors,
        // identity mismatch, etc.) are unaffected — only the empty-surface reason
        // is graced. See [[followups-switch-hotness-update-friction]].
        let benign_reveal_empty_fault = fault_reason
            == Some(RETAINED_EMPTY_XTERM_SURFACE_PROBLEM)
            && self.terminal_session_in_reveal_grace(session_path)
            && self.terminal_session_was_ever_ready(session_path)
            && self.daemon_owns_session_runtime(session_path);
        if benign_reveal_empty_fault {
            let suppression_key = format!("{session_path}:reveal_grace");
            if self.last_retained_fault_invalidation_suppression_key.as_deref()
                != Some(suppression_key.as_str())
            {
                self.last_retained_fault_invalidation_suppression_key = Some(suppression_key);
                self.record_terminal_contract_telemetry(
                    "retained_fault_recovery_suppressed_during_reveal",
                    "info",
                    session_path,
                    "reveal grace: benign empty surface on revealed retained host",
                    json!({
                        "reveal_grace_ms": RETAINED_REVEAL_EMPTY_GRACE_MS,
                    }),
                );
            }
            return false;
        }
        self.last_retained_fault_invalidation_suppression_key = None;
        let recovery_already_in_flight = self.terminal_attach_in_flight.contains(session_path)
            && self
                .latest_terminal_open_attempt_for_path(session_path)
                .is_some_and(|attempt| {
                    attempt.source == "retained_fault_recovery"
                        && attempt.latched_failure_reason.is_none()
                        && matches!(
                            attempt.state,
                            TerminalOpenAttemptState::Pending
                                | TerminalOpenAttemptState::Recovering
                        )
                });
        if recovery_already_in_flight {
            return false;
        }
        // A YOUNG in-flight attempt is not a fault. The empty-surface signal
        // fires the moment the host mounts — before the ensure/attach has
        // delivered a single byte — so without this gate a user open was
        // invalidated ~0.7s in and cold-remounted, on virtually every reveal
        // (the "each reveal constructs twice" cross-pathway blink: measured
        // epoch N then N+1 within 0.3–2.2s on almost every mount pair).
        // While the latest attempt is still pending inside the SAME budget
        // the recovery watchdog itself grants a recovery attempt, the attempt
        // machinery owns the outcome; a genuinely hung attempt ages past the
        // budget and recovery proceeds on the next fault signal.
        let attempt_still_settling = self.terminal_attach_in_flight.contains(session_path)
            && self
                .latest_terminal_open_attempt_for_path(session_path)
                .is_some_and(|attempt| {
                    attempt.latched_failure_reason.is_none()
                        && matches!(
                            attempt.state,
                            TerminalOpenAttemptState::Pending
                                | TerminalOpenAttemptState::Recovering
                        )
                        && current_millis().saturating_sub(attempt.started_at_ms)
                            < retained_fault_recovery_rearm_after_ms(attempt)
                });
        if attempt_still_settling {
            let suppression_key = format!("{session_path}:attempt_settling");
            if self
                .last_retained_fault_invalidation_suppression_key
                .as_deref()
                != Some(suppression_key.as_str())
            {
                self.last_retained_fault_invalidation_suppression_key = Some(suppression_key);
                self.record_terminal_contract_telemetry(
                    "retained_fault_recovery_suppressed_attempt_settling",
                    "info",
                    session_path,
                    fault_reason.unwrap_or("fault while open attempt still settling"),
                    json!({}),
                );
            }
            return false;
        }
        // Per [[spec-xterm-gating-ux]]: stop the recovery loop when the gate
        // is unsatisfiable. If we've already failed once AND the daemon does
        // not have a PTY for this session, latch — no point creating a new
        // attempt that will fail identically.
        if self
            .retained_fault_recovery_lost_pty_sessions
            .contains(session_path)
        {
            return false;
        }
        let in_user_click_grace = self
            .retained_fault_recovery_latch_grace_until_ms
            .get(session_path)
            .copied()
            .is_some_and(|until_ms| current_millis() < until_ms);
        if !in_user_click_grace
            && self.retained_fault_recovery_has_prior_failure(session_path)
            && !self.daemon_owns_session_runtime(session_path)
        {
            let reason = fault_reason.unwrap_or(
                "retained fault recovery latched: daemon does not own this session's PTY",
            );
            self.latch_retained_fault_recovery_lost_pty(session_path, reason);
            return false;
        }
        let retained_before_fault = self.retained_terminal_session_paths.contains(session_path);
        let active_terminal_session = self.server.active_view_mode() == WorkspaceViewMode::Terminal
            && self.server.active_session_path() == Some(session_path);
        if !retained_before_fault && !active_terminal_session {
            return false;
        }
        self.retained_terminal_session_paths
            .insert(session_path.to_string());
        self.terminal_resume_ready_paths.remove(session_path);
        self.terminal_bootstrap_owner_by_session
            .remove(session_path);
        self.terminal_bootstrap_lease_by_session
            .remove(session_path);
        let _ = self.bump_terminal_mount_epoch_for_session(session_path);
        self.active_terminal_host_id = if self.server.active_view_mode()
            == WorkspaceViewMode::Terminal
            && self.server.active_session_path() == Some(session_path)
        {
            self.terminal_session_host_id(session_path)
        } else {
            None
        };
        self.terminal_attach_in_flight
            .insert(session_path.to_string());
        let previous_open_request_id = self
            .latest_terminal_open_attempt_for_path(session_path)
            .map(|attempt| attempt.open_request_id)
            .unwrap_or(self.latest_open_request_id);
        self.latest_open_request_id = self
            .latest_open_request_id
            .max(previous_open_request_id)
            .saturating_add(1);
        let request_id = format!("retained-fault-recovery-{}", current_millis());
        let open_request_id = self.latest_open_request_id;
        let attempt_id = self.begin_terminal_open_attempt(
            session_path,
            &request_id,
            open_request_id,
            "retained_fault_recovery",
        );
        if let Some(attempt) = self.terminal_open_attempts.get_mut(&attempt_id)
            && let Some(fault_reason) = fault_reason
        {
            attempt.last_observed_reason = Some(fault_reason.to_string());
            attempt.last_surface_problem = Some(fault_reason.to_string());
        }
        true
    }
    fn terminal_session_has_visual_resume_reveal(&self, session_path: &str) -> bool {
        self.terminal_resume_ready_paths.contains(session_path)
            || self.terminal_session_has_ready_attempt(session_path)
    }
    /// Is the resume gate currently refusing this row?
    ///
    /// Reads the same two facts `remote_resume_input_ready_for_snapshot` reads,
    /// so the deadline below can never disagree with the policy it nurses.
    fn remote_resume_input_gate_is_shut(&self, session_path: &str) -> bool {
        !self.terminal_session_has_visual_resume_reveal(session_path)
    }
    /// The one session the deadline may act on: the row the user is looking at
    /// and typing into. A background row's shut gate is not a symptom.
    fn input_gate_deadline_candidate(&self) -> Option<String> {
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal
            || !self.window_focused
            || self.app_control_backgrounded
        {
            return None;
        }
        self.server
            .active_session()
            .filter(|session| is_remote_resume_agent_session(session))
            .map(|session| session.session_path.clone())
    }
    /// Would a deadline tick write nothing at all?
    ///
    /// ⛔ The deadline loop runs once a second for the life of the process, and
    /// `Signal::with_mut` marks the shell dirty ON DROP whether or not the
    /// closure wrote anything. So an unconditional tick re-renders the whole
    /// app root every second forever, even on a GUI with no sessions in it —
    /// measured at rest, zero sessions: 1.67 renders/s with 95% of the renders
    /// reporting no watched field changed. This predicate lets the loop ask,
    /// under `peek()` (a read that neither subscribes nor dirties), whether the
    /// write is worth taking.
    ///
    /// It enumerates the arms of [`Self::tick_input_gate_deadline_for_candidate`]
    /// that only ever REMOVE, and answers `true` only when there is nothing
    /// left for them to remove:
    ///
    /// - no candidate ⇒ the arm clears both maps, inert once both are empty;
    /// - a candidate whose gate is **open** ⇒ the arm removes that path from
    ///   both maps, inert once both are empty.
    ///
    /// A candidate behind a **shut** gate inserts, so it answers `false` and
    /// the loop takes the write. ⚠ The first version of this predicate tested
    /// only the no-candidate arm, which is nearly worthless in practice: at
    /// rest the user is normally focused on a terminal row, so the candidate is
    /// `Some` and the open-gate arm is the one that actually runs. Locked by
    /// `an_inert_input_gate_tick_really_writes_nothing`.
    ///
    /// ⛔⛔ AND THE EMPTINESS TEST MUST BE PER-PATH, WHICH THE PROSE ABOVE HAS
    /// SAID SINCE IT WAS WRITTEN AND THE CODE DID NOT DO. It asked whether the
    /// maps were empty GLOBALLY, but the open-gate arm only ever removes the
    /// CANDIDATE's entry — so one stale entry left by a row that is no longer
    /// focused answered "not inert" on every tick, for a tick that would then
    /// remove nothing. That pinned a full app-root re-render at 1 Hz for the
    /// rest of the process, armed by a single past refusal.
    ///
    /// ⚠ And it self-heals in exactly the wrong direction, which is why an idle
    /// machine never shows it: the clear-all arm needs `candidate == None`,
    /// i.e. the terminal view left, the row switched to a non-agent one, or the
    /// **window unfocused**. So the 1 Hz render persists precisely while the
    /// owner is using the app and evaporates the moment he looks away.
    fn input_gate_deadline_tick_is_inert(&self) -> bool {
        match self.input_gate_deadline_candidate() {
            // The clear-all arm: inert once there is nothing left to clear.
            None => {
                self.input_gate_denied_since_ms.is_empty()
                    && self.input_gate_stuck_reported.is_empty()
            }
            Some(session_path) => {
                // A shut gate INSERTS (and may restore); never inert.
                if self.remote_resume_input_gate_is_shut(&session_path) {
                    return false;
                }
                // An open gate removes THIS path from both maps and nothing
                // else. Another path's leftovers are not work for this tick.
                !self.input_gate_denied_since_ms.contains_key(&session_path)
                    && !self.input_gate_stuck_reported.contains(&session_path)
            }
        }
    }
    /// The same question for the restore card the deadline tick refreshes
    /// alongside itself. Mirrors the early returns at the top of
    /// [`Self::refresh_terminal_restore_card`] — not in a terminal view, no
    /// active session, or no card under this session's job key means there is
    /// nothing to re-word or re-bar. A card that IS up answers `false` and
    /// takes the write, because its bar must keep moving.
    /// ⛔⛔ "A CARD IS UP" IS NOT THE SAME QUESTION AS "THE CARD WOULD CHANGE",
    /// AND ANSWERING THE FIRST COST A RENDER PER SECOND FOR THE CARD'S WHOLE
    /// LIFE. The old predicate said "not inert" whenever ANY card existed under
    /// this session's job key, so every long-lived card pinned a full app-root
    /// re-render at 1 Hz — including the ones that by construction never change,
    /// and including a card raised on a row whose surface is already broken,
    /// which is the worst moment to be spending renders.
    ///
    /// Only the stage-driven card ("Restoring Remote Terminal") re-words itself,
    /// and only that one carries an elapsed-seconds string that really does move
    /// every tick; its bar keeps ticking exactly as before. Every other card
    /// keeps its own wording and a stage-derived fraction, both stable between
    /// stages — so it now costs renders only when a stage actually advances.
    ///
    /// The comparison covers every field `upsert_job_notification` writes.
    /// `created_at_ms` is deliberately NOT among them: it is bumped on every
    /// call, so including it would make the predicate permanently false and
    /// restore the bug. Skipping the bump is safe because an unfinished card is
    /// `persistent` and exempt from the age filter, and the transition to
    /// finished flips `persistent` — which IS compared, so that tick takes the
    /// write.
    fn restore_card_refresh_is_inert(&self) -> bool {
        let Some(update) = self.terminal_restore_card_update() else {
            return true;
        };
        let progress = Some(update.fraction);
        let persistent = !notification_progress_is_finished(progress);
        self.notifications.iter().any(|notification| {
            notification.job_key.as_deref() == Some(update.job_key.as_str())
                && notification.tone == update.tone
                && notification.title == update.title
                && notification.message == update.message
                && notification.progress == progress
                && notification.persistent == persistent
                && notification.source.as_deref() == Some(update.session_path.as_str())
        })
    }
    /// ⛔ THE ESCAPE HATCH THE GATE NEVER HAD. See
    /// [`INPUT_GATE_STUCK_RESTORE_AFTER_MS`].
    ///
    /// Returns the restored session path when it acts. Everything it does is a
    /// write to `terminal_resume_ready_paths` — the existing owner of the
    /// answer — so no second source of truth is created.
    fn tick_input_gate_deadline(&mut self, now_ms: u64) -> Option<String> {
        let candidate = self.input_gate_deadline_candidate();
        self.tick_input_gate_deadline_for_candidate(candidate, now_ms)
    }
    /// The deadline's whole decision, with the candidate handed in — the seam
    /// tests drive, because installing a live SSH session view into the server
    /// is not something a unit test can do.
    fn tick_input_gate_deadline_for_candidate(
        &mut self,
        candidate: Option<String>,
        now_ms: u64,
    ) -> Option<String> {
        let Some(session_path) = candidate else {
            self.input_gate_denied_since_ms.clear();
            self.input_gate_stuck_reported.clear();
            return None;
        };
        if !self.remote_resume_input_gate_is_shut(&session_path) {
            self.input_gate_denied_since_ms.remove(&session_path);
            self.input_gate_stuck_reported.remove(&session_path);
            return None;
        }
        let denied_since_ms = *self
            .input_gate_denied_since_ms
            .entry(session_path.clone())
            .or_insert(now_ms);
        let denied_for_ms = now_ms.saturating_sub(denied_since_ms);
        // The surface must be demonstrably live before we hand it the keyboard:
        // a host is mounted, it reached Ready at least once in this life, and
        // the daemon owns its PTY right now. A first cold resume fails this
        // test — which is the case the gate exists to protect.
        if !self.terminal_session_host_reusable_for_reveal(&session_path) {
            if denied_for_ms >= INPUT_GATE_STUCK_REPORT_AFTER_MS
                && self.input_gate_stuck_reported.insert(session_path.clone())
            {
                let host_mounted = self.terminal_session_host_id(&session_path).is_some();
                let was_ever_ready = self.terminal_session_was_ever_ready(&session_path);
                let daemon_owns = self.daemon_owns_session_runtime(&session_path);
                self.record_terminal_io_telemetry(
                    "input_gate_stuck_unrestorable",
                    "error",
                    &session_path,
                    "the input gate has refused the focused row for longer than the report deadline, and the surface cannot be proven live",
                    json!({
                        "session_path": session_path.clone(),
                        "denied_for_ms": denied_for_ms,
                        "host_mounted": host_mounted,
                        "was_ever_ready": was_ever_ready,
                        "daemon_owns_session_runtime": daemon_owns,
                        "terminal_attach_in_flight": self
                            .terminal_attach_in_flight
                            .contains(&session_path),
                    }),
                );
            }
            // ⛔ THE BRANCH USED TO END HERE, AND THAT WAS THE BUG. Reporting is
            // not recovering: the report fires once, and every subsequent tick
            // fell through to this same `return None`, so a row that could not
            // prove itself live stayed untypeable for the rest of its life.
            // See INPUT_GATE_STUCK_UNPROVEN_RESTORE_AFTER_MS for why the two
            // FACTS below are enough without this client's memory of `ready`.
            if denied_for_ms >= INPUT_GATE_STUCK_UNPROVEN_RESTORE_AFTER_MS
                && self.terminal_session_host_id(&session_path).is_some()
                && self.daemon_owns_session_runtime(&session_path)
            {
                let cleared_attach = self.terminal_attach_in_flight.remove(&session_path);
                self.terminal_resume_ready_paths
                    .insert(session_path.clone());
                self.input_gate_denied_since_ms.remove(&session_path);
                self.input_gate_stuck_reported.remove(&session_path);
                self.record_terminal_io_telemetry(
                    "input_gate_deadline_restored_unproven",
                    "warn",
                    &session_path,
                    "the gate refused a row it could not prove ready past the last-resort deadline; the daemon owns a live PTY for a mounted host, so readiness was restored without this client's ready-memory",
                    json!({
                        "session_path": session_path.clone(),
                        "denied_for_ms": denied_for_ms,
                        "deadline_ms": INPUT_GATE_STUCK_UNPROVEN_RESTORE_AFTER_MS,
                        "cleared_stale_attach_in_flight": cleared_attach,
                    }),
                );
                return Some(session_path);
            }
            return None;
        }
        let attach_in_flight = self.terminal_attach_in_flight.contains(&session_path);
        let deadline_ms = if attach_in_flight {
            INPUT_GATE_STUCK_INFLIGHT_RESTORE_AFTER_MS
        } else {
            INPUT_GATE_STUCK_RESTORE_AFTER_MS
        };
        if denied_for_ms < deadline_ms {
            return None;
        }
        self.terminal_resume_ready_paths
            .insert(session_path.clone());
        if attach_in_flight {
            // The marker outlived the attach it described; the daemon owning a
            // live PTY for a host that was ready is the disproof.
            self.terminal_attach_in_flight.remove(&session_path);
        }
        self.input_gate_denied_since_ms.remove(&session_path);
        self.input_gate_stuck_reported.remove(&session_path);
        self.record_terminal_io_telemetry(
            "input_gate_deadline_restored",
            "warn",
            &session_path,
            "the input gate refused a live surface past its deadline; readiness restored",
            json!({
                "session_path": session_path.clone(),
                "denied_for_ms": denied_for_ms,
                "deadline_ms": deadline_ms,
                "cleared_stale_attach_in_flight": attach_in_flight,
            }),
        );
        Some(session_path)
    }
    fn active_terminal_prefers_text_input(&self) -> bool {
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal {
            return false;
        }
        if (self.right_panel_mode != RightPanelMode::Hidden && !self.terminal_input_override_active)
            || self.search_focused
            || self.tree_rename_path.is_some()
            || is_command_query(&self.search_query)
        {
            return false;
        }
        let Some(session_path) = self.server.active_session_path() else {
            return false;
        };
        if self.terminal_attach_in_flight.contains(session_path) {
            return false;
        }
        self.terminal_session_has_visual_resume_reveal(session_path)
            || self.terminal_session_has_ready_attempt(session_path)
    }
    fn terminal_session_has_active_terminal_request(&self, session_path: &str) -> bool {
        let Some(request) = self.active_surface_requests.get(&YggSurface::Terminal) else {
            return false;
        };
        active_request_session_target_path(request, self.server.active_session_path()).as_deref()
            == Some(session_path)
    }
    fn startup_terminal_restore_should_open(&self, active_session_path: &str) -> bool {
        self.server.active_view_mode() == WorkspaceViewMode::Terminal
            && !self.server_busy
            && self.server.active_session_path() == Some(active_session_path)
            && self.latest_open_request_id == 0
            && !self.terminal_attach_in_flight.contains(active_session_path)
            && !self.terminal_session_has_active_terminal_request(active_session_path)
            && !self.terminal_session_has_ready_attempt(active_session_path)
            && self.terminal_session_host_id(active_session_path).is_none()
    }
    fn latest_terminal_open_attempt_has_empty_surface(&self, active_session_path: &str) -> bool {
        self.latest_terminal_open_attempt_for_path(active_session_path)
            .is_some_and(|attempt| {
                attempt.last_surface_problem.as_deref()
                    == Some(RETAINED_EMPTY_XTERM_SURFACE_PROBLEM)
                    || attempt.last_observed_reason.as_deref()
                        == Some(RETAINED_EMPTY_XTERM_SURFACE_PROBLEM)
            })
    }
    fn startup_terminal_restore_should_recover(
        &self,
        active_session_path: &str,
        now_ms: u64,
    ) -> bool {
        // A live web surface owns the viewport: a blank xterm behind it is
        // expected, and remounting the terminal would replay the app OSC and
        // destroy/recreate the surface every watch tick (the 5s ychrome churn
        // storm). Observation-side neutralization covers NEW readings; this
        // covers a problem latched before the surface came up.
        if self.has_live_web_surface(active_session_path, now_ms) {
            return false;
        }
        // Futile-recovery cap: each recovery here tears down and re-seeds the
        // viewport. If N consecutive recoveries ran without the session ever
        // latching Ready, another remount won't change the outcome — stop the
        // unbounded 5s epoch-bump loop (observed live at epoch 179+, pegging
        // the CPU). The streak resets on any Ready and on any user-driven open.
        if self
            .startup_restore_recover_streak
            .get(active_session_path)
            .copied()
            .unwrap_or(0)
            >= STARTUP_TERMINAL_RESTORE_MAX_RECOVERIES
        {
            return false;
        }
        let mut stale_attempt_empty_surface = false;
        let stale_startup_attempt = self
            .latest_terminal_open_attempt_for_path(active_session_path)
            .is_some_and(|attempt| {
                let stale_open_attempt = matches!(
                    attempt.state,
                    TerminalOpenAttemptState::Pending | TerminalOpenAttemptState::Recovering
                ) && now_ms.saturating_sub(attempt.started_at_ms)
                    >= STARTUP_TERMINAL_RESTORE_RECOVERY_MS;
                let empty_surface = attempt.last_surface_problem.as_deref()
                    == Some(RETAINED_EMPTY_XTERM_SURFACE_PROBLEM)
                    || attempt.last_observed_reason.as_deref()
                        == Some(RETAINED_EMPTY_XTERM_SURFACE_PROBLEM);
                let stale =
                    stale_open_attempt && (attempt.source == "startup_restore" || empty_surface);
                if stale && empty_surface {
                    stale_attempt_empty_surface = true;
                }
                stale
            });
        if !stale_startup_attempt {
            return false;
        }
        let remote_session_path = self.terminal_session_uses_remote_runtime(active_session_path);
        let has_stable_retained_host = self.terminal_session_host_id(active_session_path).is_some()
            && !self.terminal_attach_in_flight.contains(active_session_path);
        let has_terminal_request = self
            .active_surface_requests
            .contains_key(&YggSurface::Terminal);
        let active_terminal_request_for_session =
            self.terminal_session_has_active_terminal_request(active_session_path);
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal
            || (self.server_busy && !active_terminal_request_for_session)
            || self.server.active_session_path() != Some(active_session_path)
            || (has_terminal_request && !active_terminal_request_for_session)
            || (has_stable_retained_host && !stale_attempt_empty_surface)
            || (!stale_attempt_empty_surface
                && (self.terminal_session_has_visual_resume_reveal(active_session_path)
                    || self.terminal_session_has_ready_attempt(active_session_path)))
            || (remote_session_path && !stale_attempt_empty_surface)
        {
            return false;
        }
        true
    }
    fn recover_startup_terminal_restore(&mut self, active_session_path: &str, now_ms: u64) -> bool {
        // A reusable retained host being revealed on switch-back can momentarily
        // read "empty surface" — a hidden xterm repaint gap, not a fault. While
        // it is inside the reveal grace, tearing it down + bumping the epoch
        // would force a ~1s cold remount (the hot-switch latency we're killing).
        // Let the activation repaint fill it instead. See
        // [[finding-hot-switch-latency-remount]] (#milestone).
        if self.terminal_session_host_reusable_for_reveal(active_session_path)
            && self.terminal_session_in_reveal_grace(active_session_path)
        {
            return false;
        }
        if !self.startup_terminal_restore_should_recover(active_session_path, now_ms) {
            return false;
        }
        *self
            .startup_restore_recover_streak
            .entry(active_session_path.to_string())
            .or_insert(0) += 1;
        if let Some(attempt_id) = self
            .terminal_open_attempt_by_session
            .get(active_session_path)
            .cloned()
            && let Some(attempt) = self.terminal_open_attempts.get_mut(&attempt_id)
        {
            attempt.state = TerminalOpenAttemptState::Recovering;
            attempt.started_at_ms = now_ms;
        }
        self.terminal_attach_in_flight.remove(active_session_path);
        self.terminal_bootstrap_owner_by_session
            .remove(active_session_path);
        self.terminal_bootstrap_lease_by_session
            .remove(active_session_path);
        self.terminal_resume_ready_paths.remove(active_session_path);
        if self.latest_terminal_open_attempt_has_empty_surface(active_session_path) {
            let _ = self.bump_terminal_mount_epoch_for_session(active_session_path);
            if self.server.active_view_mode() == WorkspaceViewMode::Terminal
                && self.server.active_session_path() == Some(active_session_path)
            {
                self.active_terminal_host_id = self.terminal_session_host_id(active_session_path);
            }
        }
        true
    }
    fn retained_fault_recovery_should_rearm(&self, active_session_path: &str, now_ms: u64) -> bool {
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal
            || self.server.active_session_path() != Some(active_session_path)
            || !self.terminal_attach_in_flight.contains(active_session_path)
        {
            return false;
        }
        if self
            .retained_rehydrate_daemon_ready_wait_elapsed_ms(active_session_path, now_ms)
            .is_some()
        {
            return false;
        }
        self.latest_terminal_open_attempt_for_path(active_session_path)
            .is_some_and(|attempt| {
                let rearm_after_ms = retained_fault_recovery_rearm_after_ms(attempt);
                attempt.source == "retained_fault_recovery"
                    && matches!(
                        attempt.state,
                        TerminalOpenAttemptState::Pending | TerminalOpenAttemptState::Recovering
                    )
                    && attempt.rearm_count < RETAINED_FAULT_RECOVERY_MAX_REARMS
                    && now_ms.saturating_sub(attempt.started_at_ms) >= rearm_after_ms
            })
    }
    fn retained_fault_recovery_watch_delay_ms(
        &self,
        active_session_path: &str,
        now_ms: u64,
    ) -> Option<u64> {
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal
            || self.server.active_session_path() != Some(active_session_path)
            || !self.terminal_attach_in_flight.contains(active_session_path)
        {
            return None;
        }
        if self
            .retained_rehydrate_daemon_ready_wait_elapsed_ms(active_session_path, now_ms)
            .is_some()
        {
            return Some(RETAINED_REHYDRATE_DAEMON_READY_WATCH_GRACE_MS);
        }
        self.latest_terminal_open_attempt_for_path(active_session_path)
            .and_then(|attempt| {
                if attempt.source != "retained_fault_recovery"
                    || !matches!(
                        attempt.state,
                        TerminalOpenAttemptState::Pending | TerminalOpenAttemptState::Recovering
                    )
                {
                    return None;
                }
                let elapsed_ms = now_ms.saturating_sub(attempt.started_at_ms);
                let rearm_after_ms = retained_fault_recovery_rearm_after_ms(attempt);
                Some(
                    rearm_after_ms
                        .saturating_sub(elapsed_ms)
                        .saturating_add(TERMINAL_RECOVERY_WATCH_GRACE_MS),
                )
            })
    }
    fn retained_fault_recovery_watch_identity(&self, active_session_path: &str) -> Option<String> {
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal
            || self.server.active_session_path() != Some(active_session_path)
            || !self.terminal_attach_in_flight.contains(active_session_path)
        {
            return None;
        }
        let attempt = self.latest_terminal_open_attempt_for_path(active_session_path)?;
        if attempt.source != "retained_fault_recovery"
            || !matches!(
                attempt.state,
                TerminalOpenAttemptState::Pending | TerminalOpenAttemptState::Recovering
            )
        {
            return None;
        }
        Some(format!(
            "retained-fault-watch:{active_session_path}:{}",
            attempt.attempt_id
        ))
    }
    fn rearm_stale_retained_fault_recovery(
        &mut self,
        active_session_path: &str,
        now_ms: u64,
    ) -> bool {
        if self.server.active_view_mode() != WorkspaceViewMode::Terminal
            || self.server.active_session_path() != Some(active_session_path)
            || !self.terminal_attach_in_flight.contains(active_session_path)
        {
            return false;
        }
        if self
            .defer_retained_fault_recovery_rearm_for_daemon_ready_wait(active_session_path, now_ms)
        {
            return false;
        }
        let mut exhausted_budget = false;
        let mut should_rearm = false;
        if let Some(attempt_id) = self
            .terminal_open_attempt_by_session
            .get(active_session_path)
            .cloned()
            && let Some(attempt) = self.terminal_open_attempts.get_mut(&attempt_id)
        {
            let rearm_after_ms = retained_fault_recovery_rearm_after_ms(attempt);
            if attempt.source != "retained_fault_recovery"
                || !matches!(
                    attempt.state,
                    TerminalOpenAttemptState::Pending | TerminalOpenAttemptState::Recovering
                )
                || now_ms.saturating_sub(attempt.started_at_ms) < rearm_after_ms
            {
                return false;
            }
            if attempt.rearm_count >= RETAINED_FAULT_RECOVERY_MAX_REARMS {
                // Exhausted: decide Failed-vs-keep-alive AFTER this borrow ends,
                // based on whether the daemon still owns the live PTY (a &self call
                // not allowed during this &mut borrow).
                exhausted_budget = true;
            } else {
                attempt.rearm_count = attempt.rearm_count.saturating_add(1);
                should_rearm = true;
            }
        }
        if !should_rearm && !exhausted_budget {
            return false;
        }
        self.record_terminal_contract_telemetry(
            if exhausted_budget {
                "retained_fault_recovery_exhausted"
            } else {
                "retained_fault_recovery_rearm"
            },
            if exhausted_budget { "error" } else { "warn" },
            active_session_path,
            if exhausted_budget {
                "retained fault recovery exhausted remount budget"
            } else {
                "retained fault recovery watchdog remount"
            },
            json!({
                "exhausted_budget": exhausted_budget,
                "should_rearm": should_rearm,
                "active_view_mode": format!("{:?}", self.server.active_view_mode()),
                "active_session_path": self.server.active_session_path(),
            }),
        );
        if exhausted_budget {
            self.terminal_attach_in_flight.remove(active_session_path);
            self.terminal_bootstrap_owner_by_session
                .remove(active_session_path);
            self.terminal_bootstrap_lease_by_session
                .remove(active_session_path);
            if self.daemon_owns_session_runtime(active_session_path) {
                // NEVER fail/close a LIVE session: the daemon still owns the PTY,
                // so the terminal content is real even though codex-prompt
                // recognition kept missing. Accept the surface as-is and keep the
                // session alive + usable (a keystroke or slash repaints) instead of
                // marking it Failed (which yanks/closes it). Auto-closing a working
                // session is the worst outcome. See [[finding-hot-switch-latency-remount]].
                self.mark_terminal_open_attempt_ready_for_session(
                    active_session_path,
                    "retained_fault_recovery_exhausted_keep_alive",
                );
            } else {
                // No live runtime — a genuine failure. Mark it failed as before.
                if let Some(attempt_id) = self
                    .terminal_open_attempt_by_session
                    .get(active_session_path)
                    .cloned()
                    && let Some(attempt) = self.terminal_open_attempts.get_mut(&attempt_id)
                {
                    attempt.state = TerminalOpenAttemptState::Failed;
                    attempt.latched_failure_at_ms = Some(now_ms);
                    attempt.latched_failure_reason =
                        Some("retained fault recovery exhausted remount budget".to_string());
                    if attempt.last_surface_problem.is_none() {
                        attempt.last_surface_problem =
                            Some("retained fault recovery exhausted remount budget".to_string());
                    }
                }
                self.terminal_resume_ready_paths.remove(active_session_path);
            }
            return true;
        }
        if let Some(attempt_id) = self
            .terminal_open_attempt_by_session
            .get(active_session_path)
            .cloned()
            && let Some(attempt) = self.terminal_open_attempts.get_mut(&attempt_id)
        {
            attempt.state = TerminalOpenAttemptState::Recovering;
            attempt.started_at_ms = now_ms;
        }
        self.terminal_attach_in_flight.remove(active_session_path);
        self.terminal_bootstrap_owner_by_session
            .remove(active_session_path);
        self.terminal_bootstrap_lease_by_session
            .remove(active_session_path);
        self.terminal_resume_ready_paths.remove(active_session_path);
        let _ = self.bump_terminal_mount_epoch_for_session(active_session_path);
        if self.server.active_view_mode() == WorkspaceViewMode::Terminal
            && self.server.active_session_path() == Some(active_session_path)
        {
            self.active_terminal_host_id = self.terminal_session_host_id(active_session_path);
        }
        true
    }
    fn terminal_session_resume_notification_should_stay_visible(&self, session_path: &str) -> bool {
        if self.terminal_session_has_ready_attempt(session_path) {
            return false;
        }
        // A saved Codex session that the remote machine has removed is a
        // terminal, actionable state: the "Session No Longer On Remote" toast
        // must stay visible so the user sees how to clear the dead row. The
        // wrapper's error text otherwise counts as "meaningful resume output"
        // below and silently suppresses the clarifier — the fast-fail gap that
        // made all three timer/transport-error sites no-op (issue #16).
        if self.terminal_session_codex_no_longer_on_remote(session_path) {
            return true;
        }
        // Per [[spec-xterm-gating-ux]]: when retained_fault_recovery is latched
        // because the PTY is gone, the user-facing toast must NOT keep
        // re-asserting itself on poll ticks. The latch is the authoritative
        // "this session is not coming back without user action" signal.
        if self
            .retained_fault_recovery_lost_pty_sessions
            .contains(session_path)
        {
            return false;
        }
        if self.terminal_session_has_meaningful_resume_output(session_path)
            && !self.terminal_attach_in_flight.contains(session_path)
            && !self.terminal_session_has_active_terminal_request(session_path)
        {
            return false;
        }
        terminal_resume_notification_should_stay_visible_for_session(
            self.terminal_attach_in_flight.contains(session_path),
            self.terminal_session_has_visual_resume_reveal(session_path),
            self.terminal_session_has_active_terminal_request(session_path),
        )
    }
    fn clear_terminal_resume_notifications_except(&mut self, keep_session_path: Option<&str>) {
        let keep_path = keep_session_path.map(str::to_string);
        let keep_is_still_recovering = keep_path.as_deref().is_some_and(|session_path| {
            self.terminal_session_resume_notification_should_stay_visible(session_path)
        });
        self.notifications.retain(|notification| {
            let Some(job_key) = notification.job_key.as_deref() else {
                return true;
            };
            let Some(session_path) = terminal_resume_notification_session_path(job_key) else {
                return true;
            };
            keep_path
                .as_deref()
                .is_some_and(|keep_path| keep_path == session_path)
                && keep_is_still_recovering
        });
    }
    fn prune_terminal_resume_notifications(&mut self) {
        let keep_session_path = if self.server.active_view_mode() == WorkspaceViewMode::Terminal {
            self.server.active_session_path().map(str::to_string)
        } else {
            None
        };
        self.clear_terminal_resume_notifications_except(keep_session_path.as_deref());
    }
    fn prune_terminal_attach_in_flight(&mut self) {
        let active_path = self.server.active_session_path().map(str::to_string);
        let active_terminal_request_path = self
            .active_surface_requests
            .get(&YggSurface::Terminal)
            .and_then(|request| {
                active_request_session_target_path(request, self.server.active_session_path())
            });
        let retained_paths = self.retained_terminal_session_paths.clone();
        let ready_paths = self
            .terminal_attach_in_flight
            .iter()
            .filter(|session_path| self.terminal_session_has_ready_attempt(session_path))
            .cloned()
            .collect::<HashSet<_>>();
        let mut removed_paths = Vec::new();
        self.terminal_attach_in_flight.retain(|session_path| {
            let foreground_attach = active_path.as_deref() == Some(session_path.as_str())
                || active_terminal_request_path.as_deref() == Some(session_path.as_str());
            let keep = foreground_attach
                && retained_paths.contains(session_path)
                && !ready_paths.contains(session_path);
            if !keep {
                removed_paths.push(session_path.clone());
            }
            keep
        });
        for session_path in removed_paths {
            self.terminal_bootstrap_owner_by_session
                .remove(&session_path);
            self.terminal_bootstrap_lease_by_session
                .remove(&session_path);
            self.maybe_finish_terminal_surface_request_for_session(&session_path);
        }
    }
    fn prune_terminal_resume_ready_paths(&mut self) {
        let mut keep_paths = self.retained_terminal_session_paths.clone();
        if let Some(active_path) = self.server.active_session_path() {
            keep_paths.insert(active_path.to_string());
        }
        self.terminal_resume_ready_paths
            .retain(|session_path| keep_paths.contains(session_path));
        if self.server.active_session_path().is_none() {
            self.active_terminal_host_id = None;
        }
    }
    fn prune_terminal_bootstrap_owners(&mut self) {
        let mut keep_paths = self.retained_terminal_session_paths.clone();
        if let Some(active_path) = self.server.active_session_path() {
            keep_paths.insert(active_path.to_string());
        }
        self.terminal_bootstrap_owner_by_session
            .retain(|session_path, _| keep_paths.contains(session_path));
        self.terminal_bootstrap_lease_by_session
            .retain(|session_path, _| keep_paths.contains(session_path));
    }
    fn ensure_active_session_expanded(&mut self) {
        let remote_paths = self
            .active_session_visibility_paths()
            .into_iter()
            .filter(|path| !self.user_collapsed_synthetic_paths.contains(path))
            .collect::<Vec<_>>();
        if !remote_paths.is_empty() {
            self.browser.ensure_expanded_paths(remote_paths);
        } else if let Some(active_path) = self.active_browser_selection_path_for_session() {
            self.browser.ensure_visible_path(&active_path);
        }
    }
    fn clear_user_collapsed_synthetic_ancestors_for_path(&mut self, session_path: &str) {
        let Some((machine_key, _session_id)) = parse_remote_scanned_session_path(session_path)
        else {
            return;
        };
        self.user_collapsed_synthetic_paths
            .retain(|path| !path.starts_with(&format!("__remote_machine__/{machine_key}")));
        self.browser
            .set_collapsed_paths(self.user_collapsed_synthetic_paths.clone());
    }
    /// Take a set apart: its members go where the HEAD sat, and the head keeps
    /// its own place.
    ///
    /// ⛔ **PROMOTE TO THE HEAD'S PLACE, NOT TO THE TOP LEVEL** — `DESIGN.md`
    /// says the members take the head's position, and that is not the same
    /// thing once sets nest. Caught by live-testing the verb: dissolving a
    /// hand-made set INSIDE a numbered book ejected its rows from the book
    /// entirely, because they were marked deliberately loose rather than
    /// re-filed where their head had been.
    ///
    /// ⚠ Members of a set the SEATS would rebuild must still be pinned, or
    /// "Ungroup" on a numbered book appears to do nothing at all: the seats
    /// re-form it on the very next frame. Pinning them to the head's parent
    /// does both jobs — it keeps them where the head was, and it is an answer,
    /// so the seats stop deciding for them.
    fn dissolve_row_set(&mut self, head_path: &str) -> Vec<String> {
        let grandparent = self
            .row_set_effective_parent(head_path)
            .filter(|parent| parent != head_path);
        let members = self.row_arrangement.sets.dissolve(head_path);
        // Anything the SEATS put under this head is dissolved too — otherwise
        // half the set survives the gesture and the other half does not.
        let seat_members: Vec<String> = self
            .sidebar_row_sets_now()
            .members_of(head_path)
            .to_vec();
        for member in members.iter().chain(seat_members.iter()) {
            match grandparent.as_deref() {
                Some(parent) => {
                    let _ = self.row_arrangement.attach(parent, member, None);
                }
                None => self.row_arrangement.detach(member),
            }
        }
        let mut promoted = members;
        promoted.extend(seat_members);
        promoted.sort();
        promoted.dedup();
        promoted
    }

    /// How many consecutive snapshots a row must be absent from before its
    /// arrangement entry is forgotten.
    ///
    /// Three, for the same reason the boot watchdog confirms an absence three
    /// times before acting on it: one missing sighting is a snapshot arriving
    /// mid-handover, and the cost of being wrong is asymmetric — pruning early
    /// destroys work the user did by hand, while pruning late leaves a dead
    /// entry nobody can see.
    const ROW_ARRANGEMENT_GONE_SIGHTINGS: u8 = 3;

    /// Forget the arrangement of rows that have CONFIRMABLY departed.
    ///
    /// ⛔ **THE DEPARTURE POINT IS WHY THIS TOOK SO LONG TO WIRE.**
    /// `RowArrangement::retain_live` has existed, correct and tested, with no
    /// production caller at all: the GUI's own close and remove paths dissolve
    /// and detach the row being closed, but a head that dies daemon-side or
    /// remotely leaves its entry behind forever, and the stored arrangement
    /// accumulates rows that exist nowhere. The obvious fix — prune every frame
    /// against the live set — is worse than the leak, because the live set
    /// FLICKERS: it is briefly empty or partial during a daemon handover, and a
    /// naive prune would delete the user's whole arrangement at every restart.
    ///
    /// ⇒ So absence is CONFIRMED before it is acted on, and the confirmation
    /// lives in memory so a restart starts the count over rather than inheriting
    /// one taken across the very gap it must not trust.
    ///
    /// ⛔ **AN EMPTY LIVE SET DECIDES NOTHING.** "No rows" and "I have not been
    /// told about the rows yet" are indistinguishable here and only one of them
    /// means everyone departed. Counting on it would let three quiet snapshots
    /// during a handover wipe an arrangement built over weeks.
    fn prune_departed_row_arrangement(&mut self) {
        let live: HashSet<String> = self
            .server
            .live_sessions()
            .iter()
            .filter(|session| is_promoted_live_session(session))
            .map(live_session_row_path)
            .collect();
        if live.is_empty() {
            self.row_arrangement_absent_sightings.clear();
            return;
        }
        let arranged: HashSet<String> = self
            .row_arrangement
            .sets
            .heads()
            .map(ToOwned::to_owned)
            .chain(
                self.row_arrangement
                    .sets
                    .heads()
                    .flat_map(|head| self.row_arrangement.sets.members_of(head))
                    .map(ToOwned::to_owned)
                    .collect::<Vec<_>>(),
            )
            .chain(self.row_arrangement.detached.iter().cloned())
            .collect();
        self.row_arrangement_absent_sightings
            .retain(|path, _| arranged.contains(path));
        let mut confirmed_gone: HashSet<String> = HashSet::new();
        for path in &arranged {
            if live.contains(path) {
                self.row_arrangement_absent_sightings.remove(path);
                continue;
            }
            let seen = self
                .row_arrangement_absent_sightings
                .entry(path.clone())
                .or_insert(0);
            *seen = seen.saturating_add(1);
            if *seen >= Self::ROW_ARRANGEMENT_GONE_SIGHTINGS {
                confirmed_gone.insert(path.clone());
            }
        }
        if confirmed_gone.is_empty() {
            return;
        }
        // `retain_live` keeps what it is GIVEN, so the set handed to it is every
        // arranged path that is not confirmed gone — not the live set. An
        // unconfirmed absence must survive untouched, and a live row obviously
        // must too.
        let keep: HashSet<String> = arranged
            .iter()
            .filter(|path| !confirmed_gone.contains(*path))
            .cloned()
            .collect();
        if self.row_arrangement.retain_live(&keep) {
            for path in &confirmed_gone {
                self.row_arrangement_absent_sightings.remove(path);
            }
            self.sync_browser_settings();
        }
    }

    /// The arrangement the sidebar is drawing right now.
    fn sidebar_row_sets_now(&self) -> yggterm_core::row_set::RowSets {
        let sessions = self.server.live_sessions();
        let promoted = sessions
            .iter()
            .filter(|session| is_promoted_live_session(session))
            .collect::<Vec<_>>();
        let paths = promoted
            .iter()
            .map(|session| live_session_row_path(session))
            .collect::<Vec<_>>();
        yggterm_core::row_set_outline::sidebar_row_sets(
            paths
                .iter()
                .zip(promoted.iter())
                .map(|(path, session)| (path.as_str(), session.outline_prefix.as_deref())),
            &self.row_arrangement,
            &HashSet::new(),
        )
    }

    /// What `row` is to the arrangement the sidebar is drawing.
    ///
    /// ⚠ Live-region rows only. A cwd-tree row is nested by its FOLDER, and
    /// offering to un-group it there would name a structure that surface does
    /// not have.
    fn row_set_menu_role(&self, row: &BrowserRow) -> RowSetMenuRole {
        if !matches!(row.kind, BrowserRowKind::Session | BrowserRowKind::Document)
            || row.full_path.starts_with("split://")
        {
            return RowSetMenuRole::None;
        }
        let path = normalize_live_session_path(&row.full_path);
        if !self.live_row_paths_for_arrangement().contains(&path) {
            return RowSetMenuRole::None;
        }
        if row_heads_a_row_set(row) {
            return RowSetMenuRole::Head;
        }
        if self.row_set_effective_parent(&path).is_some() {
            return RowSetMenuRole::Member;
        }
        RowSetMenuRole::None
    }

    /// Every live row the arrangement may speak about, by the path its row
    /// carries.
    fn live_row_paths_for_arrangement(&self) -> HashSet<String> {
        self.server
            .live_sessions()
            .iter()
            .filter(|session| is_promoted_live_session(session))
            .map(live_session_row_path)
            .collect()
    }

    /// Who holds `path` on the drawn sidebar — the hand's answer if there is
    /// one, and the seat's otherwise.
    ///
    /// ⚠ Asks the SAME function the sidebar draws from rather than reading
    /// `row_arrangement` directly: a drop beside a row must join whatever the
    /// user can SEE holding it, and most rows are held by their seat rather
    /// than by anything a hand has said.
    fn row_set_effective_parent(&self, path: &str) -> Option<String> {
        let sessions = self.server.live_sessions();
        let promoted = sessions
            .iter()
            .filter(|session| is_promoted_live_session(session))
            .collect::<Vec<_>>();
        let paths = promoted
            .iter()
            .map(|session| live_session_row_path(session))
            .collect::<Vec<_>>();
        let sets = yggterm_core::row_set_outline::sidebar_row_sets(
            paths
                .iter()
                .zip(promoted.iter())
                .map(|(path, session)| (path.as_str(), session.outline_prefix.as_deref())),
            &self.row_arrangement,
            // Collapse is irrelevant to WHO HOLDS a row, and passing the real
            // set here would make a drop's meaning depend on what is folded
            // away — the arrangement must not change because something is shut.
            &HashSet::new(),
        );
        sets.parent_of(path).map(str::to_string)
    }

    fn update_synthetic_group_collapse_state(&mut self, path: &str, expanded: bool) {
        if expanded {
            self.user_collapsed_synthetic_paths.remove(path);
        } else {
            self.user_collapsed_synthetic_paths.insert(path.to_string());
        }
        // Keep the browser's collapse mirror current so the next rebuild's default
        // level-one seeding honors this collapse instead of re-opening the group.
        self.browser
            .set_collapsed_paths(self.user_collapsed_synthetic_paths.clone());
    }
    fn sync_active_session_selection(&mut self) {
        if self.preserve_tree_rename_selection() {
            return;
        }
        if let Some(active) = self.server.active_session().cloned() {
            let selected_path = self
                .active_browser_selection_path_for_session()
                .unwrap_or_else(|| active.session_path.clone());
            self.selected_tree_paths.clear();
            self.selected_tree_paths.insert(selected_path.clone());
            self.selection_anchor = Some(selected_path.clone());
            self.browser.select_path(selected_path);
        }
    }
    /// Read the user's view — active session + view mode + selected-row truth —
    /// as one value, so a mutation that must not disturb it can hand it back.
    fn capture_user_view(&self) -> PreservedUserView {
        PreservedUserView {
            viewport: match self.server.active_session_path() {
                Some(path) => PreservedViewport::Session {
                    path: path.to_string(),
                    view_mode: self.server.active_view_mode(),
                },
                None => PreservedViewport::StartPage,
            },
            selection: SidebarSelection {
                anchor: self.selection_anchor.clone(),
                tree_paths: self.selected_tree_paths.clone(),
                browser_path: self.browser.selected_path().map(ToOwned::to_owned),
            },
        }
    }
    /// Put back exactly what `capture_user_view` read. The browser's selection
    /// is cleared before it is re-applied because `select_path` silently
    /// no-ops on a path that is no longer a row — without the clear, a row that
    /// vanished during the mutation would leave the INTRUDING selection
    /// standing instead of falling back to none.
    fn restore_user_view(&mut self, preserved: PreservedUserView) {
        match preserved.viewport {
            PreservedViewport::Session { path, view_mode } => {
                self.server.restore_active_session(&path, view_mode);
            }
            // The same hand-back the viewport history performs for its own
            // `StartPage` entry. `show_start_page` is the SSOT setter (path and
            // view mode together — clearing the path alone leaves a terminal
            // view active without an active session), and
            // `show_start_page_when_no_live_sessions` is forced FALSE rather
            // than restored: while it is true every later snapshot promotes the
            // first live session back to active, which is now the row the
            // create was told not to activate.
            PreservedViewport::StartPage => {
                self.server.show_start_page();
                self.show_start_page_when_no_live_sessions = false;
                self.active_terminal_host_id = None;
                self.clear_terminal_resume_notifications_except(None);
            }
        }
        self.selection_anchor = preserved.selection.anchor;
        self.selected_tree_paths = preserved.selection.tree_paths;
        self.browser.clear_selection();
        if let Some(path) = preserved.selection.browser_path {
            self.browser.select_path(path);
        }
        // `settings.selected_browser_path` is a persisted consumer of the same
        // truth; the apply above already wrote the intruder into it.
        self.sync_browser_settings();
    }
    /// Apply a create's snapshot, then hand back whatever the create promised
    /// not to move.
    ///
    /// ONE owner for both create call sites (local and remote): they differed
    /// only in transport, and the selection half was missing from both. The
    /// apply necessarily marks the NEW session active — that is what the daemon
    /// returned — and `sync_active_session_selection` +
    /// `ensure_active_session_visible` follow it, so the hand-back must land in
    /// the SAME mutation window; both are applied before the next render, so
    /// nothing flashes.
    fn apply_created_terminal_snapshot(
        &mut self,
        result: Result<(ServerUiSnapshot, Option<String>)>,
        preserved: Option<PreservedUserView>,
    ) {
        self.apply_interactive_snapshot_result(result);
        if let Some(preserved) = preserved {
            self.restore_user_view(preserved);
        }
    }
    fn preserve_tree_rename_selection(&mut self) -> bool {
        let Some(rename_path) = self.tree_rename_path.clone() else {
            return false;
        };
        if self
            .browser
            .rows()
            .iter()
            .any(|row| row.full_path == rename_path)
        {
            self.browser.select_path(rename_path.clone());
        }
        self.selected_tree_paths.clear();
        self.selected_tree_paths.insert(rename_path.clone());
        self.selection_anchor = Some(rename_path);
        true
    }
    fn active_titlebar_rename_row(&self) -> Option<BrowserRow> {
        let active = self.server.active_session()?;
        let active_path = normalize_live_session_path(&active.session_path);
        let snapshot = self.snapshot();
        if let Some(row) = selected_sidebar_row_from_rows(
            &snapshot.rows,
            &self.selected_tree_paths,
            self.selection_anchor.as_deref(),
            snapshot.selected_path.as_deref(),
        ) && matches!(row.kind, BrowserRowKind::Session | BrowserRowKind::Document)
            && (normalize_live_session_path(&row.full_path) == active_path
                || row.session_id.as_deref() == Some(active.id.as_str()))
        {
            return Some(row);
        }
        snapshot
            .rows
            .iter()
            .find(|row| {
                matches!(row.kind, BrowserRowKind::Session | BrowserRowKind::Document)
                    && (normalize_live_session_path(&row.full_path) == active_path
                        || row.session_id.as_deref() == Some(active.id.as_str()))
            })
            .cloned()
    }
    fn begin_active_titlebar_rename(&mut self) -> bool {
        let Some(row) = self.active_titlebar_rename_row() else {
            return false;
        };
        self.begin_tree_rename(&row);
        self.titlebar_session_menu_open = false;
        true
    }
    fn background_active_selection_sync_needed(&self) -> bool {
        if self.tree_rename_path.is_some() {
            return false;
        }
        if self.selected_tree_paths.is_empty() {
            return true;
        }
        let Some(selected_row) = explicit_selected_sidebar_row(self) else {
            return true;
        };
        let Some(expected_path) = self
            .active_browser_selection_path_for_session()
            .or_else(|| {
                self.server
                    .active_session()
                    .map(|session| session.session_path.clone())
            })
            .or_else(|| self.server.active_session_path().map(str::to_string))
        else {
            return false;
        };
        selected_row.full_path == expected_path
            && !self.active_session_sidebar_selection_is_consistent()
    }
    fn active_session_sidebar_selection_is_consistent(&self) -> bool {
        let expected_browser_path = self.active_browser_selection_path_for_session();
        let expected_path = self
            .active_browser_selection_path_for_session()
            .or_else(|| {
                self.server
                    .active_session()
                    .map(|session| session.session_path.clone())
            })
            .or_else(|| self.server.active_session_path().map(str::to_string));
        match expected_path {
            Some(expected_path) => {
                current_selected_sidebar_row(self).is_some_and(|row| row.full_path == expected_path)
                    && expected_browser_path
                        .as_deref()
                        .is_none_or(|path| self.browser.selected_path() == Some(path))
            }
            None => {
                current_selected_sidebar_row(self).is_none()
                    && self.browser.selected_path().is_none()
            }
        }
    }
    fn active_browser_selection_path_for_session(&self) -> Option<String> {
        let active = self.server.active_session()?;
        let active_path = active.session_path.clone();
        if self
            .browser
            .rows()
            .iter()
            .any(|row| row.full_path == active_path)
        {
            return Some(active_path);
        }
        self.browser.rows().iter().find_map(|row| {
            (row.session_id.as_deref() == Some(active.id.as_str())
                && matches!(row.kind, BrowserRowKind::Session | BrowserRowKind::Document))
            .then(|| row.full_path.clone())
        })
    }
    fn viewport_row_for_session_path(&self, session_path: &str) -> Option<BrowserRow> {
        let normalized_path = normalize_live_session_path(session_path);
        let active_session_id = self
            .server
            .active_session()
            .filter(|session| {
                session.session_path == session_path
                    || normalize_live_session_path(&session.session_path) == normalized_path
            })
            .map(|session| session.id.clone());
        self.snapshot().rows.into_iter().find(|row| {
            row.full_path == session_path
                || normalize_live_session_path(&row.full_path) == normalized_path
                || active_session_id
                    .as_deref()
                    .is_some_and(|id| row.session_id.as_deref() == Some(id))
        })
    }
    fn current_start_page_scope_path(&self, closed_paths: &[String]) -> Option<String> {
        let snapshot = self.snapshot();
        let selected_path = self
            .selection_anchor
            .as_ref()
            .cloned()
            .or_else(|| self.browser.selected_path().map(ToOwned::to_owned))?;
        snapshot
            .rows
            .iter()
            .find(|row| {
                row.full_path == selected_path
                    && row.kind == BrowserRowKind::Group
                    && !viewport_path_matches_closed(&row.full_path, closed_paths)
            })
            .map(|row| row.full_path.clone())
    }
    fn current_viewport_history_entry(&self) -> ViewportHistoryEntry {
        if let Some(active_path) = self.server.active_session_path()
            && let Some(row) = self.viewport_row_for_session_path(active_path)
        {
            return ViewportHistoryEntry::Session {
                row,
                mode: self.server.active_view_mode(),
            };
        }
        ViewportHistoryEntry::StartPage {
            selected_path: self.current_start_page_scope_path(&[]),
        }
    }
    fn remember_current_viewport_for_history(&mut self) {
        let target = self.current_viewport_history_entry();
        self.push_viewport_history_entry(target);
    }
    fn push_viewport_history_entry(&mut self, target: ViewportHistoryEntry) {
        if self.viewport_history.back() == Some(&target) {
            return;
        }
        self.viewport_history.retain(|entry| entry != &target);
        self.viewport_history.push_back(target);
        while self.viewport_history.len() > VIEWPORT_HISTORY_LIMIT {
            self.viewport_history.pop_front();
        }
    }
    fn prune_viewport_history_for_closed_paths(&mut self, closed_paths: &[String]) {
        self.viewport_history
            .retain(|entry| !viewport_entry_references_closed(entry, closed_paths));
    }
    fn resolve_valid_viewport_history_entry(
        &self,
        entry: &ViewportHistoryEntry,
        closed_paths: &[String],
    ) -> Option<ViewportHistoryEntry> {
        match entry {
            ViewportHistoryEntry::StartPage { selected_path } => {
                let selected_path = selected_path.as_ref().and_then(|path| {
                    let snapshot = self.snapshot();
                    snapshot
                        .rows
                        .iter()
                        .find(|row| {
                            row.full_path == *path
                                && row.kind == BrowserRowKind::Group
                                && !viewport_path_matches_closed(&row.full_path, closed_paths)
                        })
                        .map(|row| row.full_path.clone())
                });
                Some(ViewportHistoryEntry::StartPage { selected_path })
            }
            ViewportHistoryEntry::Session { row, mode } => {
                if viewport_path_matches_closed(&row.full_path, closed_paths) {
                    return None;
                }
                let snapshot = self.snapshot();
                let current_row = snapshot.rows.into_iter().find(|candidate| {
                    candidate.full_path == row.full_path
                        || normalize_live_session_path(&candidate.full_path)
                            == normalize_live_session_path(&row.full_path)
                        || row
                            .session_id
                            .as_deref()
                            .is_some_and(|id| candidate.session_id.as_deref() == Some(id))
                })?;
                if !matches!(
                    current_row.kind,
                    BrowserRowKind::Session | BrowserRowKind::Document
                ) {
                    return None;
                }
                let mode = if *mode == WorkspaceViewMode::Terminal
                    && !row_supports_terminal(self, &current_row)
                {
                    WorkspaceViewMode::Rendered
                } else {
                    *mode
                };
                Some(ViewportHistoryEntry::Session {
                    row: current_row,
                    mode,
                })
            }
        }
    }
    fn close_redirect_target_for_pending(
        &mut self,
        pending: &PendingDeleteDialog,
    ) -> Option<ViewportHistoryEntry> {
        if !pending.live_session_close {
            return None;
        }
        let active_path = self.server.active_session_path()?.to_string();
        if !viewport_path_matches_closed(&active_path, &pending.session_paths) {
            return None;
        }
        self.prune_viewport_history_for_closed_paths(&pending.session_paths);
        for entry in self.viewport_history.iter().rev() {
            if let Some(target) =
                self.resolve_valid_viewport_history_entry(entry, &pending.session_paths)
            {
                return Some(target);
            }
        }
        Some(ViewportHistoryEntry::StartPage {
            selected_path: self.current_start_page_scope_path(&pending.session_paths),
        })
    }
    fn apply_viewport_history_entry_locally(
        &mut self,
        target: &ViewportHistoryEntry,
        source: &str,
    ) {
        match target {
            ViewportHistoryEntry::StartPage { selected_path } => {
                self.server.show_start_page();
                self.show_start_page_when_no_live_sessions = false;
                self.active_terminal_host_id = None;
                self.clear_terminal_resume_notifications_except(None);
                if let Some(path) = selected_path
                    && let Some(row) = self
                        .snapshot()
                        .rows
                        .into_iter()
                        .find(|row| row.full_path == *path && row.kind == BrowserRowKind::Group)
                {
                    self.selected_tree_paths.clear();
                    self.selected_tree_paths.insert(row.full_path.clone());
                    self.selection_anchor = Some(row.full_path.clone());
                    if !is_synthetic_sidebar_row(&row) {
                        self.browser.select_path(row.full_path.clone());
                    }
                } else {
                    self.selected_tree_paths.clear();
                    self.selection_anchor = None;
                    self.browser.clear_selection();
                }
                self.refresh_tree_debug(source);
            }
            ViewportHistoryEntry::Session { row, mode } => {
                self.show_start_page_when_no_live_sessions = false;
                self.selected_tree_paths.clear();
                self.selected_tree_paths.insert(row.full_path.clone());
                self.selection_anchor = Some(row.full_path.clone());
                if !is_synthetic_sidebar_row(row) {
                    self.browser.select_path(row.full_path.clone());
                }
                if session_is_hot_terminal_row(self, row) || is_live_sidebar_row(row) {
                    self.server.focus_live_session(&row.full_path);
                } else {
                    self.server.open_or_focus_session(
                        session_kind_for_row(row),
                        &row.full_path,
                        row.session_id.as_deref(),
                        row.session_cwd.as_deref(),
                        Some(row.label.as_str()),
                        None,
                    );
                }
                self.server.set_view_mode(*mode);
                if self.server.active_view_mode() == WorkspaceViewMode::Terminal {
                    arm_terminal_activation(self, &row.full_path);
                    self.retain_terminal_session_path(&row.full_path);
                    self.clear_terminal_resume_notifications_except(Some(row.full_path.as_str()));
                } else {
                    self.clear_terminal_resume_notifications_except(None);
                }
                self.ensure_session_path_visible(&row.full_path);
                self.sync_browser_settings();
                self.refresh_tree_debug(source);
            }
        }
    }
    fn active_session_visibility_paths(&self) -> Vec<String> {
        let active_session = self.server.active_session().cloned();
        let active_path = active_session
            .as_ref()
            .map(|session| session.session_path.clone())
            .or_else(|| self.server.active_session_path().map(ToOwned::to_owned));
        let Some(active_path) = active_path else {
            return Vec::new();
        };
        let active_is_promoted_live = self.server.live_sessions().iter().any(|session| {
            session.session_path == active_path && is_promoted_live_session(session)
        }) || (self.terminal_session_is_retained_live(&active_path)
            && is_hot_terminal_sidebar_path(&active_path));
        let mut paths = Vec::new();
        if active_is_promoted_live {
            paths.push("__live_sessions__".to_string());
        }
        let active_is_kept_live = active_session.as_ref().is_some_and(live_session_keep_alive);
        if active_is_promoted_live
            && !is_local_live_session_path(&active_path)
            && !active_is_kept_live
        {
            return paths;
        }
        if let Some((machine_key, session_id)) = parse_remote_scanned_session_path(&active_path) {
            paths.push(format!("__remote_machine__/{machine_key}"));
            let active_cwd = active_session
                .as_ref()
                .map(|active| metadata_value(active, "Cwd"));
            if let Some(machine) = self
                .server
                .remote_machines()
                .iter()
                .find(|machine| machine.machine_key == machine_key)
            {
                let cwd = active_cwd.unwrap_or_else(|| {
                    machine
                        .sessions
                        .iter()
                        .find(|session| {
                            session.session_path == active_path || session.session_id == session_id
                        })
                        .map(|session| session.cwd.clone())
                        .unwrap_or_default()
                });
                let mut folder_paths = compressed_remote_folder_paths(&machine.sessions, &cwd);
                if folder_paths.is_empty() && !cwd.trim().is_empty() {
                    let mut current = String::new();
                    for segment in cwd.split('/').filter(|segment| !segment.is_empty()) {
                        current.push('/');
                        current.push_str(segment);
                        folder_paths.push(current.clone());
                    }
                }
                paths.extend(
                    folder_paths
                        .into_iter()
                        .map(|path| format!("__remote_folder__/{machine_key}{path}")),
                );
            } else {
                let cwd = active_cwd.unwrap_or_default();
                let mut current = String::new();
                for segment in cwd.split('/').filter(|segment| !segment.is_empty()) {
                    current.push('/');
                    current.push_str(segment);
                    paths.push(format!("__remote_folder__/{machine_key}{current}"));
                }
            }
            return paths;
        }
        let Some(active) = active_session else {
            return Vec::new();
        };
        let local_anchor = if active.kind == SessionKind::Document {
            let document_path = metadata_value(&active, "Path");
            if document_path.is_empty() {
                active.session_path.clone()
            } else {
                document_path
            }
        } else {
            metadata_value(&active, "Cwd")
        };
        paths.push("local".to_string());
        if local_anchor.is_empty() {
            return paths;
        }
        let mut ancestors = Vec::<String>::new();
        let mut cursor = workspace_parent_path(&local_anchor);
        while let Some(path) = cursor {
            if path != "/" {
                ancestors.push(path.clone());
            }
            cursor = workspace_parent_path(&path);
        }
        ancestors.reverse();
        paths.extend(ancestors);
        paths
    }
    fn hydrate_generated_copy_from_remote_cache(&mut self) {
        let cached = self
            .server
            .remote_machines()
            .iter()
            .flat_map(|machine| machine.sessions.iter())
            .map(|session| {
                (
                    session.session_path.clone(),
                    session.title_hint.clone(),
                    session.cached_precis.clone(),
                    session.cached_summary.clone(),
                )
            })
            .collect::<Vec<_>>();
        for (session_path, title_hint, precis, summary) in cached {
            if !title_hint.trim().is_empty() && !memoized_generated_fallback_title(&title_hint) {
                self.server
                    .set_session_title_hint_passive(&session_path, &title_hint);
            }
            if let Some(precis) = precis {
                self.generated_precis
                    .insert(session_path.clone(), precis.clone());
                self.server.set_session_precis_hint(&session_path, &precis);
            }
            if let Some(summary) = summary {
                self.generated_summaries
                    .insert(session_path.clone(), summary.clone());
                self.server
                    .set_session_summary_hint(&session_path, &summary);
            }
        }
    }
    fn select_row(&mut self, row: &BrowserRow) {
        if matches!(
            row.kind,
            BrowserRowKind::Group | BrowserRowKind::Session | BrowserRowKind::Document
        ) {
            self.remember_current_viewport_for_history();
        }
        self.browser.select_path(row.full_path.clone());
        self.record_ui_telemetry(
            "tree_activate",
            json!({
                "path": row.full_path,
                "kind": format!("{:?}", row.kind),
                "selected_paths": self.selected_tree_paths.iter().cloned().collect::<Vec<_>>(),
            }),
        );
        match row.kind {
            BrowserRowKind::Group => {
                self.show_start_page_for_sidebar_scope(row, "select_group_start_page");
            }
            BrowserRowKind::Separator => {
                self.context_menu_row = None;
                self.last_action = format!("selected {}", row.label);
            }
            BrowserRowKind::Session | BrowserRowKind::Document => {
                self.context_menu_row = None;
                self.show_start_page_when_no_live_sessions = false;
                self.clear_user_collapsed_synthetic_ancestors_for_path(&row.full_path);
                self.apply_daemon_snapshot_result(open_stored_session(
                    &self.bootstrap.server_endpoint,
                    session_kind_for_row(&row),
                    &row.full_path,
                    row.session_id.as_deref(),
                    row.session_cwd.as_deref(),
                    Some(row.label.as_str()),
                ));
                self.sync_browser_settings();
                self.last_action = format!("opened {}", row.label);
            }
        }
    }
    fn show_start_page_for_sidebar_scope(&mut self, row: &BrowserRow, source: &str) {
        self.remember_current_viewport_for_history();
        if !self.search_query.trim().is_empty() {
            self.search_query.clear();
            self.search_sidebar_match_index = None;
            self.search_content_match_index = None;
            self.search_focused = false;
        }
        self.server.show_start_page();
        self.show_start_page_when_no_live_sessions = false;
        self.active_terminal_host_id = None;
        self.context_menu_row = None;
        self.close_titlebar_new_menu();
        self.close_context_menu();
        self.sync_browser_settings();
        self.last_action = format!("focused {}", row.label);
        self.refresh_tree_debug(source);
    }
