/// Fill a contributed row's rename field with an AI-generated name.
///
/// The app declared the source text (`rename.ai_source`); yggterm owns the
/// model call, because the endpoint/key/model are yggterm settings and a second
/// copy of them inside every app is the duplicate source of truth the working
/// rules forbid.
fn queue_app_pane_row_rename_ai_name(
    mut state: Signal<ShellState>,
    pane_id: String,
    row_id: String,
    source: String,
) {
    let settings = safe_shell_read(state, "app_pane_rename_ai_settings", |shell| {
        shell.settings.clone()
    });
    let Some(settings) = settings else {
        return;
    };
    spawn(async move {
        let generated = tokio::task::spawn_blocking(move || {
            yggterm_core::request_generated_short_name(&settings, &source)
        })
        .await;
        match generated {
            Ok(Ok(name)) => {
                state.with_mut_counted(|shell| {
                    shell.set_app_pane_row_rename_value(&pane_id, &row_id, name);
                    shell.last_action = "generated a name".to_string();
                });
            }
            Ok(Err(error)) => {
                state.with_mut_counted(|shell| {
                    shell.push_notification(
                        NotificationTone::Warning,
                        "Name Generation Failed",
                        error.to_string(),
                    );
                });
            }
            Err(error) => {
                state.with_mut_counted(|shell| {
                    shell.push_notification(
                        NotificationTone::Warning,
                        "Name Generation Failed",
                        format!("name generation task failed: {error}"),
                    );
                });
            }
        }
    });
}
fn queue_rename_field_ai_title_generation(mut state: Signal<ShellState>, row: BrowserRow) {
    let row_for_task = row.clone();
    spawn(async move {
        let outcome = tokio::task::spawn_blocking(move || -> anyhow::Result<()> {
            let store = SessionStore::open_or_init()?;
            if let Some(session_id) = row_for_task.session_id.as_deref() {
                store.clear_title_for_session_id(session_id)?;
            } else if store
                .clear_title_for_session_path(&row_for_task.full_path)?
                .is_none()
            {
                return Err(anyhow!(
                    "session AI title refresh needs a stable session identity: {}",
                    row_for_task.full_path
                ));
            }
            Ok(())
        })
        .await;

        match outcome {
            Ok(Ok(())) => {
                state.with_mut_counted(|shell| {
                    if shell.tree_rename_path.as_deref() == Some(row.full_path.as_str()) {
                        shell.cancel_tree_rename();
                    }
                    shell.last_action = "regenerating session title".to_string();
                });
                queue_title_generation(state, row, true, true);
            }
            Ok(Err(error)) => {
                state.with_mut_counted(|shell| {
                    shell.push_notification(
                        NotificationTone::Warning,
                        "Title Refresh Failed",
                        error.to_string(),
                    );
                });
            }
            Err(error) => {
                state.with_mut_counted(|shell| {
                    shell.push_notification(
                        NotificationTone::Warning,
                        "Title Refresh Failed",
                        format!("title refresh task failed: {error}"),
                    );
                });
            }
        }
    });
}
