/// The accelerator intercept set as a JS array literal `[{ctrl,alt,shift,meta,key},…]`,
/// generated from the EFFECTIVE accelerators (shipping defaults + the user's
/// keymap.json overrides) so a rebound chord is intercepted too, and the SSOT
/// stays in Rust.
fn keytip_accel_js_array(config: &KeymapConfig) -> String {
    let entries: Vec<String> = keytip::effective_accelerators(config)
        .into_iter()
        .map(|(_, chord)| {
            format!(
                "{{ctrl:{},alt:{},shift:{},meta:{},key:{:?}}}",
                chord.ctrl, chord.alt, chord.shift, chord.meta, chord.key
            )
        })
        .collect();
    format!("[{}]", entries.join(","))
}
/// The fully-assembled bridge script (interactable walk + ALT tap + chord walk +
/// accelerators + badge painter), with the accelerator set baked in. The walk
/// rides the same install loop so the audit verb and the derive edge always see
/// the one `window.__yggtermKeytipWalk`, reinstalled after a webview reload.
fn keytip_bridge_js(config: &KeymapConfig) -> String {
    format!(
        "{KEYTIP_INTERACTABLE_WALK_JS}\n{}",
        ALT_TAP_LISTENER_JS_TEMPLATE.replace("__ACCELS__", &keytip_accel_js_array(config))
    )
}
/// Refresh the LIVE accelerator intercept set in the page after a rebind, without
/// re-installing the listeners. Without this the JS would keep intercepting the
/// OLD chord (which no longer maps to a command) and ignore the new one, so a
/// rebind would silently do nothing until the next GUI restart.
fn push_accels_to_bridge(config: &KeymapConfig) {
    let _ = document::eval(&format!(
        "window.__yggtermAltAccels = {};",
        keytip_accel_js_array(config)
    ));
    // …and the OTHER key door, on the same edge and from the same config, so a
    // rebind cannot land on one and not the other. The JS set only fires while
    // the SHELL webview holds the keyboard; this one fires above every focused
    // child. Two doors, one keymap.
    window().set_web_surface_claimed_chords(claimed_chords_for(config));
}

/// The id the FIND chord relays under.
///
/// The find bar is not on the ALT ladder, so it has no keytip command id to
/// borrow; this is spelled once and read at the terminus, which is what keeps
/// the wire name from growing a second spelling.
const WEB_FIND_CHORD_ID: &str = "web.find";

/// Ctrl+F, the one claimed chord that is NOT a registered accelerator.
///
/// It cannot be one: `keytip::DEFAULT_ACCELERATORS` is asserted PTY-safe
/// (`assert_accels_pty_safe`) and a bare `Ctrl+<letter>` belongs to the
/// terminal forever. Ctrl+F is a BROWSER key, legal only while a browser owns
/// the viewport — which is exactly what `page_only` says and what the window
/// claimer checks before claiming.
const WEB_FIND_CHORD: &str = "Ctrl+F";

/// One legacy browser chord: what to press, what it means, and whether serving
/// it needs the keyboard brought back to the shell's own DOM.
struct WebPageChord {
    chord: &'static str,
    id: &'static str,
    /// True only for a chord whose target is a shell DOM control. A page holds
    /// the toplevel focus while these fire, and an `<input>` in the shell's
    /// webview cannot take a keystroke until the keyboard comes home.
    focus_shell: bool,
}

/// ⭐ **THE LEGACY BROWSER LAYER — the keys thirty years of browsers taught
/// every user, and which yggterm's web surface did not have.**
///
/// Measured before this table existed: F5, Ctrl+R, Ctrl+T, Ctrl+L, Ctrl+W, F12
/// and Ctrl+Shift+I ALL did nothing over a focused page. Reload was the ⟳
/// button or the row menu; a new tab was the `+`; the address bar could not be
/// reached from the keyboard at all; DevTools was agent-only. Every one of them
/// is a verb this app already had, reachable only by mouse.
///
/// ## How this coexists with the ALT layer, which owns different keys
///
/// The two layers cannot collide, and the reason is structural rather than a
/// convention someone has to remember:
///
/// - **The ALT layer owns a clean ALT TAP** (`keytip.rs`, and the JS/GTK tap
///   observers) plus the registered ACCELERATORS in
///   `keytip::DEFAULT_ACCELERATORS`, all of which are asserted PTY-safe by
///   `assert_accels_pty_safe` — meaning none of them is a bare `Ctrl+<letter>`
///   or a bare function key, because those belong to the terminal.
/// - **This layer owns exactly the chords that layer is FORBIDDEN to hold**,
///   and every row is `page_only`, so a chord here does not exist unless a
///   browser genuinely owns the keyboard. `assert_no_legacy_chord_is_an_accel`
///   holds the two disjoint by name rather than by hope.
/// - A terminal never sees any of them: the window claimer asks the toplevel
///   which widget has focus and stands a `page_only` row down unless the
///   focused widget is one of this host's VISIBLE surface webviews.
///
/// So `Ctrl+R` is readline's reverse-search everywhere in the app, and a reload
/// only while a page is in front — which is what a user pressing it means both
/// times.
///
/// ## Why these and not others
///
/// The four the user named are here (F5, Ctrl+R, Ctrl+T, F12), plus the
/// siblings a hand reaches for in the same breath: the second spelling of each
/// (Ctrl+Shift+R, Ctrl+Shift+I), the address bar (Ctrl+L), and closing a tab
/// (Ctrl+W). `Ctrl+N`/`Ctrl+Shift+N` are deliberately absent — this browser has
/// no window to open — and `Ctrl+P` stays absent for the reason it always has:
/// there is no print path to route it to.
const WEB_PAGE_CHORDS: &[WebPageChord] = &[
    // The find bar is in the SHELL's DOM, so it needs the keyboard home.
    WebPageChord {
        chord: WEB_FIND_CHORD,
        id: WEB_FIND_CHORD_ID,
        focus_shell: true,
    },
    // Reload, both spellings. The verb is the row menu's `webtab-reload` aimed
    // at the ACTIVE tab — a difference in the aim, not in the verb.
    WebPageChord {
        chord: "F5",
        id: "web.reload",
        focus_shell: false,
    },
    WebPageChord {
        chord: "Ctrl+R",
        id: "web.reload",
        focus_shell: false,
    },
    // Hard reload. A DIFFERENT verb, not a louder one: it bypasses the HTTP
    // cache, which is the entire reason a user reaches for it.
    WebPageChord {
        chord: "Ctrl+Shift+R",
        id: "web.reload.hard",
        focus_shell: false,
    },
    // A new tab lands TYPING-READY in the address bar, which is the whole
    // point of the key — and that promise is `open_web_surface_tab`'s, kept
    // once for every door rather than re-remembered here.
    WebPageChord {
        chord: "Ctrl+T",
        id: "web.tab.new",
        focus_shell: true,
    },
    // The address bar itself: focus it and select what is in it.
    WebPageChord {
        chord: "Ctrl+L",
        id: "web.address",
        focus_shell: true,
    },
    WebPageChord {
        chord: "Ctrl+W",
        id: "web.tab.close",
        focus_shell: false,
    },
    // DevTools, both spellings. Toggle, not open: a key that only opens leaves
    // the user hunting for the panel's own close button.
    WebPageChord {
        chord: "F12",
        id: "web.devtools",
        focus_shell: false,
    },
    WebPageChord {
        chord: "Ctrl+Shift+I",
        id: "web.devtools",
        focus_shell: false,
    },
    // Copy the PAGE's URL.
    //
    // ⚠ `Ctrl+Shift+C` is ALSO the terminal's copy, and that is not a conflict
    // — it is the whole reason this layer is `page_only`. The terminal's copy
    // lives inside the xterm host's own key handler, which only ever runs for a
    // focused terminal widget; this row stands down unless a VISIBLE surface
    // webview holds the toplevel's focus. One key, one meaning in each place a
    // hand can be: copy the selection in a terminal, copy the address on a
    // page. Locked by `the_terminal_copy_chord_is_never_stolen_from_a_terminal`.
    //
    // `focus_shell: false` on purpose: copying an address is not a reason to
    // take the keyboard off the page the user is reading.
    WebPageChord {
        chord: "Ctrl+Shift+C",
        id: "web.url.copy",
        focus_shell: false,
    },
];

/// Which registered accelerators are claimed ABOVE a focused child.
///
/// **Not all of them, and that is deliberate.** Every accelerator in
/// `keytip::DEFAULT_ACCELERATORS` has the same deafness — the JS bridge that
/// serves them lives in the shell webview and never sees a key a focused page
/// took — but only one of them is a TRAP: `window.fullscreen` is the way OUT of
/// a mode that hides the chrome, and a user who cannot leave it has no recourse
/// but to kill the app (reported 2026-07-31, exactly that). The rest degrade to
/// "the shortcut did nothing", which is a bug to fix on its own evidence, not a
/// reason to reroute five more keys through a new path in one change.
///
/// Adding one is this list plus nothing else.
const WINDOW_CLAIMED_ACCEL_COMMANDS: &[&str] = &["window.fullscreen"];

/// The GDK key name a `keytip::Chord` key means, or `None` when this door
/// cannot express it.
///
/// `None` is a REFUSAL, not a gap to paper over: a chord whose key we cannot
/// name is simply not claimed, so it keeps working exactly as it does today
/// through the JS bridge. Silently claiming the wrong key would be worse than
/// not claiming at all.
fn gdk_key_name_for_chord_key(key: &str) -> Option<String> {
    let key = key.trim().to_ascii_lowercase();
    let mut chars = key.chars();
    match (chars.next(), chars.next()) {
        // A single alphanumeric: GDK answers a character keyval, and
        // `press_key` folds it to lowercase.
        (Some(single), None) if single.is_ascii_alphanumeric() => Some(single.to_string()),
        // F1..F35: GDK's key NAME, which is upper-case `F` plus the number.
        (Some('f'), Some(digit)) if digit.is_ascii_digit() => {
            let number: u32 = key[1..].parse().ok()?;
            (1..=35).contains(&number).then(|| format!("F{number}"))
        }
        _ => None,
    }
}

/// THE claim table, built from the live keymap.
///
/// Data, not code: the vendored host matches it and relays the id back, and
/// knows nothing about what any of it means. Rebuilt on every keymap edge
/// (`push_accels_to_bridge`), so a rebound accelerator is claimed at its NEW
/// chord without a restart.
fn claimed_chords_for(config: &KeymapConfig) -> Vec<dioxus::desktop::ClaimedChord> {
    let mut out = Vec::new();
    for legacy in WEB_PAGE_CHORDS {
        let Some(chord) = Chord::parse(legacy.chord) else {
            continue;
        };
        let Some(key) = gdk_key_name_for_chord_key(&chord.key) else {
            continue;
        };
        out.push(dioxus::desktop::ClaimedChord {
            ctrl: chord.ctrl,
            shift: chord.shift,
            alt: chord.alt,
            key,
            id: legacy.id.to_string(),
            // ⚠ EVERY LEGACY BROWSER CHORD IS `page_only`, and that is what
            // keeps this layer legal. Claimed app-wide, `Ctrl+R` would eat
            // readline's reverse-search and `F5` would eat a TUI's refresh in
            // every terminal in the app.
            page_only: true,
            focus_shell: legacy.focus_shell,
        });
    }
    for (id, chord) in keytip::effective_accelerators(config) {
        if !WINDOW_CLAIMED_ACCEL_COMMANDS.contains(&id.as_str()) {
            continue;
        }
        // SUPER belongs to the compositor on this path; the claimer does not
        // read it, so a chord rebound onto it must not be claimed here either.
        if chord.meta {
            continue;
        }
        let Some(key) = gdk_key_name_for_chord_key(&chord.key) else {
            continue;
        };
        out.push(dioxus::desktop::ClaimedChord {
            ctrl: chord.ctrl,
            shift: chord.shift,
            alt: chord.alt,
            key,
            id,
            // PTY-safe by the keymap's own rule, so it needs no browser.
            // ⚠ THIS IS THE ESCAPE HATCH: an F11 that only worked over a
            // focused page would still leave a user trapped everywhere else.
            page_only: false,
            // Leaving fullscreen must not ALSO take the keyboard off the page
            // the user was reading — that would be a second, unasked-for effect.
            focus_shell: false,
        });
    }
    out
}
/// Keep the below-the-webview ALT key bridge installed for the GUI's lifetime
/// and act on each message it reports. The eval is held open so its `recv()`
/// drains messages as they arrive; if the channel closes (a webview reload), the
/// outer loop reinstalls — and the JS guard makes reinstall a cheap no-op that
/// only re-binds the live sender. The intercept set is rebuilt each (re)install
/// from the live config, so an accelerator rebind takes effect on the next cycle.
async fn keytip_alt_tap_install_loop(state: Signal<ShellState>) {
    let bridge_js = keytip_bridge_js(&state.peek().keytip_config);
    loop {
        // The OTHER key door, re-armed on every (re)install. `push_accels_to_bridge`
        // keeps the two in step on every keymap edge; this is what arms the window
        // claimer in the first place — and it is inside the loop, not before it,
        // so the ESCAPE HATCH cannot be lost to a startup ordering race with the
        // surface host's installation. Replacing the table with an identical one
        // is free.
        window().set_web_surface_claimed_chords(claimed_chords_for(&state.peek().keytip_config));
        // …and the PAGE MENU's entries, on the same edge and for the same
        // reason: a list armed once, before a surface host that installs later,
        // is a list the user never sees. Re-pushing an identical one is free.
        window().set_web_surface_page_menu_items(
            WEB_PAGE_MENU_ITEMS
                .iter()
                .map(|(id, label)| dioxus::desktop::PageMenuItem {
                    id: (*id).to_string(),
                    label: (*label).to_string(),
                })
                .collect(),
        );
        let mut eval = document::eval(&bridge_js);
        loop {
            match eval.recv::<serde_json::Value>().await {
                Ok(msg) => keytip_apply_bridge_message(state, &msg),
                Err(_) => break,
            }
        }
        sleep(Duration::from_millis(500)).await;
    }
}
/// Apply one message from the ALT key bridge. A clean tap (`{tap:true}`) toggles
/// the overlay; a chord key (`{key:"b"}` / `{key:"Escape"}` / `{key:"Backspace"}`)
/// walks the open chord. Routing every ALT interaction through here is what makes
/// it independent of which surface holds DOM focus (§13.1, invariant 11).
fn keytip_apply_bridge_message(mut state: Signal<ShellState>, msg: &serde_json::Value) {
    if msg.get("tap").and_then(|value| value.as_bool()) == Some(true) {
        state.with_mut_counted(|shell| {
            if shell.alt_overlay_active {
                shell.clear_alt_overlay();
            } else {
                shell.activate_alt_overlay();
            }
        });
        return;
    }
    // A direct accelerator (§11): resolve the pressed chord to its command and
    // dispatch it — the same terminus dispatch the ALT layer uses, so both layers
    // are two views of one command (no second encoding).
    if let Some(accel) = msg.get("accel") {
        let chord = Chord {
            ctrl: accel.get("ctrl").and_then(|v| v.as_bool()).unwrap_or(false),
            alt: accel.get("alt").and_then(|v| v.as_bool()).unwrap_or(false),
            shift: accel.get("shift").and_then(|v| v.as_bool()).unwrap_or(false),
            meta: accel.get("meta").and_then(|v| v.as_bool()).unwrap_or(false),
            key: accel
                .get("key")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .to_string(),
        };
        let command = keytip::accel_command_for(&chord, &state.read().keytip_config);
        if let Some(command) = command {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            dispatch_keytip_node(state, &command);
        }
        return;
    }
    // A shell CHORD claimed on a focused PAGE webview (§13.1's second door).
    // The GTK claimer already consumed the key, so this is DELIVERY, not
    // interception — and it lands on the same opener the shell's own Ctrl+F
    // keydown uses, which is what keeps the two doors from growing different
    // refusals. Its own message, like `modal_key`, so a chord name can never be
    // mistaken for a chord CHARACTER.
    if let Some(chord) = msg.get("chord").and_then(|value| value.as_str()) {
        if chord == WEB_FIND_CHORD_ID {
            open_web_find_for_viewport(state);
            return;
        }
        // The legacy browser layer. Asked BEFORE the keytip dispatch because
        // these ids are not keytip commands — `dispatch_keytip_node` would find
        // no node and the key would silently do nothing, which is the exact
        // failure this layer exists to end.
        if dispatch_web_page_chord(state, chord) {
            return;
        }
        // Every other claimed chord IS a keytip command id, and it lands on the
        // same dispatch the accelerator bridge above uses — so `window.fullscreen`
        // has ONE toggle whichever door the key came through.
        state.with_mut_counted(|shell| shell.clear_alt_overlay());
        dispatch_keytip_node(state, chord);
        return;
    }
    // A PAGE MENU entry the user chose, with the click point in CSS pixels.
    // Its own message, like `chord`: an entry id is not a chord and not a
    // character, and the point only means anything for this one.
    if let Some(menu) = msg.get("page_menu") {
        let Some(id) = menu.get("id").and_then(|value| value.as_str()) else {
            return;
        };
        dispatch_web_page_menu(
            state,
            id,
            menu.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0),
            menu.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0),
        );
        return;
    }
    // §12.3: a dialog key for an open modal, sent while the ALT overlay is
    // CLOSED. Kept as its own message so it can never be confused with a chord
    // character, and so the modal boundary owns the decision.
    if let Some(modal_key) = msg.get("modal_key").and_then(|value| value.as_str()) {
        modal_key_dispatch(state, modal_key);
        return;
    }
    // A floating menu's Escape, sent while the ALT overlay is CLOSED. Its own
    // message for the same reason `modal_key` is: the bridge only sends it while
    // the menu marker is on screen, so it can never be mistaken for a chord
    // character — and it lands on the ONE dismissal terminus the mouse uses.
    if msg.get("menu_key").and_then(|value| value.as_str()) == Some("Escape") {
        dismiss_top_menu(state);
        return;
    }
    // §12.4 (unified): the dialog a DERIVED click just opened. The bridge is the
    // only observer of that edge — the click crossed into JS — and it only sends
    // this while the one-shot armed by that click is live. The shell still checks
    // its OWN precedence, so a message that lost the race to a state change lands
    // on nothing rather than on the wrong dialog.
    if let Some(kind) = msg.get("follow_modal").and_then(|value| value.as_str()) {
        let kind = kind.to_string();
        state.with_mut_counted(|shell| {
            if shell.alt_overlay_active {
                return;
            }
            if shell.top_modal().map(|modal| modal.kind()) == Some(kind.as_str()) {
                shell.descend_alt_overlay_into_modal(&kind);
            }
        });
        return;
    }
    // §12.2: the walk's overlay-open report — the visible interactables that
    // carry no declaration and no per-element exemption. Assign them letters
    // through the ONE ladder and stamp the letters back for the §9 painter.
    if let Some(derive) = msg.get("derive").and_then(|value| value.as_array()) {
        // The scope the walk actually confined itself to (`"root"` or
        // `"modal:<kind>"`). It is the SAME walk that produced these elements,
        // so letters and scope can never describe two different surfaces.
        let scope = msg
            .get("scope")
            .and_then(|value| value.as_str())
            .unwrap_or("root")
            .to_string();
        let elements: Vec<(String, String)> = derive
            .iter()
            .filter_map(|entry| {
                let id = entry.get("id").and_then(|value| value.as_str())?;
                // The walk stamps `d<N>` and nothing else; refuse anything that
                // is not that shape so the stamp lookups stay literal.
                if !(id.starts_with('d')
                    && id.len() > 1
                    && id[1..].chars().all(|c| c.is_ascii_digit()))
                {
                    return None;
                }
                let label = entry
                    .get("label")
                    .and_then(|value| value.as_str())
                    .unwrap_or_default();
                Some((id.to_string(), label.to_string()))
            })
            .collect();
        apply_derived_keytips(state, &scope, &elements);
        return;
    }
    let Some(key) = msg.get("key").and_then(|value| value.as_str()) else {
        return;
    };
    // §12.3 with the layer UP: inside a modal scope the dialog keys belong to
    // the dialog, not to the chord walker — the same three keys, the same one
    // dispatcher as the overlay-closed path, so a modal answers Enter/Escape
    // identically whether the badges are showing or not. The layer closes with
    // the dialog and only with it (Fido2 deliberately swallows Enter, and a
    // swallowed key must not take the badges down with it).
    if state.read().alt_overlay_modal_scope.is_some()
        && matches!(key, "Escape" | "Enter" | "Backspace")
    {
        modal_key_dispatch(state, key);
        state.with_mut_counted(|shell| {
            if shell.top_modal().is_none() {
                shell.clear_alt_overlay();
            }
        });
        return;
    }
    match key {
        // Esc backs all the way out: the overlay AND whatever container it opened.
        // Leaving a keyboard-opened row menu on screen after Esc would strand a
        // surface the keyboard can no longer reach.
        "Escape" => state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.close_context_menu();
            shell.close_titlebar_new_menu();
        }),
        "Backspace" => state.with_mut_counted(|shell| {
            shell.alt_overlay_sequence.pop();
            if shell.alt_overlay_sequence.is_empty() {
                // Back at the root scope: the container this chord had opened is no
                // longer the level being shown, so it closes with the level.
                shell.close_context_menu();
                shell.close_titlebar_new_menu();
                shell.alt_jump_path = None;
            } else if shell.row_menu_page.is_some() {
                // ⚠ A level that is not the last one still has a container to
                // undo. Popping `ALT,E,S` back to `ALT,E` while the menu stayed
                // on the submenu page left the layer showing the PARENT's
                // letters over the CHILD's list — every badge pointing at
                // something else on screen.
                shell.turn_row_menu_page(None);
            }
        }),
        // Jump mode (`ALT,J`): walk the Live list, commit with Enter. Outside jump
        // mode these keys are inert — the bridge already swallowed them so they
        // cannot leak to the PTY behind the overlay.
        "ArrowUp" | "ArrowDown" | "PageUp" | "PageDown" | "Home" | "End" | "Enter"
            if state.read().alt_jump_path.is_some() =>
        {
            if key == "Enter" {
                let target = state.with_mut_counted(|shell| {
                    let path = shell.alt_jump_path.clone();
                    shell.clear_alt_overlay();
                    path.and_then(|path| synthesize_app_control_row(shell, &path))
                });
                if let Some(row) = target {
                    spawn_open_session_row(state, row);
                }
                return;
            }
            let (delta, to_edge) = match key {
                "ArrowUp" | "PageUp" => (-1, false),
                "ArrowDown" | "PageDown" => (1, false),
                "Home" => (-1, true),
                _ => (1, true),
            };
            state.with_mut_counted(|shell| shell.navigate_session_jump(delta, to_edge));
            scroll_sidebar_row_into_view_quietly(state);
        }
        other => {
            let mut chars = other.chars();
            if let (Some(ch), None) = (chars.next(), chars.next()) {
                feed_alt_overlay_char(state, ch);
            }
        }
    }
}
/// §12.2's Rust half: assign the walk's collected elements their letters and
/// stamp them back. The assignment is [`derive_keytips_for_elements`] — the one
/// ladder — and the stamps are `data-keytip-tip`, which the EXISTING §9 painter
/// paints with zero new render code. The map is stored on [`ShellState`] and
/// dies with the overlay.
fn apply_derived_keytips(
    mut state: Signal<ShellState>,
    scope: &str,
    elements: &[(String, String)],
) {
    // The walk is the observer of which surface is on top, so its scope is what
    // reconciles the layer: a dialog that appeared while the overlay was up puts
    // the layer INSIDE it, and a dialog that has gone takes the layer with it
    // (the container the scope named is no longer there to act on).
    let modal_kind = scope.strip_prefix("modal:").map(|kind| kind.to_string());
    let closed = state.with_mut_counted(|shell| {
        if !shell.alt_overlay_active {
            return false;
        }
        if shell.alt_overlay_modal_scope.is_some() && modal_kind.is_none() {
            shell.clear_alt_overlay();
            return true;
        }
        if modal_kind.is_some() && shell.alt_overlay_modal_scope != modal_kind {
            // Entering (or switching) a modal resets the chord: the letters
            // about to be assigned are the dialog's, not the old surface's.
            shell.alt_overlay_sequence.clear();
            shell.alt_derived_sequence.clear();
            shell.alt_jump_path = None;
            shell.alt_overlay_modal_scope = modal_kind.clone();
        }
        false
    });
    if closed {
        return;
    }
    let assignments = {
        let shell = state.read();
        // The overlay closed before the walk answered — a stale report must not
        // stamp letters onto a layer that is no longer up.
        if !shell.alt_overlay_active {
            return;
        }
        // Which letters the REGISTRY already owns on this surface, so derivation
        // can never shadow a declared one (§6). Inside a modal the registry owns
        // nothing at all: the dialog is isolated, so its whole alphabet is free.
        let claimed = if shell.alt_overlay_modal_scope.is_some() {
            Vec::new()
        } else {
            match shell.snapshot().keytip_tree.tips_at(&shell.alt_overlay_sequence) {
                Some(tips) => tips,
                // Not a resolvable scope: derive nothing rather than guess an
                // exclusion set.
                None => return,
            }
        };
        derive_keytips_for_elements(&claimed, elements)
    };
    state.with_mut_counted(|shell| {
        // Replace wholesale: the report is the complete derivation for THIS
        // surface; merging with a previous one could dispatch a dead stamp.
        shell.alt_derived_tips.clear();
        shell.alt_derived_sequence.clear();
        for (id, tip) in &assignments {
            shell.alt_derived_tips.insert(tip.clone(), id.clone());
        }
    });
    let mut script = String::new();
    for (id, tip) in &assignments {
        // Both halves are machine-generated ([a-z0-9] by construction — the id
        // shape is enforced at the bridge terminus, the tip comes from the
        // ladder), so embedding them literally is safe.
        script.push_str(&format!(
            "var el{id} = document.querySelector('[data-keytip-derived-id=\"{id}\"]'); \
             if (el{id}) {{ el{id}.setAttribute('data-keytip-tip', '{tip_upper}'); }}\n",
            tip_upper = tip.to_ascii_uppercase(),
        ));
    }
    if !script.is_empty() {
        let _ = document::eval(&script);
    }
}
/// Derived (snapshot-time) letter assignment — §12.2 achieved at the overlay
/// boundary. ONE assigner: a phantom head re-claims every letter the registry
/// already owns on the surface being shown (`claimed`; declared beats derived,
/// §6), then the walk's elements ladder through the same [`keytip::assign_scope`]
/// as every declaration — title letter, then a–z, then digits, then a two-letter
/// tip when the surface is crowded (§5). Pure and deterministic: elements arrive
/// in document order and the ladder is pure, so the same DOM always yields the
/// same letters.
fn derive_keytips_for_elements(
    claimed: &[String],
    elements: &[(String, String)],
) -> Vec<(String, String)> {
    // Exclude the FIRST char of every claimed tip: a bare letter, a group
    // letter, and a two-letter tip's prefix all make that char unavailable to
    // derivation.
    let mut taken: Vec<char> = claimed
        .iter()
        .filter_map(|tip| tip.chars().next())
        .collect();
    taken.sort_unstable();
    taken.dedup();
    // Phantom claimants (App origin so a reserved letter is claimed VERBATIM —
    // an Origin::Shell phantom would be denied 'n' at root and exclude the
    // wrong letter) followed by the derived elements, hint-less so they take
    // the pure ladder.
    let mut decls: Vec<KeyTipDecl> = taken
        .iter()
        .map(|&letter| {
            KeyTipDecl::app(
                format!("__registry-taken:{letter}"),
                String::new(),
                Some(letter),
                Target::Run,
            )
        })
        .collect();
    for (id, label) in elements {
        decls.push(KeyTipDecl::app(
            format!("derived:{id}"),
            label.clone(),
            None,
            Target::Run,
        ));
    }
    let assigned = keytip::assign_scope(
        &KtScope::App("derived".to_string()),
        &decls,
        &KeymapConfig::default(),
    );
    let mut used: std::collections::BTreeSet<String> =
        taken.iter().map(|letter| letter.to_string()).collect();
    let mut out: Vec<(String, String)> = Vec::new();
    for node in assigned {
        if let keytip::AssignedNode::Leaf { key, tip, .. } = node {
            let Some(id) = key.strip_prefix("derived:") else {
                continue;
            };
            // A crowded surface now overflows into two-letter tips (§5 step 7),
            // so the ladder no longer repeats itself — but a tip that somehow
            // arrived twice still cannot dispatch unambiguously, so the first
            // claimant (document order) keeps it and the duplicate is dropped
            // rather than badged with a letter that would fire the other one.
            if !used.insert(tip.clone()) {
                continue;
            }
            out.push((id.to_string(), tip));
        }
    }
    out
}
/// `~/.yggterm/keymap.json` — the directly-editable ALT+ keymap override file.
fn keymap_config_path() -> Option<std::path::PathBuf> {
    yggterm_core::resolve_yggterm_home()
        .ok()
        .map(|home| home.join("keymap.json"))
}
/// The keymap-v2 config on disk (spec §11.5):
///
/// ```jsonc
/// { "version": 2,
///   "keytips":      { "sidebar.toggle": "b" },              // ALT letters
///   "pinned":       { "insert.menu/n/ychrome": 1 },         // group numbers (§6)
///   "accelerators": { "insert.terminal": "Ctrl+Shift+T" } } // direct chords
/// ```
///
/// v1's `bindings` is still read as a legacy alias for `keytips`. A corrupt file
/// falls back to defaults so it never bricks the accelerators.
fn parse_keytip_config(text: &str) -> KeymapConfig {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(text) else {
        return KeymapConfig::default();
    };
    let mut config = KeymapConfig::default();
    // keytips (v2) with `bindings` (v1) as an alias.
    for section in ["keytips", "bindings"] {
        if let Some(map) = value.get(section).and_then(|v| v.as_object()) {
            for (id, letter) in map {
                if let Some(ch) = letter.as_str().and_then(|s| s.chars().next()) {
                    if ch.is_ascii_alphanumeric() {
                        config.set_keytip(id.clone(), ch);
                    }
                }
            }
        }
    }
    if let Some(map) = value.get("pinned").and_then(|v| v.as_object()) {
        for (key, number) in map {
            if let Some(n) = number.as_u64() {
                config.pin_number(key.clone(), n as u32);
            }
        }
    }
    if let Some(map) = value.get("accelerators").and_then(|v| v.as_object()) {
        for (id, chord) in map {
            if let Some(spec) = chord.as_str() {
                if let Some(parsed) = keytip::Chord::parse(spec) {
                    if parsed.is_pty_safe() {
                        config.set_accel(id.clone(), parsed);
                    }
                }
            }
        }
    }
    config
}
/// Derive the legacy [`Keymap`] view (letters only) from the unified config, so
/// the existing editor + resolver keep working off one disk source.
fn keymap_from_keytip_config(config: &KeymapConfig) -> Keymap {
    Keymap::from_overrides(config.keytips().iter().map(|(id, ch)| (id.clone(), *ch)))
}
/// Load the unified keymap-v2 config from `~/.yggterm/keymap.json` (v1-compatible).
fn load_keytip_config_from_disk() -> KeymapConfig {
    let Some(path) = keymap_config_path() else {
        return KeymapConfig::default();
    };
    match std::fs::read_to_string(&path) {
        Ok(text) => parse_keytip_config(&text),
        Err(_) => KeymapConfig::default(),
    }
}
/// Persist the unified config as keymap-v2 (sparse — only overrides, pins, and
/// accelerator overrides, so the file stays a small hand-editable diff).
fn save_keytip_config_to_disk(config: &KeymapConfig) {
    let Some(path) = keymap_config_path() else {
        return;
    };
    let keytips: serde_json::Map<String, serde_json::Value> = config
        .keytips()
        .iter()
        .map(|(id, ch)| (id.clone(), serde_json::Value::String(ch.to_string())))
        .collect();
    let pinned: serde_json::Map<String, serde_json::Value> = config
        .pinned()
        .iter()
        .map(|(key, n)| (key.clone(), serde_json::Value::from(*n)))
        .collect();
    let accelerators: serde_json::Map<String, serde_json::Value> = config
        .accelerators()
        .iter()
        .map(|(id, chord)| (id.clone(), serde_json::Value::String(chord.display())))
        .collect();
    let doc = serde_json::json!({
        "version": 2,
        "keytips": keytips,
        "pinned": pinned,
        "accelerators": accelerators,
    });
    if let Ok(text) = serde_json::to_string_pretty(&doc) {
        let _ = std::fs::write(&path, text);
    }
}
/// The node key for a libyggterm app's verb in the New… scope. This is the
/// declaration key the resolver assigns a letter to and the marker/dispatch key,
/// so a chord like `ALT, I, N` reaches exactly this verb.
fn app_verb_node_key(app: &str, verb: &str) -> String {
    format!("appverb:{app}:{verb}")
}
/// Build every open scope's KeyTip declarations for this frame (spec §1, §4).
/// The tree is assembled in Rust during render — never scraped from the DOM. The
/// shell chrome comes from [`command_registry::SHELL_COMMANDS`] (its letters,
/// titles, and structure stay the SSOT); the New… scope additionally carries the
/// first-class "New Claude Code" item and one node per installed app verb
/// (`~/.yggterm/apps/*.json`, spec §10), so an app the shell never heard of
/// extends the layer without the shell changing.
fn build_keytip_scopes(
    apps: &[AppManifest],
    row_menu: &[RowMenuItem],
) -> Vec<(KtScope, Vec<KeyTipDecl>)> {
    let mut root: Vec<KeyTipDecl> = Vec::new();
    let mut insert: Vec<KeyTipDecl> = Vec::new();
    for spec in command_registry::SHELL_COMMANDS {
        let Some(hint) = spec.default_keytip else {
            continue; // accel-only commands (session nav) have no ALT letter
        };
        // A command that opens a container descends into that container's scope
        // (spec §4). WHICH scope is registry data, not a match arm here.
        let target = match spec.descends_into {
            Some(scope) => Target::Descend(keytip_scope_from_id(scope)),
            None => Target::Run,
        };
        let decl = KeyTipDecl::shell(spec.id, spec.title, hint, target);
        match spec.parent {
            None => root.push(decl),
            Some("insert.menu") => insert.push(decl),
            Some(_) => root.push(decl),
        }
    }
    // "New Claude Code" is a first-class agent launch (not in the enum registry
    // yet) but belongs in the New… scope between session and terminal.
    if let Some(pos) = insert
        .iter()
        .position(|decl| decl.key == "insert.terminal")
    {
        insert.insert(
            pos,
            KeyTipDecl::shell("insert.claude", "New Claude Code", 'c', Target::Run),
        );
    } else {
        insert.push(KeyTipDecl::shell(
            "insert.claude",
            "New Claude Code",
            'c',
            Target::Run,
        ));
    }
    // App verbs — the dynamic feed. Origin::App, so they may be denied a hint or
    // folded into a numbered group when two apps want the same letter.
    for (app, verb) in app_launcher_entries(apps) {
        let hint = verb
            .keytip
            .chars()
            .next()
            .or_else(|| app.keytip.chars().next());
        insert.push(KeyTipDecl::app(
            app_verb_node_key(&app.name, &verb.id),
            verb.label.clone(),
            hint,
            Target::Run,
        ));
    }
    // The Settings scope (spec §4): the theme options are flat in the panel, so
    // they get direct letters (ALT,G then L/D) — one key shorter than the spec's
    // ALT,G,T,<letter> nesting, which the flat panel makes redundant.
    let settings = vec![
        KeyTipDecl::shell("theme.light", "Light theme", 'l', Target::Run),
        KeyTipDecl::shell("theme.dark", "Dark theme", 'd', Target::Run),
    ];
    // The ROW MENU scope (ALT,E) — declared from the very list the mouse menu
    // draws ([`row_menu_items`]), so the two can never disagree about what exists.
    // Empty while no row menu is open, which is the only time it is unreachable.
    //
    // ⚠ A DISABLED item is not declared. This is the ALT layer's half of
    // `RowMenuItem::disabled`: the mouse path refuses a dimmed item at the
    // dispatch ([`context_menu_item_dispatches`]), and the keyboard path never
    // gets a letter for it, so neither view can run a verb the other refuses.
    // Filtering here rather than guarding `dispatch_keytip_node` is deliberate —
    // an undeclared node has no badge either, so the overlay cannot paint an
    // accelerator that would do nothing.
    //
    // ⚖ An item that OPENS a submenu declares `Target::Descend` into that
    // submenu's own scope, and every child scope is declared on the SAME frame
    // whether or not the submenu is drawn. That is what lets `ALT,E,S,L` run
    // straight through: the chord resolver walks scopes, not pixels, so the
    // keyboard never has to visit a page the mouse would have had to turn to.
    let rowmenu: Vec<KeyTipDecl> = row_menu
        .iter()
        .filter(|item| !item.separator && !item.disabled)
        .map(|item| {
            let target = if item.submenu.is_empty() {
                Target::Run
            } else {
                Target::Descend(KtScope::RowMenuSub(item.id.clone()))
            };
            KeyTipDecl::shell_optional(
                row_menu_node_key(&item.id),
                item.label.clone(),
                item.hint,
                target,
            )
        })
        .collect();
    let rowmenu_children: Vec<(KtScope, Vec<KeyTipDecl>)> = row_menu
        .iter()
        .filter(|item| !item.submenu.is_empty())
        .map(|item| {
            let decls = item
                .submenu
                .iter()
                .filter(|child| !child.separator && !child.disabled)
                .map(|child| {
                    KeyTipDecl::shell_optional(
                        row_menu_node_key(&child.id),
                        child.label.clone(),
                        child.hint,
                        Target::Run,
                    )
                })
                .collect();
            (KtScope::RowMenuSub(item.id.clone()), decls)
        })
        .collect();
    let mut scopes = vec![
        (KtScope::Root, root),
        (KtScope::Insert, insert),
        (KtScope::Settings, settings),
        (KtScope::RowMenu, rowmenu),
        // Jump-to-session is a NAVIGATION scope, not a badge scope (spec §8 —
        // lists are navigated, not badged): it holds no declarations, and the
        // arrow/PageUp/PageDown/Enter keys are handled by the bridge while it is
        // the open scope.
        (KtScope::SessionJump, Vec::new()),
    ];
    scopes.extend(rowmenu_children);
    scopes
}
/// Map a registry scope id (`descends_into`) to the resolver's scope. One place
/// that knows the scope vocabulary.
fn keytip_scope_from_id(scope: &str) -> KtScope {
    match scope {
        "insert.menu" => KtScope::Insert,
        "settings" => KtScope::Settings,
        "settings.theme" => KtScope::SettingsTheme,
        "rowmenu" => KtScope::RowMenu,
        "session.jump" => KtScope::SessionJump,
        other => KtScope::App(other.to_string()),
    }
}
/// The resolved KeyTip tree for a snapshot: the single source both the badge
/// painter and the chord walker read. Driven by the unified keymap-v2 config
/// (letters + pins + accelerator overrides), the disk SSOT.
fn build_keytip_tree(
    config: &KeymapConfig,
    apps: &[AppManifest],
    row_menu: &[RowMenuItem],
) -> KeyTipTree {
    KeyTipTree::build(&build_keytip_scopes(apps, row_menu), config)
}
/// The stable `data-keytip-node` id for a declaration key, used as the floating-
/// badge painter's measurement anchor and the orphan audit's proof that this
/// interactable is declared (spec §9, §12). Shell commands derive their scope
/// from the registry; other keys (app verbs, `insert.claude`) live in the New…
/// scope.
fn keytip_node_id(node_key: &str) -> String {
    let scope = spec_for_id(node_key)
        .and_then(|spec| spec.parent)
        .unwrap_or_else(|| {
            if node_key.starts_with("appverb:") || node_key == "insert.claude" {
                "insert.menu"
            } else if node_key.starts_with("theme.") {
                "settings"
            } else if node_key.starts_with("rowmenu:") {
                // A submenu leaf's key is `rowmenu:<opener>/<leaf>`; its scope
                // is the opener's, not the parent menu's, or the §12 audit
                // reports both levels as one scope and the badge painter asks
                // the wrong list for its letter.
                //
                // Returned as an owned String below; the borrow shape here only
                // needs to distinguish the two cases.
                "rowmenu"
            } else {
                "root"
            }
        });
    if scope == "rowmenu" {
        if let Some(rest) = node_key.strip_prefix("rowmenu:") {
            if let Some((opener, _leaf)) = rest.split_once('/') {
                return format!("rowmenu.{opener}/{node_key}");
            }
        }
    }
    format!("{scope}/{node_key}")
}
/// The `data-keytip-tip` value for a node: the assigned letter (or group number),
/// uppercased, when the overlay is up and this node's scope is the one being
/// shown; else an empty string. The floating painter skips empty tips; the marker
/// carries `data-keytip-node` regardless so the audit always sees it. Reads only
/// the resolved tree — SSOT with the chord walker.
fn keytip_tip_attr(snapshot: &RenderSnapshot, node_key: &str) -> String {
    keytip_tip_for(
        &snapshot.keytip_tree,
        keytip_declared_badges_active(snapshot),
        &snapshot.alt_overlay_sequence,
        node_key,
    )
}
/// Whether DECLARED (registry) badges may paint at all this frame.
///
/// The layer being up is not enough: inside a modal scope (§4) the registry is
/// out of the walk entirely, so a badge on the chrome behind the dialog would
/// advertise a key that does nothing — the exact species of lie this layer
/// exists to end. Caught on the first live pixel of the modal scope: the
/// KeyTips editor was fully badged and the titlebar was ALSO wearing B/V/T/I.
fn keytip_declared_badges_active(snapshot: &RenderSnapshot) -> bool {
    snapshot.alt_overlay_active && snapshot.alt_overlay_modal_scope.is_none()
}
/// The tip lookup itself, over the raw tree — so a component that holds the tree
/// without the whole snapshot (the row menu) badges from the same SSOT.
fn keytip_tip_for(
    tree: &KeyTipTree,
    alt_overlay_active: bool,
    sequence: &str,
    node_key: &str,
) -> String {
    if !alt_overlay_active {
        return String::new();
    }
    tree.tip_for(sequence, node_key)
        .or_else(|| tree.group_member_tip(sequence, node_key))
        .unwrap_or_default()
}
/// Dispatch a registry command. Every ALT+ KeyTip, the `command invoke <id>`
/// probe, and the settings modal funnel through here — one action per command.
fn execute_shell_command(mut state: Signal<ShellState>, command: ShellCommand) {
    match command {
        ShellCommand::ToggleSidebar => {
            // Opening the sidebar from the keyboard (ALT,B) also focuses a row so
            // arrow-key navigation works without a mouse click first (§8). Keeps an
            // existing selection; otherwise focuses the first navigable row.
            let focus_path = state.with_mut_counted(|shell| {
                shell.clear_alt_overlay();
                shell.toggle_sidebar();
                if !shell.sidebar_open {
                    return None;
                }
                // Focus the existing selection if there is one, else the first row —
                // either way the sidebar gains DOM focus so arrows route to it.
                match current_selected_sidebar_row(shell) {
                    Some(row) => Some(row.full_path),
                    None => shell.navigate_sidebar_selection(-1, true),
                }
            });
            if let Some(path) = focus_path {
                scroll_sidebar_row_into_view(&path);
            }
        }
        ShellCommand::FocusSearch => {
            state.with_mut_counted(|shell| {
                shell.clear_alt_overlay();
                shell.set_search_focus(true);
            });
            focus_search_input(true);
        }
        ShellCommand::ViewWeb => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            spawn_set_view_mode(state, WorkspaceViewMode::Rendered);
        }
        ShellCommand::ViewTerminal => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            spawn_set_view_mode(state, WorkspaceViewMode::Terminal);
        }
        ShellCommand::ToggleConnect => state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.toggle_connect_panel();
        }),
        ShellCommand::ToggleNotifications => state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.toggle_notifications_panel();
        }),
        ShellCommand::ToggleSettings => {
            // Opening Settings from the keyboard (ALT,G) also moves focus into the
            // panel, exactly as ToggleSidebar above focuses a row (§8). The panel's
            // blanket `data-keytip-exempt="settings-panel"` is justified by calling
            // it "a Tab-navigable configuration surface" — and its 25 controls ARE
            // natively focusable with nothing intercepting Tab, but measuring it
            // live on 2026-07-22 showed `activeElement` stuck on <body> with the
            // panel open, so the Tab chain never began inside the panel and the
            // user still had to reach for the mouse. Focusing the head of the chain
            // is what makes that justification true.
            let opened = state.with_mut_counted(|shell| {
                shell.clear_alt_overlay();
                shell.toggle_settings_panel();
                shell.displayed_right_panel_mode() == RightPanelMode::Settings
            });
            if opened {
                focus_settings_field(state, SETTINGS_FIRST_FIELD_KEY);
            }
        }
        ShellCommand::ToggleMetadata => state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.toggle_metadata_panel();
        }),
        ShellCommand::ToggleFullscreen => state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.toggle_fullscreen();
        }),
        ShellCommand::ToggleAlwaysOnTop => state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.toggle_always_on_top();
        }),
        ShellCommand::OpenKeymapEditor => state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.open_keymap_editor();
        }),
        ShellCommand::OpenInsertMenu => {
            // Both an action and a chord node: open the New… menu AND descend a
            // level so the submenu's KeyTips paint. Park the overlay at the
            // insert chord (keymap-derived, not the hardcoded "i").
            let insert_chord = state
                .read()
                .keymap
                .chord_for_id("insert.menu")
                .unwrap_or_default();
            state.with_mut_counted(|shell| {
                shell.alt_overlay_active = true;
                shell.alt_overlay_sequence = insert_chord;
                shell.titlebar_session_menu_open = false;
                shell.titlebar_new_menu_open = true;
            });
        }
        ShellCommand::OpenRowMenu => {
            // Both an action and a chord node (like the `+` menu): open the row
            // menu on the "here" row AND park the overlay at this command's chord
            // so the menu's own KeyTips paint.
            let chord = state
                .read()
                .keymap
                .chord_for_id("session.menu")
                .unwrap_or_default();
            state.with_mut_counted(|shell| {
                shell.alt_overlay_active = true;
                shell.alt_overlay_sequence = chord;
            });
            spawn_open_row_menu_here(state);
        }
        ShellCommand::JumpSession => {
            let chord = state
                .read()
                .keymap
                .chord_for_id("session.jump")
                .unwrap_or_default();
            state.with_mut_counted(|shell| {
                shell.alt_overlay_active = true;
                shell.alt_overlay_sequence = chord;
                shell.begin_session_jump();
            });
            scroll_sidebar_row_into_view_quietly(state);
        }
        ShellCommand::InsertSession => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            spawn_start_preferred_agent_session(state);
        }
        ShellCommand::InsertTerminal => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            spawn_start_terminal_session(state);
        }
        ShellCommand::NextSession => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            spawn_switch_live_session(state, true);
        }
        ShellCommand::PrevSession => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            spawn_switch_live_session(state, false);
        }
    }
}
/// Feed one character into the open KeyTips chord (fed by the below-the-webview
/// bridge, [`keytip_apply_bridge_message`]). Mirrors the Excel walk: extend the
/// sequence, resolve it against the resolved tree, then act — wait (Pending),
/// descend into a scope/group, run a node's action, or dismiss (Invalid).
fn feed_alt_overlay_char(mut state: Signal<ShellState>, ch: char) {
    if !state.read().alt_overlay_active {
        return;
    }
    // Two cases where the REGISTRY is out of the walk entirely:
    //
    // - a modal scope (§4): the dialog owns the screen, so a letter must never
    //   reach the chrome behind it — its letters are its own derivation;
    // - a derived two-letter tip in flight (§5 step 7): the second key belongs
    //   to the prefix that is waiting, never to a registry letter that happens
    //   to share it.
    let derived_only = {
        let shell = state.read();
        shell.alt_overlay_modal_scope.is_some() || !shell.alt_derived_sequence.is_empty()
    };
    if derived_only {
        feed_alt_derived_char(state, ch);
        return;
    }
    let (next_sequence, resolution) = {
        let shell = state.read();
        let next = format!("{}{}", shell.alt_overlay_sequence, ch.to_ascii_lowercase());
        // The SAME tree the badges are painted from (it carries the open row
        // menu's scope), so what you see is exactly what the chord resolves to.
        let tree = shell.snapshot().keytip_tree;
        (next.clone(), tree.resolve(&next))
    };
    match resolution {
        ChordResolution::Pending => state.with_mut_counted(|shell| {
            shell.alt_overlay_active = true;
            shell.alt_overlay_sequence = next_sequence;
        }),
        ChordResolution::Descend { key, scope: _ } => {
            // Open the container this node governs (e.g. the New… menu), then park
            // the overlay at the typed sequence so the child scope's badges paint.
            if !key.is_empty() {
                dispatch_keytip_open(state, &key);
            }
            state.with_mut_counted(|shell| {
                shell.alt_overlay_active = true;
                shell.alt_overlay_sequence = next_sequence;
            });
        }
        ChordResolution::Run(key) => {
            dispatch_keytip_node(state, &key);
            follow_chord_into_modal(state);
        }
        // §12.2: a letter the registry tree does not know may still be a DERIVED
        // tip — the assignment the walk made for the surface on screen. Registry
        // resolution ran first (it produced the Invalid), so a declared letter is
        // never shadowed.
        ChordResolution::Invalid => feed_alt_derived_char(state, ch),
    }
}
/// §4/§12.3 — a chord that opened a DIALOG opened a container, so the layer
/// follows the keyboard into it instead of ending at the mouse. This is the
/// user's `ALT,E,X` report: the dialog appeared with no letters on its buttons
/// because dispatch is act-and-DISMISS and the layer went down with it.
///
/// Synchronous, at the one chord terminus, deliberately: every dialog a chord
/// can raise is raised inside its dispatch (`open_context_menu_delete_for_row`,
/// `copy_edit_dialog`, …), so the shell KNOWS on the same tick and nothing has
/// to watch the DOM for a dialog to appear. `!alt_overlay_active` is the guard
/// that keeps this to act-and-dismiss nodes — a node that DESCENDS parks the
/// layer itself and must not be re-parked here. Accelerators (§11) deliberately
/// do not call this: a flat chord is not a chord walk, and raising badges after
/// `Ctrl+Shift+X` would be a surprise.
fn follow_chord_into_modal(mut state: Signal<ShellState>) {
    state.with_mut_counted(|shell| {
        if shell.alt_overlay_active {
            return;
        }
        let Some(modal) = shell.top_modal() else {
            return;
        };
        // §12.4 (user-corrected): EVERY dialog gets its own ALT layer. A form
        // dialog is not an exception — it is a dialog with a focus path as well.
        shell.descend_alt_overlay_into_modal(modal.kind());
    });
}
/// One key against the DERIVED map (§12.2), which is where a modal's letters and
/// a crowded surface's overflow live. Mirrors the registry walk one level down:
/// a tip fires, a two-letter tip's first key waits (§5 step 7), anything else
/// dismisses the layer exactly as an unknown letter always has.
fn feed_alt_derived_char(mut state: Signal<ShellState>, ch: char) {
    let (next, resolution) = {
        let shell = state.read();
        let next = format!(
            "{}{}",
            shell.alt_derived_sequence,
            ch.to_ascii_lowercase()
        );
        let resolution = keytip::resolve_derived(&shell.alt_derived_tips, &next);
        (next, resolution)
    };
    match resolution {
        keytip::DerivedResolution::Pending => {
            state.with_mut_counted(|shell| shell.alt_derived_sequence = next);
        }
        keytip::DerivedResolution::Hit(id) => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            // The id shape was enforced at the bridge terminus (`d<N>`), so the
            // selector is literal. Focus-then-click: click activates a button,
            // focus is the useful half for an input/select.
            //
            // §12.4 (unified): if this click opens a DIALOG, the layer follows it
            // in — "entering a modal with the ALT mode on triggers its alt mode
            // on". A registry chord can be followed synchronously, but this one
            // cannot: the click crosses into JS, so the dialog appears a frame or
            // two later. The one-shot below is set in the SAME eval as the click,
            // which is what ties the two together; the bridge consumes it when a
            // new modal appears, and drops it on any real user input or after a
            // few idle ticks, so a dialog opened minutes later by the mouse can
            // never inherit it.
            let _ = document::eval(&format!(
                "var el = document.querySelector('[data-keytip-derived-id=\"{id}\"]'); \
                 if (el) {{ window.__yggtermFollowNextModal = 6; \
                 if (el.focus) {{ el.focus(); }} el.click(); }}"
            ));
        }
        keytip::DerivedResolution::Miss => {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
        }
    }
}
/// Run a container-opening node's side effect (a `Descend` target) without
/// dismissing the overlay: it stays up so the descended scope's badges show.
fn dispatch_keytip_open(mut state: Signal<ShellState>, key: &str) {
    match key {
        "insert.menu" => state.with_mut_counted(|shell| {
            shell.titlebar_session_menu_open = false;
            shell.titlebar_new_menu_open = true;
        }),
        "settings.toggle" => {
            // Descending into Settings OPENS the panel (never toggles it shut), so
            // the theme options are on screen to badge (spec §4).
            state.with_mut_counted(|shell| shell.set_right_panel_mode(RightPanelMode::Settings));
            // ...and focuses the head of its Tab chain, exactly as the Run arm in
            // `execute_shell_command` does. `settings.toggle` DESCENDS (registry
            // `descends_into: Some("settings")`), so ALT,G — the primary keyboard
            // route — lands HERE and never in that arm: fixing only the Run arm
            // would have left the real chord unfixed while the probe passed. Same
            // two-dispatch-arm shape as the yedit declare/ping trap.
            // Safe during a chord: the walker is a WINDOW-level keydown listener
            // that claims chord keys "at any focus" and preventDefaults them while
            // the overlay is open, so ALT,G,L still reaches the theme node.
            focus_settings_field(state, SETTINGS_FIRST_FIELD_KEY);
        }
        // ALT,E — the row menu, on the "here" row. The menu is a positioned
        // surface, so it opens where a right-click on that row would have put it.
        "session.menu" => spawn_open_row_menu_here(state),
        // ALT,J — jump mode. The live list is walked, not badged (§8).
        "session.jump" => state.with_mut_counted(|shell| shell.begin_session_jump()),
        // ALT,E,<letter> onto a submenu opener — turn the drawn menu to that
        // page so the mouse and the keyboard are looking at the same list.
        //
        // ⚠ The CHORD does not need this: the child scope is declared every
        // frame, so `ALT,E,S,L` would resolve even if nothing turned. Turning
        // is for the human who stops after `S` — without it they would see the
        // parent list wearing the child's badges, which is the worst of both.
        key if key.starts_with("rowmenu:") => {
            let opener = key.trim_start_matches("rowmenu:").to_string();
            state.with_mut_counted(|shell| shell.turn_row_menu_page(Some(opener)));
        }
        _ => {}
    }
}
/// Run a leaf node's action and dismiss the overlay. One dispatch for every ALT+
/// chord terminus: a shell command funnels through [`execute_shell_command`], the
/// first-class Claude Code launch and any app verb launch route to their spawn
/// helpers. The node key is the resolver's SSOT identity for the target.
fn dispatch_keytip_node(mut state: Signal<ShellState>, key: &str) {
    if let Some(spec) = spec_for_id(key) {
        execute_shell_command(state, spec.command);
        return;
    }
    // A row-menu item (ALT,E,<letter>): the SAME terminus a click on that item
    // takes, keyed by the same id (spec §3 — one command, two views).
    if let Some(id) = key.strip_prefix("rowmenu:") {
        let id = id.to_string();
        let Some(row) = state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            // The RESOLVED row, the same one the drawn menu was built from: a
            // chord must not act on an anchor that has left the tree.
            shell.live_context_menu_row()
        }) else {
            return;
        };
        dispatch_row_menu_action(state, row, id);
        return;
    }
    if key == "insert.claude" {
        // Clears the overlay + closes the menu itself.
        spawn_start_agent_session_for_row(state, None, SessionKind::ClaudeCode);
        return;
    }
    if let Some(theme) = match key {
        "theme.light" => Some(UiTheme::ZedLight),
        "theme.dark" => Some(UiTheme::ZedDark),
        _ => None,
    } {
        state.with_mut_counted(|shell| {
            shell.clear_alt_overlay();
            shell.set_ui_theme(theme);
        });
        return;
    }
    if let Some(rest) = key.strip_prefix("appverb:") {
        let Some((app_name, verb_id)) = rest.split_once(':') else {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            return;
        };
        // Resolve against the registry of the machine "here" resolves to — the
        // same list the ladder drew this entry from.
        let entry = state.with(|shell| {
            let anchor = here_row(shell);
            resolve_app_verb_for_row(shell, anchor.as_ref(), app_name, verb_id)
        });
        let Some((app, verb)) = entry else {
            state.with_mut_counted(|shell| shell.clear_alt_overlay());
            return;
        };
        // "Here" resolves identically for the KeyTip and for the mouse (invariant
        // 10): the focused sidebar row, else the active session — cwd AND sidebar
        // insert position both.
        spawn_launch_app_verb_here(state, app, verb, None);
        return;
    }
    // Unknown key: fail safe by dismissing rather than acting on nothing.
    state.with_mut_counted(|shell| shell.clear_alt_overlay());
}
fn execute_search_command(mut state: Signal<ShellState>, query: String) {
    let command = query.trim().to_ascii_lowercase();
    match command.as_str() {
        "/preview" | "/web-view" => spawn_set_view_mode(state, WorkspaceViewMode::Rendered),
        "/terminal" => spawn_set_view_mode(state, WorkspaceViewMode::Terminal),
        "/refresh" => spawn_server_snapshot_action(
            state,
            "refreshing workspace".to_string(),
            move |endpoint| daemon_snapshot(&endpoint),
        ),
        "/expand-all" => {
            spawn_server_snapshot_action(state, "expanding preview".to_string(), move |endpoint| {
                set_all_preview_blocks_folded(&endpoint, false)
            });
        }
        "/collapse-all" => {
            spawn_server_snapshot_action(
                state,
                "collapsing preview".to_string(),
                move |endpoint| set_all_preview_blocks_folded(&endpoint, true),
            );
        }
        "/settings" => {
            state.with_mut_counted(|shell| shell.toggle_settings_panel());
            sync_active_terminal_input_policy(state);
        }
        "/metadata" => {
            state.with_mut_counted(|shell| shell.toggle_metadata_panel());
            sync_active_terminal_input_policy(state);
        }
        "/notifications" => {
            state.with_mut_counted(|shell| shell.toggle_notifications_panel());
            sync_active_terminal_input_policy(state);
        }
        "/connect" => {
            state.with_mut_counted(|shell| shell.toggle_connect_panel());
            sync_active_terminal_input_policy(state);
        }
        _ => state.with_mut_counted(|shell| {
            shell.push_notification(
                NotificationTone::Warning,
                "Unknown Command",
                format!("{command} is not a recognized yggterm command."),
            );
        }),
    }
    state.with_mut_counted(|shell| {
        shell.set_search(String::new());
        shell.set_search_focus(false);
    });
}
fn filtered_sidebar_rows(rows: &[BrowserRow], query: &str) -> Vec<BrowserRow> {
    let terms = search_terms(query);
    if terms.is_empty() {
        return rows.to_vec();
    }
    let key = sidebar_search_cache_key(rows, query, 1);
    if let Ok(mut cache) = sidebar_search_cache().lock() {
        if let Some(hit) = cache.entries.get(&key).cloned() {
            if let Some(ix) = cache.order.iter().position(|existing| *existing == key) {
                cache.order.remove(ix);
            }
            cache.order.push_back(key);
            return hit;
        }
    }
    let mut ancestor_stack = Vec::<String>::new();
    let mut ancestors_by_path = HashMap::<String, Vec<String>>::new();
    for row in rows {
        ancestor_stack.truncate(row.depth);
        ancestors_by_path.insert(row.full_path.clone(), ancestor_stack.clone());
        if matches!(row.kind, BrowserRowKind::Group | BrowserRowKind::Separator) {
            ancestor_stack.push(row.full_path.clone());
        }
    }
    let mut keep_paths = HashSet::<String>::new();
    for row in rows {
        if row_matches_search(row, &terms) {
            keep_paths.insert(row.full_path.clone());
            if let Some(ancestors) = ancestors_by_path.get(&row.full_path) {
                keep_paths.extend(ancestors.iter().cloned());
            }
        }
    }
    let filtered = rows
        .iter()
        .filter(|row| keep_paths.contains(&row.full_path))
        .cloned()
        .collect::<Vec<_>>();
    if let Ok(mut cache) = sidebar_search_cache().lock() {
        cache.entries.insert(key, filtered.clone());
        if let Some(ix) = cache.order.iter().position(|existing| *existing == key) {
            cache.order.remove(ix);
        }
        cache.order.push_back(key);
        while cache.order.len() > SIDEBAR_SEARCH_CACHE_LIMIT {
            if let Some(oldest) = cache.order.pop_front() {
                cache.entries.remove(&oldest);
            }
        }
    }
    filtered
}
fn sidebar_rows_for_render(rows: &[BrowserRow], query: &str) -> Vec<BrowserRow> {
    let mut filtered = filtered_sidebar_rows(rows, query);
    if search_terms(query).is_empty() || filtered.len() <= SIDEBAR_SEARCH_RENDER_LIMIT {
        return filtered;
    }
    filtered.truncate(SIDEBAR_SEARCH_RENDER_LIMIT);
    filtered
}
fn search_expanded_paths(
    stored_rows: &[BrowserRow],
    remote_machines: &[RemoteMachineSnapshot],
    ssh_targets: &[SshConnectTarget],
    live_sessions: &[ManagedSessionView],
    base_expanded_paths: &HashSet<String>,
) -> HashSet<String> {
    let mut expanded = base_expanded_paths.clone();
    for row in stored_rows {
        if matches!(row.kind, BrowserRowKind::Group | BrowserRowKind::Separator) {
            expanded.insert(row.full_path.clone());
        }
    }
    let mut machine_rows = BTreeMap::<String, SidebarRemoteMachine>::new();
    for target in ssh_targets {
        let machine_key = machine_key_from_labelish(&target.ssh_target);
        machine_rows
            .entry(machine_key.clone())
            .or_insert_with(|| SidebarRemoteMachine {
                key: machine_key.clone(),
                label: ssh_target_machine_label(target),
                health: MachineHealth::Cached,
                remote_deploy_state: RemoteDeployState::Planned,
                scanned_sessions: Vec::new(),
                workspace_folders: Vec::new(),
                needs_resort: false,
            });
    }
    for machine in remote_machines {
        let mut scanned_sessions = machine.sessions.clone();
        sort_remote_scanned_sessions_by_recency(&mut scanned_sessions);
        machine_rows.insert(
            machine.machine_key.clone(),
            SidebarRemoteMachine {
                key: machine.machine_key.clone(),
                label: machine.label.clone(),
                health: match machine.health {
                    RemoteMachineHealth::Healthy => MachineHealth::Healthy,
                    RemoteMachineHealth::Cached => MachineHealth::Cached,
                    RemoteMachineHealth::Offline => MachineHealth::Offline,
                },
                remote_deploy_state: machine.remote_deploy_state,
                scanned_sessions,
                workspace_folders: Vec::new(),
                needs_resort: false,
            },
        );
    }
    for row in stored_rows {
        let Some((machine_key, folder)) = remote_workspace_folder_from_row(row) else {
            continue;
        };
        let machine =
            machine_rows
                .entry(machine_key.clone())
                .or_insert_with(|| SidebarRemoteMachine {
                    key: machine_key.clone(),
                    label: machine_key.clone(),
                    health: MachineHealth::Cached,
                    remote_deploy_state: RemoteDeployState::Planned,
                    scanned_sessions: Vec::new(),
                    workspace_folders: Vec::new(),
                    needs_resort: false,
                });
        if !machine
            .workspace_folders
            .iter()
            .any(|existing| existing.cwd == folder.cwd)
        {
            machine.workspace_folders.push(folder);
        }
    }
    merge_remote_live_sessions(&mut machine_rows, ssh_targets, live_sessions);
    for machine in machine_rows.into_values() {
        expanded.insert(format!("__remote_machine__/{}", machine.key));
        for session in &machine.scanned_sessions {
            for path in compressed_remote_folder_paths(&machine.scanned_sessions, &session.cwd) {
                expanded.insert(format!("__remote_folder__/{}{}", machine.key, path));
            }
        }
        for folder in &machine.workspace_folders {
            for path in compressed_remote_folder_paths(&machine.scanned_sessions, &folder.cwd) {
                expanded.insert(format!("__remote_folder__/{}{}", machine.key, path));
            }
            expanded.insert(format!("__remote_folder__/{}{}", machine.key, folder.cwd));
        }
    }
    expanded
}
fn search_sidebar_matches(rows: &[BrowserRow], query: &str) -> Vec<BrowserRow> {
    let terms = search_terms(query);
    if terms.is_empty() {
        return Vec::new();
    }
    let key = sidebar_search_cache_key(rows, query, 2);
    if let Ok(mut cache) = sidebar_search_cache().lock() {
        if let Some(hit) = cache.entries.get(&key).cloned() {
            if let Some(ix) = cache.order.iter().position(|existing| *existing == key) {
                cache.order.remove(ix);
            }
            cache.order.push_back(key);
            return hit;
        }
    }
    let matches = filtered_sidebar_rows(rows, query)
        .into_iter()
        .filter(|row| {
            matches!(
                row.kind,
                BrowserRowKind::Group | BrowserRowKind::Session | BrowserRowKind::Document
            )
        })
        .filter(|row| row_matches_search(row, &terms))
        .collect::<Vec<_>>();
    if let Ok(mut cache) = sidebar_search_cache().lock() {
        cache.entries.insert(key, matches.clone());
        if let Some(ix) = cache.order.iter().position(|existing| *existing == key) {
            cache.order.remove(ix);
        }
        cache.order.push_back(key);
        while cache.order.len() > SIDEBAR_SEARCH_CACHE_LIMIT {
            if let Some(oldest) = cache.order.pop_front() {
                cache.entries.remove(&oldest);
            }
        }
    }
    matches
}
fn content_search_query(query: &str) -> Option<Vec<String>> {
    let terms = search_terms(query);
    if terms.is_empty() { None } else { Some(terms) }
}
fn search_content_hits(
    session: Option<&ManagedSessionView>,
    view_mode: WorkspaceViewMode,
    query: &str,
) -> Vec<SearchContentHit> {
    let Some(session) = session else {
        return Vec::new();
    };
    let Some(terms) = content_search_query(query) else {
        return Vec::new();
    };
    match view_mode {
        WorkspaceViewMode::Rendered => {
            let mut hits = Vec::new();
            let header_haystack = [
                resolved_session_title_for_search(session),
                resolved_session_precis_for_search(session),
                resolved_session_summary_for_search(session),
            ]
            .into_iter()
            .flatten()
            .collect::<Vec<_>>()
            .join("\n");
            if !header_haystack.trim().is_empty()
                && text_matches_search_terms(&header_haystack, &terms)
            {
                hits.push(SearchContentHit {
                    dom_id: PREVIEW_HEADER_SEARCH_HIT_ID.to_string(),
                    label: "Summary".to_string(),
                });
            }
            // The RAW index, because that is what the rendered row's dom id is
            // built from — a hit keyed by its position in the filtered list
            // scrolls to whatever row happens to sit at that number.
            for (raw_ix, block) in visible_preview_block_rows(session).iter() {
                let haystack = block.lines.join("\n");
                if text_matches_search_terms(&haystack, &terms) {
                    hits.push(SearchContentHit {
                        dom_id: preview_block_dom_id(&session.id, *raw_ix),
                        label: block.timestamp.clone(),
                    });
                }
            }
            hits
        }
        WorkspaceViewMode::Terminal => session
            .terminal_lines
            .iter()
            .enumerate()
            .filter_map(|(ix, line)| {
                if text_matches_search_terms(line, &terms) {
                    Some(SearchContentHit {
                        dom_id: format!("__terminal_line__:{ix}"),
                        label: format!("Line {}", ix + 1),
                    })
                } else {
                    None
                }
            })
            .collect(),
    }
}
fn resolved_session_title_for_search(session: &ManagedSessionView) -> Option<String> {
    let title = session.title.trim();
    if title.is_empty() {
        None
    } else {
        Some(title.to_string())
    }
}
fn resolved_session_precis_for_search(session: &ManagedSessionView) -> Option<String> {
    let precis = metadata_value(session, "Precis");
    if precis.trim().is_empty() {
        None
    } else {
        Some(precis)
    }
}
fn resolved_session_summary_for_search(session: &ManagedSessionView) -> Option<String> {
    let summary = metadata_value(session, "Summary");
    if summary.trim().is_empty() {
        None
    } else {
        Some(summary)
    }
}
fn preview_block_dom_id(session_id: &str, ix: usize) -> String {
    format!("preview-block-{}-{ix}", sanitize_dom_id(session_id))
}
fn sanitize_dom_id(value: &str) -> String {
    value
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '-' })
        .collect()
}
fn format_preview_timestamp_label(raw: &str, last_date_key: &mut Option<(i32, u8, u8)>) -> String {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return String::new();
    }
    let parsed = parse_preview_timestamp(trimmed);
    let Some(timestamp) = parsed else {
        return String::new();
    };
    let date_key = (timestamp.year(), timestamp.month() as u8, timestamp.day());
    let time_only = timestamp
        .format(time::macros::format_description!(
            "[hour repr:12]:[minute][period case:upper]"
        ))
        .unwrap_or_else(|_| trimmed.to_string());
    let full = timestamp
        .format(time::macros::format_description!(
            "[month repr:short] [day], [year] [hour repr:12]:[minute][period case:upper] UTC[offset_hour sign:mandatory][offset_minute]"
        ))
        .unwrap_or_else(|_| trimmed.to_string());
    if last_date_key.as_ref() == Some(&date_key) {
        return time_only;
    }
    *last_date_key = Some(date_key);
    full
}
fn parse_preview_timestamp(raw: &str) -> Option<OffsetDateTime> {
    let iso = time::format_description::well_known::Rfc3339;
    OffsetDateTime::parse(raw, &iso)
        .ok()
        .or_else(|| {
            OffsetDateTime::parse(
                raw,
                &time::macros::format_description!(
                    "[month repr:short] [day], [year] [hour repr:12]:[minute] [period case:upper] UTC[offset_hour sign:mandatory][offset_minute]"
                ),
            )
            .ok()
        })
        .or_else(|| {
            OffsetDateTime::parse(
                raw,
                &time::macros::format_description!(
                    "[month repr:short] [day], [year] [hour repr:12]:[minute][period case:upper] UTC[offset_hour sign:mandatory][offset_minute]"
                ),
            )
            .ok()
        })
}
/// Borrows, never clones: every caller either reads a routing field or looks
/// the session back up in `machine.sessions`, and a clone here copied the
/// whole scanned machine (1.75 MB on the live host) once per call — including
/// once per live session inside the copy scan's read block.
fn remote_machine_for_session_path<'a>(
    server: &'a YggtermServer,
    session_path: &str,
) -> Option<&'a RemoteMachineSnapshot> {
    server.remote_machines().iter().find(|machine| {
        machine
            .sessions
            .iter()
            .any(|session| session.session_path == session_path)
    })
}
fn spawn_active_session_copy_hydration(mut state: Signal<ShellState>, session: ManagedSessionView) {
    let session_path = session.session_path.clone();
    let session_id = session.id.clone();
    let already_in_flight = state.with_mut_counted(|shell| {
        if shell
            .active_copy_hydration_in_flight
            .contains(&session_path)
            || shell.store_copy_hydrated_session_ids.contains(&session_id)
        {
            true
        } else {
            shell
                .active_copy_hydration_in_flight
                .insert(session_path.clone());
            false
        }
    });
    if already_in_flight {
        return;
    }
    let remote_cached = remote_generated_copy(&state.read().server, &session_path);
    let needs_local_lookup = is_local_stored_session_row(&BrowserRow {
        kind: BrowserRowKind::Session,
        full_path: session_path.clone(),
        label: session.title.clone(),
        detail_label: String::new(),
        document_kind: None,
        group_kind: None,
        session_title: Some(session.title.clone()),
        depth: 0,
        host_label: session.host_label.clone(),
        descendant_sessions: 0,
        expanded: false,
        session_id: Some(session.id.clone()),
        session_cwd: Some(metadata_value(&session, "Cwd")),
        session_kind: None,
    });
    spawn(async move {
        let path_for_task = session_path.clone();
        let outcome = task::spawn_blocking(
            move || -> Result<(Option<String>, Option<String>, Option<String>)> {
                let store = SessionStore::open_or_init()?;
                if let Some((title, precis, summary)) = remote_cached {
                    let store_title = store.resolve_title_for_session_id(&session.id)?;
                    let store_precis = store.resolve_precis_for_session_id(&session.id)?;
                    let store_summary = store.resolve_summary_for_session_id(&session.id)?;
                    let resolved_title = if title.trim().is_empty() {
                        store_title
                    } else {
                        store_title.or(Some(title))
                    };
                    let resolved_precis = if precis
                        .as_ref()
                        .is_some_and(|value| !value.trim().is_empty())
                    {
                        store_precis.or(precis)
                    } else {
                        store_precis
                    };
                    let resolved_summary = if summary
                        .as_ref()
                        .is_some_and(|value| !value.trim().is_empty())
                    {
                        store_summary.or(summary)
                    } else {
                        store_summary
                    };
                    return Ok((resolved_title, resolved_precis, resolved_summary));
                }
                let (title, precis, summary) = if !needs_local_lookup {
                    (
                        store.resolve_title_for_session_id(&session.id)?,
                        store.resolve_precis_for_session_id(&session.id)?,
                        store.resolve_summary_for_session_id(&session.id)?,
                    )
                } else {
                    (
                        store.resolve_title_for_session_path(&path_for_task)?,
                        store.resolve_precis_for_session_path(&path_for_task)?,
                        store.resolve_summary_for_session_path(&path_for_task)?,
                    )
                };
                Ok((title, precis, summary))
            },
        )
        .await;
        let persist_request = state.with_mut_counted(|shell| {
            shell.active_copy_hydration_in_flight.remove(&session_path);
            shell
                .store_copy_hydrated_session_ids
                .insert(session_id.clone());
            let Ok(Ok((title, precis, summary))) = outcome else {
                return None;
            };
            let should_persist_live_hint = shell
                .server
                .live_sessions()
                .iter()
                .any(|session| session.session_path == session_path);
            let persisted_title = title.clone();
            let persisted_precis = precis.clone();
            let persisted_summary = summary.clone();
            if let Some(title) = title {
                remember_session_title_override(shell, &session_path, &title);
                shell.server.set_session_title_hint(&session_path, &title);
            }
            if let Some(precis) = precis {
                shell.generated_precis.insert(session_path.clone(), precis);
                if let Some(precis) = shell.generated_precis.get(&session_path).cloned() {
                    shell.server.set_session_precis_hint(&session_path, &precis);
                }
            }
            if let Some(summary) = summary {
                shell
                    .generated_summaries
                    .insert(session_path.clone(), summary);
                if let Some(summary) = shell.generated_summaries.get(&session_path).cloned() {
                    shell
                        .server
                        .set_session_summary_hint(&session_path, &summary);
                }
            }
            if should_persist_live_hint {
                Some((
                    shell.bootstrap.server_endpoint.clone(),
                    session_path.clone(),
                    persisted_title,
                    persisted_precis,
                    persisted_summary,
                ))
            } else {
                None
            }
        });
        if let Some((endpoint, session_path, title, precis, summary)) = persist_request {
            spawn_persist_session_copy_hints(
                state,
                endpoint,
                session_path,
                title,
                precis,
                summary,
                false,
                "Session copy",
                false,
            );
        }
        let active = safe_shell_read(state, "copy_hydration_recheck_active", |shell| {
            shell
                .server
                .active_session()
                .cloned()
                .filter(|active| active.session_path == session_path)
        })
        .flatten();
        if let Some(active) = active {
            maybe_request_copy_generation_for_session(state, active);
        }
    });
}
fn preview_context_from_session(session: &ManagedSessionView) -> Option<String> {
    let lines = session
        .preview
        .blocks
        .iter()
        .rev()
        .take(6)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .flat_map(|block| {
            let role = block.role.trim().to_string();
            block.lines.iter().filter_map(move |line| {
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    return None;
                }
                let composed = if role.is_empty() {
                    trimmed.to_string()
                } else {
                    format!("{role}: {trimmed}")
                };
                (!memoized_low_signal_generated_copy(&composed)).then_some(composed)
            })
        })
        .collect::<Vec<_>>();
    if !lines.is_empty() {
        return Some(lines.join(
            "
",
        ));
    }
    let terminal_lines = session
        .terminal_lines
        .iter()
        .rev()
        .filter_map(|line| {
            let trimmed = line.trim();
            if trimmed.is_empty() || memoized_low_signal_generated_copy(trimmed) {
                None
            } else {
                Some(trimmed.to_string())
            }
        })
        .take(12)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect::<Vec<_>>();
    (!terminal_lines.is_empty()).then(|| {
        terminal_lines.join(
            "
",
        )
    })
}
fn parse_remote_scanned_session_path(path: &str) -> Option<(&str, &str)> {
    yggterm_core::agent_scheme::remote_agent_row_schemes().find_map(|scheme| {
        let rest = path.strip_prefix(scheme.prefix)?;
        let (machine_key, session_id) = rest.split_once('/')?;
        Some((machine_key, session_id))
    })
}
fn stage_local_clipboard_png(home: &PathBuf, png_bytes: &[u8]) -> Result<String> {
    let clipboard_dir = home.join("clipboard");
    fs::create_dir_all(&clipboard_dir)?;
    let filename = format!("clipboard-{}.png", current_millis());
    let path = clipboard_dir.join(filename);
    fs::write(&path, png_bytes)?;
    Ok(path.to_string_lossy().to_string())
}
fn create_native_clipboard() -> Result<NativeClipboard> {
    NativeClipboard::new()
        .map_err(|error| anyhow!("failed to initialize native clipboard access: {error}"))
}

/// Decode a PNG to 8-bit RGBA.
///
/// The messages name the PNG, NOT a caller: this decoder serves the clipboard
/// AND `capture-element --split`, whose `split_error` surfaced them verbatim, so
/// an agent whose element rasterizer failed was told its clipboard was broken.
/// Callers add their own context.
fn decode_png_rgba(png_bytes: &[u8]) -> Result<(Vec<u8>, usize, usize)> {
    let decoder = png::Decoder::new(Cursor::new(png_bytes));
    let mut reader = decoder
        .read_info()
        .map_err(|error| anyhow!("failed to decode PNG metadata: {error}"))?;
    let mut buffer = vec![
        0;
        reader
            .output_buffer_size()
            .context("reading PNG output buffer size")?
    ];
    let info = reader
        .next_frame(&mut buffer)
        .map_err(|error| anyhow!("failed to decode PNG pixels: {error}"))?;
    let width = info.width as usize;
    let height = info.height as usize;
    let pixels = &buffer[..info.buffer_size()];
    match (info.color_type, info.bit_depth) {
        (png::ColorType::Rgba, png::BitDepth::Eight) => Ok((pixels.to_vec(), width, height)),
        (png::ColorType::Rgb, png::BitDepth::Eight) => {
            let mut rgba = Vec::with_capacity(width * height * 4);
            for chunk in pixels.chunks_exact(3) {
                rgba.extend_from_slice(&[chunk[0], chunk[1], chunk[2], 255]);
            }
            Ok((rgba, width, height))
        }
        _ => Err(anyhow!("PNG must use 8-bit RGB or RGBA channels")),
    }
}

fn encode_rgba_png(width: usize, height: usize, rgba_bytes: &[u8]) -> Result<Vec<u8>> {
    if rgba_bytes.len() != width.saturating_mul(height).saturating_mul(4) {
        return Err(anyhow!(
            "clipboard image bytes did not match RGBA dimensions"
        ));
    }
    let mut png_bytes = Vec::new();
    let mut encoder = png::Encoder::new(&mut png_bytes, width as u32, height as u32);
    encoder.set_color(png::ColorType::Rgba);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder
        .write_header()
        .map_err(|error| anyhow!("failed to start clipboard PNG encoding: {error}"))?;
    writer
        .write_image_data(rgba_bytes)
        .map_err(|error| anyhow!("failed to encode clipboard PNG bytes: {error}"))?;
    drop(writer);
    Ok(png_bytes)
}

fn with_owned_native_clipboard<R>(
    mut state: Signal<ShellState>,
    kind: NativeClipboardOwnerKind,
    operation: impl FnOnce(&mut NativeClipboard) -> Result<R>,
) -> Result<R> {
    state.with_mut_counted(|shell| {
        if shell.native_clipboard_owner.is_none() {
            shell.native_clipboard_owner = Some(Rc::new(RefCell::new(NativeClipboardOwner {
                clipboard: create_native_clipboard()?,
                kind,
                updated_at_ms: current_millis(),
            })));
        }
        let owner = shell
            .native_clipboard_owner
            .as_mut()
            .expect("native clipboard owner initialized");
        let mut owner = owner.borrow_mut();
        let result = operation(&mut owner.clipboard)?;
        owner.kind = kind;
        owner.updated_at_ms = current_millis();
        Ok(result)
    })
}

fn terminal_clipboard_owner_sender()
-> Result<std::sync::mpsc::Sender<TerminalClipboardOwnerRequest>> {
    if let Some(sender) = TERMINAL_CLIPBOARD_OWNER_TX.get() {
        return Ok(sender.clone());
    }

    let (sender, receiver) = std::sync::mpsc::channel::<TerminalClipboardOwnerRequest>();
    thread::Builder::new()
        .name("yggterm-terminal-clipboard-owner".to_string())
        .spawn(move || terminal_clipboard_owner_loop(receiver))
        .map_err(|error| anyhow!("failed to spawn terminal clipboard owner: {error}"))?;
    let _ = TERMINAL_CLIPBOARD_OWNER_TX.set(sender.clone());
    TERMINAL_CLIPBOARD_OWNER_TX
        .get()
        .cloned()
        .ok_or_else(|| anyhow!("terminal clipboard owner was not initialized"))
}

fn terminal_clipboard_owner_loop(
    receiver: std::sync::mpsc::Receiver<TerminalClipboardOwnerRequest>,
) {
    let mut clipboard: Option<NativeClipboard> = None;
    for request in receiver {
        let result = (|| -> Result<()> {
            if clipboard.is_none() {
                clipboard = Some(create_native_clipboard()?);
            }
            let clipboard = clipboard
                .as_mut()
                .ok_or_else(|| anyhow!("native clipboard owner is unavailable"))?;
            #[cfg(target_os = "linux")]
            {
                let set = clipboard.set().clipboard(LinuxClipboardKind::Clipboard);
                let set = match request.sensitivity {
                    ClipboardSensitivity::Shareable => set,
                    ClipboardSensitivity::Secret => set.exclude_from_history(),
                };
                set.text(request.text.as_str()).map_err(|error| {
                    anyhow!("failed to seed terminal selection clipboard text: {error}")
                })?;
            }
            #[cfg(not(target_os = "linux"))]
            {
                clipboard.set_text(request.text.as_str()).map_err(|error| {
                    anyhow!("failed to seed terminal selection clipboard text: {error}")
                })?;
            }
            Ok(())
        })();

        let (event_name, error) = match result {
            Ok(()) => ("selection_copy_owner_updated", None),
            Err(error) => {
                clipboard = None;
                ("selection_copy_owner_error", Some(error.to_string()))
            }
        };
        append_trace_event(
            &request.trace_home,
            "ui",
            "terminal_clipboard",
            event_name,
            json!({
                "session_path": request.session_path,
                "action": request.action,
                "bytes": request.byte_count,
                "error": error,
            }),
        );
    }
}

/// How long two byte-identical writes from the same surface count as ONE act.
/// Long enough to absorb a double dispatch (measured at the same millisecond on
/// the live host), far short of any human re-copying the same text on purpose.
const TERMINAL_CLIPBOARD_WRITE_COALESCE_MS: u64 = 400;
/// The last write this door served, as a FINGERPRINT and a time — never the
/// text. A `Secret` copy (a vault TOTP code) must not be left sitting in a
/// static for the sake of a duplicate check.
static LAST_TERMINAL_CLIPBOARD_WRITE_FINGERPRINT: AtomicU64 = AtomicU64::new(0);
static LAST_TERMINAL_CLIPBOARD_WRITE_AT_MS: AtomicU64 = AtomicU64::new(0);

/// What a terminal clipboard write actually did. A caller that cannot tell
/// "served" from "already served" chimes twice for one copy, which is how the
/// double copy notification survived so long.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClipboardWriteOutcome {
    /// Queued to the owner thread; names the method for telemetry.
    Served(&'static str),
    /// A byte-identical write for the same surface and action inside the
    /// coalescing window — ONE user act that reached this door twice.
    Coalesced,
}

impl ClipboardWriteOutcome {
    fn served_method(self) -> Option<&'static str> {
        match self {
            Self::Served(method) => Some(method),
            Self::Coalesced => None,
        }
    }
}

/// Whether this write repeats the previous one closely enough to be the same
/// user act. Pure so the window can be tested without the process statics.
fn terminal_clipboard_write_is_repeat(
    previous: Option<(u64, u64)>,
    fingerprint: u64,
    now_ms: u64,
) -> bool {
    let Some((last_fingerprint, last_at_ms)) = previous else {
        return false;
    };
    last_fingerprint == fingerprint
        && now_ms >= last_at_ms
        && now_ms - last_at_ms < TERMINAL_CLIPBOARD_WRITE_COALESCE_MS
}

fn terminal_clipboard_write_fingerprint(session_path: &str, action: &str, text: &str) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    session_path.hash(&mut hasher);
    action.hash(&mut hasher);
    text.hash(&mut hasher);
    // A zero fingerprint would be indistinguishable from "nothing written yet".
    hasher.finish() | 1
}

fn copy_terminal_selection_to_clipboard(
    session_path: &str,
    action: &str,
    text: String,
    trace_home: PathBuf,
) -> Result<ClipboardWriteOutcome> {
    copy_terminal_text_to_clipboard(
        session_path,
        action,
        text,
        trace_home,
        ClipboardSensitivity::Shareable,
    )
}
fn copy_terminal_text_to_clipboard(
    session_path: &str,
    action: &str,
    text: String,
    trace_home: PathBuf,
    sensitivity: ClipboardSensitivity,
) -> Result<ClipboardWriteOutcome> {
    if text.is_empty() {
        return Err(anyhow!(
            "Select terminal text before using the clipboard shortcut."
        ));
    }
    let byte_count = text.len();
    if byte_count > TERMINAL_SELECTION_CLIPBOARD_MAX_BYTES {
        return Err(anyhow!(
            "Terminal selection is too large to copy safely ({} bytes).",
            byte_count
        ));
    }
    // ⛔ ONE COPY GESTURE, ONE WRITE. Measured on the live host: the viewport
    // Copy action reached this door TWICE at the same millisecond with identical
    // text, and each call set the selection again. On Wayland the clipboard is
    // served on demand by whoever owns the selection, so a second set_text
    // re-offers mid-handshake and the requester can be answered by the previous
    // owner instead — a copy that reports success and pastes as the OLD content.
    // Coalescing here rather than at the dispatcher is deliberate: the clipboard
    // is one resource with one owner, so the invariant belongs at its door and
    // holds for every caller (selection copy, OSC 52, cut) instead of once per
    // route. The duplicate is still traced — swallowing it silently would hide
    // the double dispatch that produced it.
    let fingerprint = terminal_clipboard_write_fingerprint(session_path, action, &text);
    let now_ms = current_millis();
    let previous = (
        LAST_TERMINAL_CLIPBOARD_WRITE_FINGERPRINT.load(Ordering::Relaxed),
        LAST_TERMINAL_CLIPBOARD_WRITE_AT_MS.load(Ordering::Relaxed),
    );
    let previous = (previous.0 != 0).then_some(previous);
    if terminal_clipboard_write_is_repeat(previous, fingerprint, now_ms) {
        LAST_TERMINAL_CLIPBOARD_WRITE_AT_MS.store(now_ms, Ordering::Relaxed);
        append_trace_event(
            &trace_home,
            "ui",
            "terminal_clipboard",
            "selection_copy_coalesced",
            json!({
                "session_path": session_path,
                "action": action,
                "bytes": byte_count,
                "since_previous_ms": now_ms.saturating_sub(previous.map(|(_, at)| at).unwrap_or(now_ms)),
            }),
        );
        return Ok(ClipboardWriteOutcome::Coalesced);
    }
    LAST_TERMINAL_CLIPBOARD_WRITE_FINGERPRINT.store(fingerprint, Ordering::Relaxed);
    LAST_TERMINAL_CLIPBOARD_WRITE_AT_MS.store(now_ms, Ordering::Relaxed);
    let sender = terminal_clipboard_owner_sender()?;
    sender
        .send(TerminalClipboardOwnerRequest {
            text,
            sensitivity,
            trace_home: trace_home.clone(),
            session_path: session_path.to_string(),
            action: action.to_string(),
            byte_count,
        })
        .map_err(|error| anyhow!("failed to queue terminal selection clipboard copy: {error}"))?;
    append_trace_event(
        &trace_home,
        "ui",
        "terminal_clipboard",
        "selection_copy_queued",
        json!({
            "session_path": session_path,
            "action": action,
            "bytes": byte_count,
            "method": "native_owner_thread",
        }),
    );
    Ok(ClipboardWriteOutcome::Served("native_owner_thread"))
}

/// Read the clipboard on a BLOCKING thread with a FRESH connection — never on
/// the GTK main thread, and never through the shared owner clipboard.
///
/// The paste path used to call arboard's synchronous `get()` directly in the
/// async paste task, which runs on the GTK main thread. When the X11 selection
/// owner is THIS process's own WebKit — a document surface (yedit) or web
/// surface the user just copied from — that `get()` DEADLOCKS the whole GUI:
/// the main thread blocks waiting for the selection contents, but WebKit needs
/// that same main thread to answer the `SelectionRequest`, so neither ever
/// completes and the window freezes hard (user had to kill it). Servicing the
/// read on a separate OS thread keeps the main loop free to answer the
/// request, so a same-process copy→paste completes. A fresh connection (not the
/// shared `native_clipboard_owner`, which is `!Send`) is what makes the read
/// movable to that thread.
fn read_native_clipboard_png_fresh() -> Result<Vec<u8>> {
    let mut clipboard = create_native_clipboard()?;
    #[cfg(target_os = "linux")]
    let image = clipboard
        .get()
        .clipboard(LinuxClipboardKind::Clipboard)
        .image()
        .map_err(|error| anyhow!("clipboard does not currently contain an image: {error}"))?;
    #[cfg(not(target_os = "linux"))]
    let image = clipboard
        .get_image()
        .map_err(|error| anyhow!("clipboard does not currently contain an image: {error}"))?;
    encode_rgba_png(image.width, image.height, image.bytes.as_ref())
}

fn read_native_clipboard_text_fresh() -> Result<String> {
    let mut clipboard = create_native_clipboard()?;
    #[cfg(target_os = "linux")]
    let text = clipboard
        .get()
        .clipboard(LinuxClipboardKind::Clipboard)
        .text()
        .map_err(|error| anyhow!("clipboard does not currently contain text: {error}"))?;
    #[cfg(not(target_os = "linux"))]
    let text = clipboard
        .get_text()
        .map_err(|error| anyhow!("clipboard does not currently contain text: {error}"))?;
    let text = text.trim_end_matches('\0').to_string();
    if text.is_empty() {
        return Err(anyhow!("clipboard does not currently contain text"));
    }
    Ok(text)
}

async fn read_native_clipboard_png_off_main() -> Result<Vec<u8>> {
    task::spawn_blocking(read_native_clipboard_png_fresh)
        .await
        .map_err(|error| anyhow!("clipboard image read task failed: {error}"))?
}

async fn read_native_clipboard_text_off_main() -> Result<String> {
    task::spawn_blocking(read_native_clipboard_text_fresh)
        .await
        .map_err(|error| anyhow!("clipboard text read task failed: {error}"))?
}

fn terminal_clipboard_png_fingerprint(png_bytes: &[u8]) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    png_bytes.hash(&mut hasher);
    hasher.finish()
}

fn prune_recent_terminal_image_pastes(
    recent: &mut HashMap<String, RecentTerminalImagePaste>,
    now_ms: u64,
) {
    recent.retain(|_, paste| now_ms.saturating_sub(paste.at_ms) <= TERMINAL_IMAGE_PASTE_DEDUPE_MS);
}

fn claim_terminal_image_paste(
    in_flight: &mut HashSet<String>,
    recent: &mut HashMap<String, RecentTerminalImagePaste>,
    session_path: &str,
    fingerprint: u64,
    now_ms: u64,
) -> TerminalImagePasteClaim {
    prune_recent_terminal_image_pastes(recent, now_ms);
    if in_flight.contains(session_path) {
        return TerminalImagePasteClaim::InFlight;
    }
    if let Some(previous) = recent.get(session_path)
        && previous.fingerprint == fingerprint
    {
        return TerminalImagePasteClaim::Duplicate {
            path: previous.path.clone(),
        };
    }
    in_flight.insert(session_path.to_string());
    TerminalImagePasteClaim::Claimed
}

fn finish_terminal_image_paste_claim(
    in_flight: &mut HashSet<String>,
    recent: &mut HashMap<String, RecentTerminalImagePaste>,
    session_path: &str,
    fingerprint: u64,
    at_ms: u64,
    path: Option<String>,
) {
    in_flight.remove(session_path);
    prune_recent_terminal_image_pastes(recent, at_ms);
    if let Some(path) = path {
        recent.insert(
            session_path.to_string(),
            RecentTerminalImagePaste {
                fingerprint,
                at_ms,
                path,
            },
        );
    }
}

/// Put something on the SYSTEM clipboard, so it can be pasted into any other
/// application.
///
/// ⛔ **Do not add `exclude_from_history()` here.** All four callers are
/// [`ClipboardSensitivity::Shareable`] — a copied message, a tab address twice,
/// and the agent verb — and every one of them used to carry that call. It is
/// why nothing yggterm copied could be pasted anywhere else.
///
/// On Linux it adds `x-kde-passwordManagerHint: secret`, which tells KDE's
/// Klipper not to record the entry, and arboard also releases clipboard
/// ownership for data it believes is sensitive — so the content is gone as soon
/// as the write returns. The write reports success either way, which is why
/// this survived: the app said "Message Copied", the notification appeared, and
/// the system clipboard still held whatever was there before.
///
/// Measured on guihost 2026-08-04: `server app clipboard text --value <probe>`
/// answered `{"kind":"text","error":null}` while Klipper still reported the
/// previous entry (`▨ 1920x1200`, an old screenshot).
///
/// A credential opts in at its own call site — see the TOTP path, which is the
/// only genuine one.
///
/// ⚠ Linux only. The `#[cfg(not(target_os = "linux"))]` arms never carried the
/// marker, so Windows and macOS were never affected, and the mobile targets do
/// not use this path.
fn set_native_clipboard_contents(
    state: Signal<ShellState>,
    contents: &YgguiClipboardContents,
) -> Result<&'static str> {
    match contents {
        YgguiClipboardContents::Text { text } => {
            with_owned_native_clipboard(state, NativeClipboardOwnerKind::Text, |clipboard| {
                #[cfg(target_os = "linux")]
                {
                    clipboard
                        .set()
                        .clipboard(LinuxClipboardKind::Clipboard)
                        .text(text.as_str())
                        .map_err(|error| {
                            anyhow!("failed to seed native clipboard text: {error}")
                        })?;
                }
                #[cfg(not(target_os = "linux"))]
                {
                    clipboard.set_text(text.as_str()).map_err(|error| {
                        anyhow!("failed to seed native clipboard text: {error}")
                    })?;
                }
                Ok(())
            })?;
            Ok("text")
        }
        YgguiClipboardContents::PngBase64 { png_base64 } => {
            let png_bytes = BASE64_STANDARD
                .decode(png_base64)
                .map_err(|error| anyhow!("invalid base64 clipboard PNG payload: {error}"))?;
            let (rgba_bytes, width, height) =
                decode_png_rgba(&png_bytes).context("decoding the clipboard PNG payload")?;
            with_owned_native_clipboard(
                state,
                NativeClipboardOwnerKind::Image,
                move |clipboard| {
                    let image = NativeClipboardImageData {
                        width,
                        height,
                        bytes: Cow::Owned(rgba_bytes),
                    };
                    #[cfg(target_os = "linux")]
                    {
                        clipboard
                            .set()
                            .clipboard(LinuxClipboardKind::Clipboard)
                            .image(image)
                            .map_err(|error| {
                                anyhow!("failed to seed native clipboard image: {error}")
                            })?;
                    }
                    #[cfg(not(target_os = "linux"))]
                    {
                        clipboard.set_image(image).map_err(|error| {
                            anyhow!("failed to seed native clipboard image: {error}")
                        })?;
                    }
                    Ok(())
                },
            )?;
            Ok("image")
        }
    }
}
fn stage_terminal_clipboard_image(
    state: Signal<ShellState>,
    session_path: &str,
    png_bytes: &[u8],
) -> Result<String> {
    let bootstrap = BOOTSTRAP.get().expect("shell bootstrap initialized");
    if session_path.starts_with("local://") {
        let home = bootstrap
            .settings_path
            .parent()
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("."));
        return stage_local_clipboard_png(&home, png_bytes);
    }
    if let Some(machine) = remote_machine_for_session_path(&state.read().server, session_path) {
        return stage_remote_clipboard_png(
            &machine.ssh_target,
            machine.prefix.as_deref(),
            png_bytes,
        );
    }
    if let Some(session) = state.read().server.active_session().cloned()
        && session.session_path == session_path
        && let Some(ssh_target) = session.ssh_target
    {
        return stage_remote_clipboard_png(&ssh_target, session.ssh_prefix.as_deref(), png_bytes);
    }
    let home = bootstrap
        .settings_path
        .parent()
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));
    stage_local_clipboard_png(&home, png_bytes)
}
async fn stage_and_paste_terminal_clipboard_image(
    mut state: Signal<ShellState>,
    session_path: &str,
) -> Result<TerminalImagePasteResult> {
    let (endpoint, runtime_session_path, trace_home) = state.with(|shell| {
        (
            shell.bootstrap.server_endpoint.clone(),
            terminal_runtime_session_path(shell, session_path),
            perf_home_dir(&shell.bootstrap.settings_path),
        )
    });
    let png_bytes = read_native_clipboard_png_off_main().await?;
    let fingerprint = terminal_clipboard_png_fingerprint(&png_bytes);
    let claim = state.with_mut_counted(|shell| {
        claim_terminal_image_paste(
            &mut shell.terminal_image_paste_in_flight,
            &mut shell.terminal_recent_image_pastes,
            session_path,
            fingerprint,
            current_millis(),
        )
    });
    match claim {
        TerminalImagePasteClaim::Claimed => {}
        TerminalImagePasteClaim::InFlight => {
            return Ok(TerminalImagePasteResult::Skipped {
                reason: "clipboard image paste already in flight",
                path: None,
            });
        }
        TerminalImagePasteClaim::Duplicate { path } => {
            return Ok(TerminalImagePasteResult::Skipped {
                reason: "duplicate clipboard image paste",
                path: Some(path),
            });
        }
    }
    let paste_result = match stage_terminal_clipboard_image(state, session_path, &png_bytes) {
        Ok(path) => {
            match terminal_write_with_local_runtime_retry_async(
                endpoint,
                runtime_session_path,
                format!("{path} "),
                trace_home.as_path(),
            )
            .await
            {
                Ok(()) => Ok(path),
                Err(error) => Err(error),
            }
        }
        Err(error) => Err(error),
    };
    let path_for_recent = paste_result.as_ref().ok().cloned();
    state.with_mut_counted(|shell| {
        finish_terminal_image_paste_claim(
            &mut shell.terminal_image_paste_in_flight,
            &mut shell.terminal_recent_image_pastes,
            session_path,
            fingerprint,
            current_millis(),
            path_for_recent,
        );
    });
    let path = paste_result?;
    Ok(TerminalImagePasteResult::Staged { path })
}
enum NativeClipboardPaste {
    Text {
        chars: usize,
        bytes: usize,
    },
    Image {
        path: String,
    },
    ImageSkipped {
        reason: &'static str,
        path: Option<String>,
    },
}

async fn paste_terminal_native_clipboard(
    mut state: Signal<ShellState>,
    session_path: &str,
) -> Result<NativeClipboardPaste> {
    let (endpoint, runtime_session_path, trace_home) = state.with(|shell| {
        (
            shell.bootstrap.server_endpoint.clone(),
            terminal_runtime_session_path(shell, session_path),
            perf_home_dir(&shell.bootstrap.settings_path),
        )
    });
    match read_native_clipboard_png_off_main().await {
        Ok(png_bytes) => {
            let fingerprint = terminal_clipboard_png_fingerprint(&png_bytes);
            let claim = state.with_mut_counted(|shell| {
                claim_terminal_image_paste(
                    &mut shell.terminal_image_paste_in_flight,
                    &mut shell.terminal_recent_image_pastes,
                    session_path,
                    fingerprint,
                    current_millis(),
                )
            });
            match claim {
                TerminalImagePasteClaim::Claimed => {}
                TerminalImagePasteClaim::InFlight => {
                    return Ok(NativeClipboardPaste::ImageSkipped {
                        reason: "clipboard image paste already in flight",
                        path: None,
                    });
                }
                TerminalImagePasteClaim::Duplicate { path } => {
                    return Ok(NativeClipboardPaste::ImageSkipped {
                        reason: "duplicate clipboard image paste",
                        path: Some(path),
                    });
                }
            }
            let paste_result = match stage_terminal_clipboard_image(state, session_path, &png_bytes)
            {
                Ok(path) => {
                    match terminal_write_with_local_runtime_retry_async(
                        endpoint,
                        runtime_session_path,
                        format!("{path} "),
                        trace_home.as_path(),
                    )
                    .await
                    {
                        Ok(()) => Ok(path),
                        Err(error) => Err(error),
                    }
                }
                Err(error) => Err(error),
            };
            let path_for_recent = paste_result.as_ref().ok().cloned();
            state.with_mut_counted(|shell| {
                finish_terminal_image_paste_claim(
                    &mut shell.terminal_image_paste_in_flight,
                    &mut shell.terminal_recent_image_pastes,
                    session_path,
                    fingerprint,
                    current_millis(),
                    path_for_recent,
                );
            });
            let path = paste_result?;
            Ok(NativeClipboardPaste::Image { path })
        }
        Err(_png_error) => {
            let text = read_native_clipboard_text_off_main().await?;
            let chars = text.chars().count();
            let bytes = text.len();
            terminal_write_with_local_runtime_retry_async(
                endpoint,
                runtime_session_path,
                text,
                trace_home.as_path(),
            )
            .await?;
            Ok(NativeClipboardPaste::Text { chars, bytes })
        }
    }
}

fn refocus_terminal_session_input(session_path: &str) {
    let _ = document::eval(&terminal_set_input_enabled_script_for_session(
        session_path,
        true,
        true,
    ));
}
fn arm_terminal_activation(shell: &mut ShellState, session_path: &str) {
    shell.dismiss_titlebar_transients();
    shell.terminal_input_override_active = true;
    shell.retain_terminal_session_path(session_path);
}
fn try_arm_terminal_activation_for_focus(
    state: Signal<ShellState>,
    session_path: &str,
    context: &'static str,
) -> bool {
    safe_shell_mut(state, context, |shell| {
        arm_terminal_activation(shell, session_path);
    })
    .is_ok()
}
fn schedule_terminal_focus_after_activation(state: Signal<ShellState>, session_path: String) {
    clear_sidebar_keyboard_owner();
    let _ = try_arm_terminal_activation_for_focus(
        state,
        &session_path,
        "terminal_focus_after_activation",
    );
    sync_active_terminal_input_policy(state);
    refocus_terminal_session_input(&session_path);
    let reclaim_script = terminal_reclaim_focus_script_for_session(&session_path);
    let _ = document::eval(&format!(
        r#"
        (() => {{
          const releaseSidebarFocus = () => {{
            try {{
              const active = document.activeElement;
              if (active && active.closest && active.closest('#yggterm-sidebar') && active.blur) {{
                active.blur();
              }}
              window.__yggtermSidebarFocusGeneration = Number(window.__yggtermSidebarFocusGeneration || 0) + 1;
              window.__yggtermSidebarKeyboardOwner = false;
              window.__yggtermFocusedSidebarRowPath = '';
              window.__yggtermUiFocusClaimUntilMs = 0;
            }} catch (_error) {{}}
          }};
          const reclaim = () => {{ {reclaim_script} }};
          releaseSidebarFocus();
          reclaim();
          window.requestAnimationFrame(() => {{ releaseSidebarFocus(); reclaim(); }});
          window.setTimeout(() => {{ releaseSidebarFocus(); reclaim(); }}, 0);
          window.setTimeout(() => {{ releaseSidebarFocus(); reclaim(); }}, 32);
          window.setTimeout(() => {{ releaseSidebarFocus(); reclaim(); }}, 96);
          window.setTimeout(() => {{ releaseSidebarFocus(); reclaim(); }}, 220);
          window.setTimeout(() => {{ releaseSidebarFocus(); reclaim(); }}, 420);
          window.setTimeout(() => {{ releaseSidebarFocus(); reclaim(); }}, 760);
          window.setTimeout(() => {{ releaseSidebarFocus(); reclaim(); }}, 1200);
        }})();
        "#
    ));
}
/// The merged sidebar with every row set drawn OPEN.
///
/// The shape questions this answers — is a row present, where does it sit, what
/// is it called — are all independent of whether a set is shut, so the callers
/// that ask them (drag targeting, reorder planning, restore telemetry) need no
/// collapse state and do not carry one. Only the rendered snapshot does, and it
/// calls [`merged_sidebar_rows_traced`] with the user's own set.
fn merged_sidebar_rows(
    stored_rows: &[BrowserRow],
    remote_machines: &[RemoteMachineSnapshot],
    ssh_targets: &[SshConnectTarget],
    live_sessions: &[ManagedSessionView],
    expanded_paths: &HashSet<String>,
) -> Vec<BrowserRow> {
    merged_sidebar_rows_with_projection_rows(
        stored_rows,
        stored_rows,
        remote_machines,
        ssh_targets,
        live_sessions,
        expanded_paths,
        &HashSet::new(),
        &yggterm_core::row_set_outline::RowArrangement::default(),
    )
}
fn merged_sidebar_rows_with_projection_rows(
    stored_rows: &[BrowserRow],
    stored_projection_rows: &[BrowserRow],
    remote_machines: &[RemoteMachineSnapshot],
    ssh_targets: &[SshConnectTarget],
    live_sessions: &[ManagedSessionView],
    expanded_paths: &HashSet<String>,
    collapsed_row_set_heads: &HashSet<String>,
    row_arrangement: &yggterm_core::row_set_outline::RowArrangement,
) -> Vec<BrowserRow> {
    let remote_session_count = remote_machines
        .iter()
        .map(|machine| machine.sessions.len())
        .sum::<usize>();
    let total_started_at = Instant::now();
    let key_started_at = Instant::now();
    let key = sidebar_merge_cache_key(
        stored_rows,
        stored_projection_rows,
        remote_machines,
        ssh_targets,
        live_sessions,
        expanded_paths,
        collapsed_row_set_heads,
        row_arrangement,
    );
    let key_ms = key_started_at.elapsed().as_secs_f64() * 1000.0;
    let cache_lookup_started_at = Instant::now();
    if let Ok(mut cache) = sidebar_merge_cache().lock() {
        if let Some(hit) = cache.entries.get(&key).cloned() {
            if let Some(ix) = cache.order.iter().position(|existing| *existing == key) {
                cache.order.remove(ix);
            }
            cache.order.push_back(key);
            maybe_record_sidebar_merge_breakdown(
                remote_session_count,
                json!({
                    "cache_hit": true,
                    "key_ms": key_ms,
                    "cache_lookup_ms": cache_lookup_started_at.elapsed().as_secs_f64() * 1000.0,
                    "uncached_ms": 0.0,
                    "total_ms": total_started_at.elapsed().as_secs_f64() * 1000.0,
                    "stored_row_count": stored_rows.len(),
                    "merged_row_count": hit.len(),
                    "expanded_path_count": expanded_paths.len(),
                    "live_session_count": live_sessions.len(),
                    "ssh_target_count": ssh_targets.len(),
                }),
            );
            return hit;
        }
    }
    let cache_lookup_ms = cache_lookup_started_at.elapsed().as_secs_f64() * 1000.0;
    let uncached_started_at = Instant::now();
    let rows = merged_sidebar_rows_uncached(
        stored_rows,
        stored_projection_rows,
        remote_machines,
        ssh_targets,
        live_sessions,
        expanded_paths,
        collapsed_row_set_heads,
        row_arrangement,
    );
    let uncached_ms = uncached_started_at.elapsed().as_secs_f64() * 1000.0;
    if let Ok(mut cache) = sidebar_merge_cache().lock() {
        cache.entries.insert(key, rows.clone());
        if let Some(ix) = cache.order.iter().position(|existing| *existing == key) {
            cache.order.remove(ix);
        }
        cache.order.push_back(key);
        while cache.order.len() > SIDEBAR_MERGE_CACHE_LIMIT {
            if let Some(oldest) = cache.order.pop_front() {
                cache.entries.remove(&oldest);
            }
        }
    }
    maybe_record_sidebar_merge_breakdown(
        remote_session_count,
        json!({
            "cache_hit": false,
            "key_ms": key_ms,
            "cache_lookup_ms": cache_lookup_ms,
            "uncached_ms": uncached_ms,
            "total_ms": total_started_at.elapsed().as_secs_f64() * 1000.0,
            "stored_row_count": stored_rows.len(),
            "merged_row_count": rows.len(),
            "expanded_path_count": expanded_paths.len(),
            "live_session_count": live_sessions.len(),
            "ssh_target_count": ssh_targets.len(),
        }),
    );
    rows
}
/// ⛔⛔ A RECORDER THAT FIRES ON MACHINE SIZE RATHER THAN ON ANOMALY BILLS THE
/// RENDER THREAD, AND IT BILLS IT WORST EXACTLY WHEN THE APP IS ALREADY IN
/// TROUBLE (measured 2026-08-14).
///
/// `remote_session_count >= 500` is a fact about how many sessions the fleet has,
/// not about anything being wrong, so on the live host (640 remote sessions) it
/// was permanently true and every merge wrote to disk. The merge runs inside
/// [`ShellState::snapshot`], which runs in the render body — so during an
/// `app_render_storm` at ~60 renders/s the GUI's render thread performed **~142
/// synchronous JSONL appends per second** (this event plus `merge_rows`), each
/// one a `create_dir_all` + metadata stat + open + write. The instrument for the
/// storm was charging its own cost to the storm.
///
/// ⇒ The size condition now COALESCES instead of emitting: slow merges (the
/// actual signal, `>= 4 ms`) still emit immediately and unchanged, and the rest
/// are folded into one event per second that carries `sampled_count`. **No rate
/// information is lost** — a reader who wants renders-per-second sums
/// `sampled_count` instead of counting lines — which is the difference between
/// coalescing and sampling, and the reason this is not a downgrade of the data.
/// What to do with one sidebar-merge measurement. ONE owner for the decision,
/// read by both the `merge_rows` and the `merge_rows_breakdown` recorders — they
/// used to carry the same condition written two different ways
/// (`>= 4.0 || >= 500` against `< 500 && < 4.0`), which is two encodings of one
/// rule and therefore two things that can drift apart.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SidebarMergeRecordPolicy {
    /// Write the event now: this merge is SLOW, which is the anomaly the event
    /// exists to catch, and it is rare enough to cost nothing.
    Immediate,
    /// Fold into the once-a-second aggregate: an ordinary merge on a big fleet.
    Coalesce,
    /// Say nothing: an ordinary merge on an ordinary machine.
    Drop,
}

/// A merge at or above this is an outlier worth a line of its own.
const SIDEBAR_MERGE_SLOW_MS: f64 = 4.0;
/// Above this many remote sessions the ordinary merges are worth counting — but
/// only counting. Emitting one line each is what billed the render thread.
const SIDEBAR_MERGE_LARGE_FLEET_SESSIONS: usize = 500;

fn sidebar_merge_record_policy(
    duration_ms: f64,
    remote_session_count: usize,
) -> SidebarMergeRecordPolicy {
    if duration_ms >= SIDEBAR_MERGE_SLOW_MS {
        SidebarMergeRecordPolicy::Immediate
    } else if remote_session_count >= SIDEBAR_MERGE_LARGE_FLEET_SESSIONS {
        SidebarMergeRecordPolicy::Coalesce
    } else {
        SidebarMergeRecordPolicy::Drop
    }
}

fn maybe_record_sidebar_merge_breakdown(remote_session_count: usize, payload: Value) {
    let total_ms = payload
        .get("total_ms")
        .and_then(Value::as_f64)
        .unwrap_or_default();
    match sidebar_merge_record_policy(total_ms, remote_session_count) {
        SidebarMergeRecordPolicy::Drop => return,
        SidebarMergeRecordPolicy::Coalesce => {
            SIDEBAR_MERGE_BREAKDOWN_COALESCED.fetch_add(1, Ordering::Relaxed);
            return;
        }
        SidebarMergeRecordPolicy::Immediate => {}
    }
    let Ok(home) = resolve_yggterm_home() else {
        return;
    };
    append_perf_event(&home, "sidebar", "merge_rows_breakdown", payload);
}

/// Merges folded away by [`maybe_record_sidebar_merge_breakdown`] since the last
/// flush. Reported as `sampled_breakdown_count` on the coalesced `merge_rows`
/// event so the count survives even though the lines do not.
static SIDEBAR_MERGE_BREAKDOWN_COALESCED: AtomicU64 = AtomicU64::new(0);
/// Merges folded away by [`merged_sidebar_rows_traced`], with the wall time they
/// spent and the worst single one, flushed at most once a second.
static SIDEBAR_MERGE_COALESCED: AtomicU64 = AtomicU64::new(0);
static SIDEBAR_MERGE_COALESCED_US: AtomicU64 = AtomicU64::new(0);
static SIDEBAR_MERGE_COALESCED_MAX_US: AtomicU64 = AtomicU64::new(0);
static SIDEBAR_MERGE_COALESCED_FLUSH_MS: AtomicU64 = AtomicU64::new(0);
const SIDEBAR_MERGE_COALESCE_FLUSH_MS: u64 = 1_000;
fn merged_sidebar_rows_traced(
    settings_path: &Path,
    source: &str,
    stored_rows: &[BrowserRow],
    stored_projection_rows: &[BrowserRow],
    remote_machines: &[RemoteMachineSnapshot],
    ssh_targets: &[SshConnectTarget],
    live_sessions: &[ManagedSessionView],
    expanded_paths: &HashSet<String>,
    collapsed_row_set_heads: &HashSet<String>,
    row_arrangement: &yggterm_core::row_set_outline::RowArrangement,
) -> Vec<BrowserRow> {
    let remote_session_count = remote_machines
        .iter()
        .map(|machine| machine.sessions.len())
        .sum::<usize>();
    let should_trace = remote_session_count >= 200
        || live_sessions.len() >= 20
        || stored_rows.len() >= 200
        || stored_projection_rows.len() >= 200
        || expanded_paths.len() >= 100;
    if !should_trace {
        return merged_sidebar_rows_with_projection_rows(
            stored_rows,
            stored_projection_rows,
            remote_machines,
            ssh_targets,
            live_sessions,
            expanded_paths,
            collapsed_row_set_heads,
            row_arrangement,
        );
    }
    let perf_home = perf_home_dir(settings_path);
    let started_at = Instant::now();
    let rows = merged_sidebar_rows_with_projection_rows(
        stored_rows,
        stored_projection_rows,
        remote_machines,
        ssh_targets,
        live_sessions,
        expanded_paths,
        collapsed_row_set_heads,
        row_arrangement,
    );
    let duration_ms = started_at.elapsed().as_secs_f64() * 1000.0;
    let meta = || {
        json!({
            "source": source,
            "stored_row_count": stored_rows.len(),
            "stored_projection_row_count": stored_projection_rows.len(),
            "remote_machine_count": remote_machines.len(),
            "remote_session_count": remote_session_count,
            "ssh_target_count": ssh_targets.len(),
            "live_session_count": live_sessions.len(),
            "expanded_path_count": expanded_paths.len(),
            "merged_row_count": rows.len(),
        })
    };
    match sidebar_merge_record_policy(duration_ms, remote_session_count) {
        SidebarMergeRecordPolicy::Drop => {}
        SidebarMergeRecordPolicy::Immediate => {
            // The outlier path, unchanged: a slow merge is the thing this event
            // was added to catch, and it is rare enough to cost nothing.
            append_perf_event(
                &perf_home,
                "sidebar",
                "merge_rows",
                json!({ "duration_ms": duration_ms, "meta": meta() }),
            );
        }
        SidebarMergeRecordPolicy::Coalesce => {
            // See `maybe_record_sidebar_merge_breakdown` for why writing one line
            // per merge here is a defect rather than thoroughness.
            let micros = (duration_ms * 1000.0).round().max(0.0) as u64;
            SIDEBAR_MERGE_COALESCED.fetch_add(1, Ordering::Relaxed);
            SIDEBAR_MERGE_COALESCED_US.fetch_add(micros, Ordering::Relaxed);
            SIDEBAR_MERGE_COALESCED_MAX_US.fetch_max(micros, Ordering::Relaxed);
            let now_ms = current_millis() as u64;
            let last = SIDEBAR_MERGE_COALESCED_FLUSH_MS.load(Ordering::Relaxed);
            // First call seeds the clock rather than flushing a window of one,
            // so the first reported window is a real second and not a startup
            // artefact.
            if last == 0 {
                SIDEBAR_MERGE_COALESCED_FLUSH_MS.store(now_ms, Ordering::Relaxed);
            } else if now_ms.saturating_sub(last) >= SIDEBAR_MERGE_COALESCE_FLUSH_MS
                && SIDEBAR_MERGE_COALESCED_FLUSH_MS
                    .compare_exchange(last, now_ms, Ordering::Relaxed, Ordering::Relaxed)
                    .is_ok()
            {
                let count = SIDEBAR_MERGE_COALESCED.swap(0, Ordering::Relaxed);
                let total_us = SIDEBAR_MERGE_COALESCED_US.swap(0, Ordering::Relaxed);
                let max_us = SIDEBAR_MERGE_COALESCED_MAX_US.swap(0, Ordering::Relaxed);
                let breakdowns = SIDEBAR_MERGE_BREAKDOWN_COALESCED.swap(0, Ordering::Relaxed);
                append_perf_event(
                    &perf_home,
                    "sidebar",
                    "merge_rows",
                    json!({
                        // Kept as the window's total so a reader summing
                        // `duration_ms` across the file still gets the true CPU
                        // cost.
                        "duration_ms": total_us as f64 / 1000.0,
                        "sampled_count": count,
                        "sampled_window_ms": now_ms.saturating_sub(last),
                        "sampled_max_ms": max_us as f64 / 1000.0,
                        "sampled_breakdown_count": breakdowns,
                        "meta": meta(),
                    }),
                );
            }
        }
    }
    rows
}
fn sidebar_rows_for_selection(
    stored_rows: &[BrowserRow],
    mut visible_rows: Vec<BrowserRow>,
) -> Vec<BrowserRow> {
    let mut seen_paths = visible_rows
        .iter()
        .map(|row| row.full_path.clone())
        .collect::<HashSet<_>>();
    for row in stored_rows {
        if row.kind == BrowserRowKind::Session && seen_paths.insert(row.full_path.clone()) {
            visible_rows.push(row.clone());
        }
    }
    visible_rows
}
/// Build the merged sidebar row list from stored rows + live sessions + remote
/// machines + SSH targets. This is the single function that owns sidebar shape.
///
/// **Contracts (see [`AGENTS.md`](../../../AGENTS.md) "Session display"):**
/// - Active sessions appear in BOTH "Live Sessions" group AND their cwd folder
///   group (dual presence). Never silently filter a live session out of the
///   cwd tree just because it also appears in Live Sessions.
/// - Local Codex/CC live sessions are injected into the cwd tree by
///   `inject_local_live_session_rows`.
/// - Remote live sessions stay in `machine.scanned_sessions`; no
///   live-vs-scanned dedup at this layer.
/// - Same-session dedup within a single tree view has ONE owner: the
///   `promoted_storage_paths` filter in the extend step, keyed by storage path.
///   ⛔ `inject_cc_sessions_into_stored_rows` used to dedup by `session_id` as
///   well; that was a cross-view rule wearing a per-view costume, and the two
///   cancelled — see the block comment inside it.
fn merged_sidebar_rows_uncached(
    stored_rows: &[BrowserRow],
    stored_projection_rows: &[BrowserRow],
    remote_machines: &[RemoteMachineSnapshot],
    ssh_targets: &[SshConnectTarget],
    live_sessions: &[ManagedSessionView],
    expanded_paths: &HashSet<String>,
    collapsed_row_set_heads: &HashSet<String>,
    row_arrangement: &yggterm_core::row_set_outline::RowArrangement,
) -> Vec<BrowserRow> {
    let stored_rows = filter_stored_rows_for_expansion(stored_rows, expanded_paths);
    let stored_projection_rows = filter_remote_workspace_projection_rows(stored_projection_rows);
    let remote_session_count = remote_machines
        .iter()
        .map(|machine| machine.sessions.len())
        .sum::<usize>();
    let breakdown_enabled = remote_session_count >= 500;
    let total_started_at = Instant::now();
    let remote_session_index = build_remote_session_index(remote_machines);
    let remote_index_ms = total_started_at.elapsed().as_secs_f64() * 1000.0;
    let promoted_live_sessions = live_sessions
        .iter()
        .filter(|session| is_promoted_live_session(session))
        .collect::<Vec<_>>();
    let has_remote_workspace_folders = stored_projection_rows
        .iter()
        .any(|row| remote_workspace_folder_from_row(row).is_some());
    if ssh_targets.is_empty()
        && remote_machines.is_empty()
        && promoted_live_sessions.is_empty()
        && !has_remote_workspace_folders
    {
        if stored_rows.is_empty() {
            return vec![BrowserRow {
                kind: BrowserRowKind::Group,
                full_path: "local".to_string(),
                label: "local".to_string(),
                detail_label: String::new(),
                document_kind: None,
                group_kind: Some(WorkspaceGroupKind::Folder),
                session_title: None,
                depth: 0,
                host_label: "local".to_string(),
                descendant_sessions: 0,
                expanded: true,
                session_id: None,
                session_cwd: None,
                session_kind: None,
            }];
        }
        return stored_rows;
    }
    let mut rows = Vec::with_capacity(stored_rows.len() + remote_machines.len() * 6 + 8);
    let machine_rows_init_started_at = Instant::now();
    let mut machine_rows = BTreeMap::<String, SidebarRemoteMachine>::new();
    for target in ssh_targets {
        let machine_key = machine_key_from_labelish(&target.ssh_target);
        machine_rows
            .entry(machine_key.clone())
            .or_insert_with(|| SidebarRemoteMachine {
                key: machine_key.clone(),
                label: ssh_target_machine_label(target),
                health: MachineHealth::Cached,
                remote_deploy_state: RemoteDeployState::Planned,
                scanned_sessions: Vec::new(),
                workspace_folders: Vec::new(),
                needs_resort: false,
            });
    }
    for machine in remote_machines {
        let mut scanned_sessions = machine.sessions.clone();
        sort_remote_scanned_sessions_by_recency(&mut scanned_sessions);
        machine_rows.insert(
            machine.machine_key.clone(),
            SidebarRemoteMachine {
                key: machine.machine_key.clone(),
                label: machine.label.clone(),
                health: match machine.health {
                    RemoteMachineHealth::Healthy => MachineHealth::Healthy,
                    RemoteMachineHealth::Cached => MachineHealth::Cached,
                    RemoteMachineHealth::Offline => MachineHealth::Offline,
                },
                remote_deploy_state: machine.remote_deploy_state,
                scanned_sessions,
                workspace_folders: Vec::new(),
                needs_resort: false,
            },
        );
    }
    for row in stored_projection_rows.iter() {
        let Some((machine_key, folder)) = remote_workspace_folder_from_row(row) else {
            continue;
        };
        let machine =
            machine_rows
                .entry(machine_key.clone())
                .or_insert_with(|| SidebarRemoteMachine {
                    key: machine_key.clone(),
                    label: machine_key.clone(),
                    health: MachineHealth::Cached,
                    remote_deploy_state: RemoteDeployState::Planned,
                    scanned_sessions: Vec::new(),
                    workspace_folders: Vec::new(),
                    needs_resort: false,
                });
        if !machine
            .workspace_folders
            .iter()
            .any(|existing| existing.cwd == folder.cwd)
        {
            machine.workspace_folders.push(folder);
        }
    }
    let machine_rows_init_ms = machine_rows_init_started_at.elapsed().as_secs_f64() * 1000.0;
    let merge_live_started_at = Instant::now();
    merge_remote_live_sessions(&mut machine_rows, ssh_targets, live_sessions);
    let merge_live_ms = merge_live_started_at.elapsed().as_secs_f64() * 1000.0;
    let promoted_retain_started_at = Instant::now();
    // Durable remote live sessions can project into their cwd folder. Plain SSH
    // terminals remain Live Sessions only; cwd is launch provenance, not saved
    // workspace identity.
    let promoted_retain_ms = promoted_retain_started_at.elapsed().as_secs_f64() * 1000.0;
    let resort_started_at = Instant::now();
    for machine in machine_rows.values_mut() {
        if machine.needs_resort {
            sort_remote_scanned_sessions_by_recency(&mut machine.scanned_sessions);
        }
    }
    let resort_ms = resort_started_at.elapsed().as_secs_f64() * 1000.0;
    // Per [[spec-active-sessions-dual-presence]]: active sessions appear in BOTH
    // "Live Sessions" AND their cwd folder group. SSOT is the session object;
    // display surfaces are dual.
    //
    // Local Codex/CC live sessions get injected under their cwd folder via
    // inject_local_live_session_rows — UNCONDITIONALLY, whether or not the
    // session also has a scanned transcript leaf in this tree. The scanned leaf
    // is what yields the slot, below, at `promoted_storage_paths`.
    let local_tree_live_sessions = promoted_live_sessions
        .iter()
        .copied()
        .filter(|session| is_local_tree_live_session(session))
        .collect::<Vec<_>>();
    let local_tree_started_at = Instant::now();
    let stored_rows = inject_local_live_session_rows(
        &stored_rows,
        &local_tree_live_sessions,
        &remote_session_index,
    );
    let local_tree_ms = local_tree_started_at.elapsed().as_secs_f64() * 1000.0;
    let push_live_started_at = Instant::now();
    // All promoted live sessions — including local Codex/CC and remote
    // sessions — appear in Live Sessions. Remote sessions ALSO remain in
    // their machine group below (no retain dedup) per the dual-presence spec.
    let display_promoted_sessions = promoted_live_sessions.iter().copied().collect::<Vec<_>>();
    push_live_session_rows(
        &mut rows,
        &display_promoted_sessions,
        &remote_session_index,
        expanded_paths,
        collapsed_row_set_heads,
        row_arrangement,
    );
    let push_live_ms = push_live_started_at.elapsed().as_secs_f64() * 1000.0;
    let push_remote_started_at = Instant::now();
    for machine in machine_rows.into_values() {
        // Do NOT remove live sessions from machine.scanned_sessions — they
        // belong in both "Live Sessions" AND their machine group per
        // [[spec-active-sessions-dual-presence]].
        push_remote_machine_rows(&mut rows, &machine, expanded_paths);
    }
    let push_remote_ms = push_remote_started_at.elapsed().as_secs_f64() * 1000.0;
    let extend_stored_started_at = Instant::now();
    // Per [[spec-active-sessions-dual-presence]]: live sessions appear in BOTH
    // "Live Sessions" group AND their cwd folder group. So we do NOT filter
    // stored rows by `promoted_live_paths`; that would yank the cwd-tree
    // injection of a live local session (added by
    // inject_local_live_session_rows above) right back out.
    //
    // We DO still filter by `promoted_storage_paths`: when a live session has
    // a "Storage" metadata pointing at a JSONL file, the file-backed stored
    // row would be a SECOND representation of the same logical session in the
    // SAME (cwd-tree) view — which is the duplicate kind that's wrong. The
    // injected live row covers that slot.
    let promoted_storage_paths = display_promoted_sessions
        .iter()
        .filter_map(|session| {
            let storage = metadata_value(session, "Storage");
            (!storage.trim().is_empty()).then_some(storage)
        })
        .collect::<HashSet<_>>();
    rows.extend(stored_rows.iter().filter_map(|row| {
        if is_remote_workspace_virtual_row(row) {
            return None;
        }
        if row.kind == BrowserRowKind::Session && promoted_storage_paths.contains(&row.full_path) {
            None
        } else {
            Some(row.clone())
        }
    }));
    let extend_stored_ms = extend_stored_started_at.elapsed().as_secs_f64() * 1000.0;
    if breakdown_enabled {
        maybe_record_sidebar_merge_breakdown(
            remote_session_count,
            json!({
                "cache_hit": false,
                "phase": "uncached_steps",
                "remote_index_ms": remote_index_ms,
                "machine_rows_init_ms": machine_rows_init_ms,
                "merge_live_ms": merge_live_ms,
                "promoted_retain_ms": promoted_retain_ms,
                "resort_ms": resort_ms,
                "local_tree_ms": local_tree_ms,
                "push_live_ms": push_live_ms,
                "push_remote_ms": push_remote_ms,
                "extend_stored_ms": extend_stored_ms,
                "total_ms": total_started_at.elapsed().as_secs_f64() * 1000.0,
                "stored_row_count": stored_rows.len(),
                "remote_machine_count": remote_machines.len(),
                "remote_session_count": remote_session_count,
                "merged_row_count": rows.len(),
                "expanded_path_count": expanded_paths.len(),
            }),
        );
    }
    rows
}
fn filter_stored_rows_for_expansion(
    stored_rows: &[BrowserRow],
    expanded_paths: &HashSet<String>,
) -> Vec<BrowserRow> {
    stored_rows
        .iter()
        .filter(|row| stored_codex_transcript_row_is_visible(row, expanded_paths))
        .cloned()
        .collect()
}
fn filter_remote_workspace_projection_rows(stored_rows: &[BrowserRow]) -> Vec<BrowserRow> {
    stored_rows
        .iter()
        .filter(|row| remote_workspace_virtual_path(row).is_some())
        .cloned()
        .collect()
}
fn remote_workspace_virtual_path(row: &BrowserRow) -> Option<&str> {
    let normalized = row.full_path.trim_start_matches('/');
    normalized
        .strip_prefix("__remote_folder__/")
        .map(|_| normalized)
}
fn is_remote_workspace_virtual_row(row: &BrowserRow) -> bool {
    let normalized = row.full_path.trim_start_matches('/');
    normalized == "__remote_folder__" || normalized.starts_with("__remote_folder__/")
}
fn stored_codex_transcript_row_is_visible(
    row: &BrowserRow,
    expanded_paths: &HashSet<String>,
) -> bool {
    if row.kind != BrowserRowKind::Session {
        return true;
    }
    let Some(root) = codex_storage_root_for_path(&row.full_path) else {
        return true;
    };
    if let Some(cwd) = row
        .session_cwd
        .as_deref()
        .map(str::trim)
        .filter(|cwd| !cwd.is_empty())
    {
        let cwd_under_storage_root = cwd == root
            || cwd
                .strip_prefix(root)
                .is_some_and(|suffix| suffix.starts_with('/'));
        if !cwd_under_storage_root {
            return true;
        }
    }
    expanded_paths.contains(root)
}
/// The codex home directory a storage path sits under (`/home/user/.codex`),
/// for either fork. The store layout that makes this derivable is descriptor
/// data — see [`path_is_in_store_of`].
fn codex_storage_root_for_path(path: &str) -> Option<&str> {
    yggterm_core::AGENT_CLIS
        .iter()
        .filter(|descriptor| yggterm_core::CODEX_FAMILY.contains(&descriptor.kind))
        .find_map(|descriptor| descriptor.store_home_prefix_of(path))
}
#[derive(Default)]
struct RemoteSessionIndex {
    modified_epoch_by_path: HashMap<String, i64>,
    generated_title_by_path: HashMap<String, String>,
    generated_summary_by_path: HashMap<String, String>,
    /// Last-used epoch keyed by SESSION ID — the only key a live row and the
    /// scan that timestamped it agree on.
    ///
    /// ⛔ Not a second encoding of `modified_epoch_by_path`: that map answers
    /// "when was the file at this PATH touched", and a live row's path is a
    /// scheme (`local://<uuid>`), not a file. Both are filled from the same
    /// scan by [`scanned_last_used_epochs_by_session_id`], which is also what
    /// the start page orders by — so the two surfaces cannot disagree.
    last_used_epoch_by_session_id: HashMap<String, i64>,
}

impl RemoteSessionIndex {
    /// When a live session was last used, in epoch seconds; `0` when no scan
    /// has ever timestamped it.
    ///
    /// ⚠ **`0` means "cannot tell", and a caller must not let it decide an
    /// order.** A rank key that answers 0 for the whole corpus ties every row
    /// and hands the ordering to whatever the tie-break is — which is exactly
    /// how the start page came to be sorted alphabetically by UUID. Every
    /// caller here pairs this with a tie-break a reader can NAME.
    fn last_used_epoch(&self, session: &ManagedSessionView) -> i64 {
        self.last_used_epoch_by_session_id
            .get(session.id.trim())
            .copied()
            .unwrap_or(0)
    }
}
// PERF (fan/CPU spin #2, live stack-sampled 2026-06-11 on v2.8.76): the GUI
// main thread pegged ~100% inside ShellState::snapshot ->
// enrich_sidebar_rows_with_live_titles -> build_remote_session_index ->
// looks_like_low_signal_generated_copy — the same per-render recognizer-burn
// class as the 2.8.73 sidebar fix (eec7cb6f), one callee over. Titles and
// summaries for a session only change when the daemon pushes new copy, so
// memoize both verdicts by text hash. Main-thread only -> thread_local, capped.
fn memoized_generated_fallback_title(title: &str) -> bool {
    thread_local! {
        static FALLBACK_TITLE_MEMO: std::cell::RefCell<HashMap<u64, bool>> =
            std::cell::RefCell::new(HashMap::new());
    }
    let key = {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        title.hash(&mut hasher);
        hasher.finish()
    };
    if let Some(hit) = FALLBACK_TITLE_MEMO.with(|memo| memo.borrow().get(&key).copied()) {
        return hit;
    }
    let verdict = looks_like_generated_fallback_title(title);
    FALLBACK_TITLE_MEMO.with(|memo| {
        let mut memo = memo.borrow_mut();
        if memo.len() >= 512 {
            memo.clear();
        }
        memo.insert(key, verdict);
    });
    verdict
}

fn memoized_low_signal_generated_copy(text: &str) -> bool {
    thread_local! {
        static LOW_SIGNAL_COPY_MEMO: std::cell::RefCell<HashMap<u64, bool>> =
            std::cell::RefCell::new(HashMap::new());
    }
    let key = {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        text.hash(&mut hasher);
        hasher.finish()
    };
    if let Some(hit) = LOW_SIGNAL_COPY_MEMO.with(|memo| memo.borrow().get(&key).copied()) {
        return hit;
    }
    let verdict = looks_like_low_signal_generated_copy(text);
    LOW_SIGNAL_COPY_MEMO.with(|memo| {
        let mut memo = memo.borrow_mut();
        if memo.len() >= 512 {
            memo.clear();
        }
        memo.insert(key, verdict);
    });
    verdict
}

fn build_remote_session_index(remote_machines: &[RemoteMachineSnapshot]) -> RemoteSessionIndex {
    let mut index = RemoteSessionIndex::default();
    index.last_used_epoch_by_session_id = scanned_last_used_epochs_by_session_id(remote_machines);
    for machine in remote_machines {
        for session in &machine.sessions {
            index
                .modified_epoch_by_path
                .insert(session.session_path.clone(), session.modified_epoch);
            let mut title = session.title_hint.trim();
            // Strip Agent unnamed prefix so remote grok/muse show real title
            // Use simple check so all kinds covered even if is_agent_plane table lags
            if title.starts_with("Agent ") && title.contains(" unnamed ") {
                if let Some(colon) = title.find(": ") {
                    let suffix = title[colon + 2..].trim();
                    if !suffix.is_empty() && !memoized_generated_fallback_title(suffix) {
                        title = suffix;
                    }
                }
            }
            if !title.is_empty() && !memoized_generated_fallback_title(title) {
                index
                    .generated_title_by_path
                    .entry(session.session_path.clone())
                    .or_insert_with(|| title.to_string());
            }
            if let Some(summary) = session
                .cached_summary
                .as_deref()
                .filter(|summary| !summary.trim().is_empty())
                .filter(|summary| !memoized_low_signal_generated_copy(summary))
            {
                index
                    .generated_summary_by_path
                    .entry(session.session_path.clone())
                    .or_insert_with(|| summary.to_string());
            }
        }
    }
    index
}
/// Does this row head a row set — is it drawn with a disclosure control?
///
/// ⭐ **The count IS the answer, and that is not a shortcut.** A row's
/// `descendant_sessions` has always meant "sessions beneath me": 1 for a leaf,
/// N for a folder. A Live-Sessions head counts its members in the same field, so
/// the disclosure control, the count badge and the folder rows all read one
/// number rather than a second flag that could disagree with it.
///
/// The split compound row is excluded BY PATH: it also counts (its panes), but a
/// split is a VIEW and a row set is an ARRANGEMENT — `DESIGN.md` §"Row sets and
/// splits are orthogonal" — and giving it a disclosure control would offer to
/// collapse rows it does not hold.
fn row_heads_a_row_set(row: &BrowserRow) -> bool {
    matches!(row.kind, BrowserRowKind::Session | BrowserRowKind::Document)
        && row.descendant_sessions > 1
        && !row.full_path.starts_with("split://")
}

fn push_live_session_rows(
    rows: &mut Vec<BrowserRow>,
    sessions: &[&ManagedSessionView],
    remote_session_index: &RemoteSessionIndex,
    expanded_paths: &HashSet<String>,
    collapsed_row_set_heads: &HashSet<String>,
    arrangement: &yggterm_core::row_set_outline::RowArrangement,
) {
    if sessions.is_empty() {
        return;
    }
    let group_path = "__live_sessions__".to_string();
    let expanded = expanded_paths.contains(&group_path);
    rows.push(BrowserRow {
        kind: BrowserRowKind::Group,
        full_path: group_path.clone(),
        label: "Live Sessions".to_string(),
        detail_label: String::new(),
        document_kind: None,
        group_kind: None,
        session_title: None,
        depth: 0,
        host_label: "live".to_string(),
        descendant_sessions: sessions.len(),
        expanded,
        session_id: None,
        session_cwd: None,
        session_kind: None,
    });
    if !expanded {
        return;
    }
    // ⭐⭐ OUTLINE ORDER IS A PROPERTY OF THE SEATS, NOT OF ARRIVAL — AND THE
    // SIDEBAR DRAWS IT CONTINUOUSLY. `sort_by_outline` documents itself as "the
    // one sort … both the rendered sidebar and any verb that reports an order
    // call this", and the rendered sidebar was the half that never did: the only
    // caller was `AppControlCommand::SortSessions`, so correct order was a manual
    // repair somebody had to remember and every spawn, fold and re-group undid
    // it. Owner-reported twice on 2026-08-21 as rows not being in ascending
    // order.
    //
    // ⚠ THE COMPARATOR WAS NEVER THE BUG. It parses a seat into `Vec<u64>` and
    // has a test named for the ten-before-two trap. What was missing is that
    // nothing on the render path asked it.
    //
    // ⚖ A SEATED ROW CAN NO LONGER BE HAND-ORDERED OUT OF SEAT ORDER HERE, and
    // that is the intended model rather than a casualty: the seat IS the order.
    // The sort is stable, so un-numbered rows keep the arrangement a drag gave
    // them and only fall in around the numbered ones.
    let sessions: Vec<&ManagedSessionView> = {
        let mut ordered = sessions.to_vec();
        yggterm_core::session_outline::sort_by_outline(&mut ordered, |session| {
            session.outline_prefix.clone()
        });
        ordered
    };
    let sessions = sessions.as_slice();
    let short_ids = unique_session_short_ids_for_pairs(
        &sessions
            .iter()
            .map(|session| (session.session_path.clone(), session.id.clone()))
            .collect::<Vec<_>>(),
    );
    let seats = live_session_seats(sessions.iter().copied());
    // ⭐ ROW SETS. The seats the rows already hold say which of them belong
    // together — `6.1` under `6.0`, `6.1.1` under `6.1` — and
    // `row_set_outline` is the one place that reading happens. Built here, from
    // the paths the rows are ABOUT to carry, so a Document row is arranged by
    // the file path it will show rather than by its session path.
    //
    // ⛔ Derived, never stored: a saved copy would disagree with the seats the
    // moment a delegate is reseated or reaped.
    let row_paths: Vec<String> = sessions
        .iter()
        .map(|session| live_session_row_path(session))
        .collect();
    let row_sets = yggterm_core::row_set_outline::sidebar_row_sets(
        row_paths
            .iter()
            .zip(sessions.iter())
            .map(|(path, session)| (path.as_str(), session.outline_prefix.as_deref())),
        arrangement,
        collapsed_row_set_heads,
    );
    // Two live rows CAN name one path (a document open twice over). The
    // arrangement holds each path once, so the emit walks the sessions AT a
    // path rather than assuming one — otherwise nesting would silently drop a
    // row the flat list used to draw.
    let mut sessions_at_path: HashMap<&str, Vec<usize>> = HashMap::new();
    for (index, path) in row_paths.iter().enumerate() {
        sessions_at_path.entry(path.as_str()).or_default().push(index);
    }
    for (path, nesting) in row_sets.visible_rows(row_paths.iter().map(String::as_str)) {
        for index in sessions_at_path.get(path.as_str()).into_iter().flatten() {
            let session = sessions[*index];
            let cwd = metadata_value(session, "Cwd");
            let label =
                live_session_label_with_index(remote_session_index, session, &short_ids, &seats);
            let detail_label = {
                let summary = live_session_summary_with_index(remote_session_index, session);
                live_session_detail_label(summary, live_session_keep_alive(session))
            };
            rows.push(BrowserRow {
                kind: if session.kind == SessionKind::Document {
                    BrowserRowKind::Document
                } else {
                    BrowserRowKind::Session
                },
                full_path: path.clone(),
                label: label.clone(),
                detail_label,
                document_kind: (session.kind == SessionKind::Document)
                    .then_some(WorkspaceDocumentKind::Note),
                group_kind: None,
                session_title: Some(label),
                // Live Sessions rows sit at depth 1; a set adds its own.
                // ⚠ INDENTATION IS BUDGETED (`DESIGN.md` §"Row sets"): step two
                // levels, then hold and let the head's own number carry the
                // depth. A title clipped to nothing is worse than a column that
                // stops stepping.
                depth: 1 + nesting.min(ROW_SET_MAX_INDENT_LEVELS),
                host_label: session.host_label.clone(),
                descendant_sessions: 1 + row_sets.descendant_count(&path),
                expanded: !row_sets.is_collapsed(&path),
                session_id: Some(session.id.clone()),
                session_cwd: (!cwd.trim().is_empty()).then_some(cwd),
                session_kind: Some(session.kind),
            });
        }
    }
}

/// How many levels of a row set's nesting the sidebar actually indents.
///
/// `DESIGN.md` §"Row sets": the sidebar runs out of horizontal room long before
/// the outline runs out of levels, so past this the indent holds and the head's
/// own number carries the depth.
const ROW_SET_MAX_INDENT_LEVELS: usize = 2;

/// The sidebar path a live session's own row carries.
///
/// A Document row is addressed by the FILE it shows — that is the path the tree,
/// the selection and the arrangement all key on — and every other session by its
/// normalized session path.
fn live_session_row_path(session: &ManagedSessionView) -> String {
    if session.kind == SessionKind::Document {
        session
            .metadata
            .iter()
            .find(|entry| entry.label == "Path")
            .map(|entry| entry.value.trim().to_string())
            .filter(|value| !value.is_empty())
            .unwrap_or_else(|| normalize_live_session_path(&session.session_path))
    } else {
        normalize_live_session_path(&session.session_path)
    }
}
/// A synthetic compound sidebar row for a split group — a miniature map of the
/// split geometry ([[campaign-split-view-groups]]). `full_path` is `split://<id>`
/// so the renderer can recognise it and pull geometry from the group SSOT;
/// `session_id` carries the group id.
fn split_compound_row(group: &SplitGroup, depth: usize, host_label: String) -> BrowserRow {
    BrowserRow {
        kind: BrowserRowKind::Session,
        full_path: group.synthetic_path(),
        label: format!("Split · {} panes", group.members.len()),
        detail_label: String::new(),
        document_kind: None,
        group_kind: None,
        session_title: None,
        depth,
        host_label,
        descendant_sessions: group.members.len(),
        expanded: true,
        session_id: Some(group.group_id.clone()),
        session_cwd: None,
        session_kind: None,
    }
}

/// A short fallback label for a split pane cell when the live session has no
/// title yet (the last path segment).
fn split_pane_fallback_label(member: &str) -> String {
    member
        .trim_end_matches('/')
        .rsplit('/')
        .next()
        .filter(|segment| !segment.is_empty())
        .unwrap_or(member)
        .to_string()
}

/// If `row` is a compound split row, build its pane cells (title + focus state)
/// from the group SSOT and the live sessions, plus whether it is side-by-side.
/// `None` for every ordinary row ([[campaign-split-view-groups]]).
fn split_group_cells_for_row(
    snapshot: &RenderSnapshot,
    row: &BrowserRow,
) -> Option<(Vec<SplitPaneCell>, bool)> {
    if !row.full_path.starts_with("split://") {
        return None;
    }
    let group_id = row.session_id.as_deref()?;
    let group = snapshot
        .split_groups
        .iter()
        .find(|group| group.group_id == group_id)?;
    let cells = group
        .members
        .iter()
        .map(|member| {
            let label = snapshot
                .live_sessions
                .iter()
                .find(|session| session.session_path == member.session)
                .map(|session| session.title.clone())
                .filter(|title| !title.trim().is_empty())
                .unwrap_or_else(|| split_pane_fallback_label(&member.session));
            SplitPaneCell {
                path: member.session.clone(),
                label,
                focused: snapshot.active_session_path.as_deref() == Some(member.session.as_str()),
            }
        })
        .collect();
    Some((cells, matches!(group.axis, SplitAxis::SideBySide)))
}

/// Collapse each split group's Live-Sessions member rows into ONE compound row
/// that mirrors the split geometry ([[campaign-split-view-groups]]). Bounded to
/// the Live Sessions region of the render rows; the cwd-tree member rows (dual
/// presence) are left intact and get a split-glyph badge at render time. The
/// compound row takes the position of the group's earliest member so row order
/// stays stable.
fn collapse_live_sessions_into_split_rows(rows: &mut Vec<BrowserRow>, groups: &[SplitGroup]) {
    if groups.is_empty() {
        return;
    }
    let Some(start) = rows
        .iter()
        .position(|row| row.full_path == "__live_sessions__")
    else {
        return;
    };
    let region_end = rows
        .iter()
        .enumerate()
        .skip(start + 1)
        .find(|(_, row)| row.depth == 0)
        .map(|(idx, _)| idx)
        .unwrap_or(rows.len());
    let mut compound_at: HashMap<usize, BrowserRow> = HashMap::new();
    let mut drop_indices: HashSet<usize> = HashSet::new();
    for group in groups {
        let member_positions: Vec<usize> = ((start + 1)..region_end)
            .filter(|idx| !drop_indices.contains(idx))
            .filter(|idx| group.contains(&rows[*idx].full_path))
            .collect();
        // Only compound when at least two members are actually present in Live
        // Sessions; a partial group falls back to plain rows.
        if member_positions.len() < 2 {
            continue;
        }
        let first = member_positions[0];
        let compound =
            split_compound_row(group, rows[first].depth, rows[first].host_label.clone());
        compound_at.insert(first, compound);
        for idx in member_positions {
            drop_indices.insert(idx);
        }
    }
    if compound_at.is_empty() {
        return;
    }
    let mut rebuilt: Vec<BrowserRow> = Vec::with_capacity(rows.len());
    for (idx, row) in std::mem::take(rows).into_iter().enumerate() {
        if let Some(compound) = compound_at.remove(&idx) {
            rebuilt.push(compound);
        } else if drop_indices.contains(&idx) {
            // Dropped member — already represented by its compound row.
        } else {
            rebuilt.push(row);
        }
    }
    *rows = rebuilt;
}

fn local_live_session_group_paths(cwd: &str) -> Vec<String> {
    let mut paths = vec!["local".to_string()];
    let trimmed = cwd.trim();
    if trimmed.is_empty() {
        return paths;
    }
    let path = Path::new(trimmed);
    let mut ancestors = path
        .ancestors()
        .filter_map(|ancestor| {
            let value = ancestor.to_string_lossy().trim().to_string();
            if value.is_empty() || value == "." || value == "/" || value == trimmed {
                None
            } else {
                Some(value)
            }
        })
        .collect::<Vec<_>>();
    ancestors.reverse();
    paths.extend(ancestors);
    paths
}
fn synthetic_local_live_session_rows(
    sessions: &[&ManagedSessionView],
    _remote_session_index: &RemoteSessionIndex,
) -> Vec<BrowserRow> {
    if sessions.is_empty() {
        return Vec::new();
    }
    // ⛔ THIS FUNCTION EMITS GROUP HEADERS ONLY — it builds the folder
    // scaffolding, never the session rows under it. A group is emitted the
    // first time its cwd is seen, so ONLY the cwd ordering is observable here;
    // two sessions sharing a cwd produce identical group paths and the second
    // is swallowed by `emitted_groups`.
    //
    // ⚠ There used to be a `.then_with(|a, b| a.session_path.cmp(...))` on this
    // sort, and it read like the thing that ordered live rows inside a folder.
    // It could not: it was unobservable in this function's output, and it sent
    // a reader looking for the sidebar's ordering bug to a line that has never
    // decided an order. The rows themselves are ordered by
    // `inject_cc_sessions_into_stored_rows`, which is the one owner of live
    // session row emission — including for the groups built here.
    let mut ordered_sessions = sessions.to_vec();
    ordered_sessions.sort_by_key(|session| metadata_value(session, "Cwd"));
    let mut rows = Vec::new();
    let mut emitted_groups = HashSet::<String>::new();
    for session in ordered_sessions {
        let cwd = metadata_value(session, "Cwd");
        let group_paths = local_live_session_group_paths(&cwd);
        for (depth, group_path) in group_paths.iter().enumerate() {
            if !emitted_groups.insert(group_path.clone()) {
                continue;
            }
            rows.push(BrowserRow {
                kind: BrowserRowKind::Group,
                full_path: group_path.clone(),
                label: group_path.clone(),
                detail_label: String::new(),
                document_kind: None,
                group_kind: None,
                session_title: None,
                depth,
                host_label: "local".to_string(),
                descendant_sessions: 1,
                expanded: true,
                session_id: None,
                session_cwd: (group_path != "local").then_some(group_path.clone()),
                session_kind: None,
            });
        }
    }
    rows
}
fn inject_local_live_session_rows(
    stored_rows: &[BrowserRow],
    sessions: &[&ManagedSessionView],
    remote_session_index: &RemoteSessionIndex,
) -> Vec<BrowserRow> {
    if sessions.is_empty() {
        return stored_rows.to_vec();
    }
    let has_group_rows = stored_rows
        .iter()
        .any(|row| row.kind == BrowserRowKind::Group);
    if !has_group_rows {
        // The scaffolding is synthesised, then filled by the SAME injector the
        // stored-row path uses. It used to return the bare group headers and
        // stop, which projected a live session's folder into the cwd tree with
        // nothing inside it — the session was reachable only under Live
        // Sessions. One owner for session rows also means one owner for their
        // order, so a fresh profile and an established one cannot sort a folder
        // differently.
        let synthetic = synthetic_local_live_session_rows(sessions, remote_session_index);
        return inject_cc_sessions_into_stored_rows(&synthetic, sessions, remote_session_index);
    }
    inject_cc_sessions_into_stored_rows(stored_rows, sessions, remote_session_index)
}

fn find_best_group_for_cwd_in_rows(rows: &[BrowserRow], cwd: &str) -> Option<(usize, usize)> {
    let cwd = cwd.trim();
    if cwd.is_empty() {
        return rows
            .iter()
            .enumerate()
            .find(|(_, r)| r.kind == BrowserRowKind::Group && r.full_path == "local")
            .map(|(idx, r)| (idx, r.depth));
    }
    let path = std::path::Path::new(cwd);
    let ancestors = path.ancestors().skip(1).filter_map(|p| {
        let s = p.to_string_lossy().to_string();
        if s.is_empty() || s == "/" {
            None
        } else {
            Some(s)
        }
    });
    let candidates = std::iter::once(cwd.to_string())
        .chain(ancestors)
        .chain(std::iter::once("local".to_string()));
    for candidate in candidates {
        if let Some(idx) = rows
            .iter()
            .position(|r| r.kind == BrowserRowKind::Group && r.full_path == candidate)
        {
            return Some((idx, rows[idx].depth));
        }
    }
    None
}

fn find_child_insert_point(rows: &[BrowserRow], group_idx: usize, group_depth: usize) -> usize {
    let mut idx = group_idx + 1;
    while idx < rows.len() && rows[idx].depth > group_depth {
        idx += 1;
    }
    idx
}

fn inject_cc_sessions_into_stored_rows(
    stored_rows: &[BrowserRow],
    sessions: &[&ManagedSessionView],
    remote_session_index: &RemoteSessionIndex,
) -> Vec<BrowserRow> {
    let short_ids = unique_session_short_ids_for_pairs(
        &sessions
            .iter()
            .map(|s| (s.session_path.clone(), s.id.clone()))
            .collect::<Vec<_>>(),
    );
    // ⛔ THERE IS NO session_id SKIP HERE, AND ADDING ONE BACK IS A SPEC VIOLATION.
    //
    // One used to live here. It skipped any live session whose `session_id`
    // already appeared on a stored row, and its stated reason was
    // `inject_file_backed_cc_session_rows` — a post-hoc injector **deleted on
    // 2026-05-26** (see the note below this function). Once that producer was
    // gone the guard kept firing, now against the ordinary SCANNED leaf that
    // `build_local_cwd_tree` emits for the session's own transcript. So the
    // live row was dropped here while `promoted_storage_paths` in
    // `merged_sidebar_rows_uncached` independently dropped the scanned leaf,
    // and the two suppressions CANCELLED: a live agent session with a
    // transcript on disk vanished from the cwd tree altogether.
    //
    // ⚠ It survived because the symptom inverts on a condition nobody varies:
    // a live session with NO transcript matches nothing here, so it is the only
    // one the tree still shows — and it was that lone survivor, not the 56
    // missing rows, that got filed as the bug.
    //
    // `AGENTS.md` "Session display = dual presence" rules on this directly:
    // *"Never silently filter a live session out of the cwd tree just because it
    // also appears in Live Sessions; if you find dedup code that does this, that
    // is a SPEC VIOLATION. Acceptable dedup is per-view (one row per logical
    // session within the same tree), not cross-view."*
    //
    // ⇒ Per-view dedup has exactly ONE owner, and it is not here: the
    // `promoted_storage_paths` filter, which drops the scanned leaf because the
    // injected live row already occupies that slot in the SAME tree. Keying on
    // the storage path is what makes it per-view — a `session_id` is shared by
    // every view, so a `session_id` key can only ever express a cross-view rule.
    let seats = live_session_seats(sessions.iter().copied());
    // ⛔ THE ORDER OF THESE ROWS IS PART OF THE CONTRACT — see
    // `docs/pending-bugs.md`, "the start page cannot be used to find a session".
    //
    // Most recently used first, exactly as the start page now states its own
    // rule, and the tie-break is the LIVE SESSIONS ORDER — the user's own
    // outline numbering, which is a manual order they authored and can name.
    //
    // It must never fall through to `session_path`: a live local row's path is
    // `local://<uuid>`, so a uuid tie-break sorts a folder alphabetically by a
    // number that means nothing. That is the defect this fix exists to close,
    // and the reason `last_used_epoch` documents its `0` so loudly — a purely
    // local live row has no scan to timestamp it, so the epoch IS 0 for all of
    // them and the tie-break is what actually orders the folder.
    let mut ordered_sessions = sessions.iter().copied().enumerate().collect::<Vec<_>>();
    ordered_sessions.sort_by(|(a_seq, a), (b_seq, b)| {
        remote_session_index
            .last_used_epoch(b)
            .cmp(&remote_session_index.last_used_epoch(a))
            .then_with(|| a_seq.cmp(b_seq))
    });
    let mut insertions: Vec<(usize, usize, BrowserRow)> = Vec::new();
    for (rank, session) in ordered_sessions.into_iter().map(|(_, s)| s).enumerate() {
        let cwd = metadata_value(session, "Cwd");
        let Some((group_idx, group_depth)) = find_best_group_for_cwd_in_rows(stored_rows, &cwd)
        else {
            continue;
        };
        // XTERM-BUG: cwd-tree-expand-bypass (Bug2) — do not inject a live session under a
        // COLLAPSED cwd group. Live local agent rows (local://, codex-runtime://, live::)
        // bypass the stored-row expansion filter, so without this gate they render under
        // a collapsed /home/user. Mirror file-backed leaves, which are hidden when their
        // parent group is collapsed (the session still appears under Live Sessions).
        if !stored_rows[group_idx].expanded {
            continue;
        }
        let insert_idx = find_child_insert_point(stored_rows, group_idx, group_depth);
        let label =
            live_session_label_with_index(remote_session_index, session, &short_ids, &seats);
        let summary = live_session_summary_with_index(remote_session_index, session);
        let keep_alive = live_session_keep_alive(session);
        let detail_label = live_session_detail_label(summary, keep_alive);
        let cwd_opt = if cwd.trim().is_empty() {
            None
        } else {
            Some(cwd)
        };
        insertions.push((
            insert_idx,
            rank,
            BrowserRow {
                kind: BrowserRowKind::Session,
                full_path: normalize_live_session_path(&session.session_path),
                label: label.clone(),
                detail_label,
                document_kind: None,
                group_kind: None,
                session_title: Some(label),
                depth: group_depth + 1,
                host_label: session.host_label.clone(),
                descendant_sessions: 1,
                expanded: true,
                session_id: Some(session.id.clone()),
                session_cwd: cwd_opt,
                session_kind: Some(session.kind),
            },
        ));
    }
    if insertions.is_empty() {
        return stored_rows.to_vec();
    }
    // Insert from back to front so earlier indices are not shifted by later
    // insertions.
    //
    // ⚠ **The tie must run backwards too, and that is not decoration.** Every
    // row destined for the SAME cwd group shares one insert point, so with a
    // forward tie the first row is inserted first and each successor then
    // pushes it down — the group comes out in exactly REVERSE order. That is
    // what the sidebar was doing: it showed the user's Live Sessions order
    // upside down inside every cwd folder, which reads as no order at all.
    insertions.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| b.1.cmp(&a.1)));
    let mut result = stored_rows.to_vec();
    for (idx, _rank, row) in insertions {
        result.insert(idx, row);
    }
    result
}
// inject_file_backed_cc_session_rows was deleted 2026-05-26.
// Per [[spec-cwd-tree-agent-cli-unified]]: file-backed CC sessions are now
// native leaves in the local cwd tree (built via
// yggterm_core::build_local_cwd_tree which calls
// yggterm_core::scan_local_claude_code_sessions alongside
// yggterm_core::scan_local_codex_sessions). The prior post-hoc injection
// bypassed expand/collapse state, causing CC rows to render at child depth
// even when their parent group was collapsed — visually orphaned.
// LIVE (running) CC sessions still need separate injection — see
// `inject_cc_sessions_into_stored_rows` below — because they come from
// `ManagedSessionView` in-memory state, not from a JSONL file scan.

fn live_session_label_with_index(
    remote_session_index: &RemoteSessionIndex,
    session: &ManagedSessionView,
    short_ids: &HashMap<String, String>,
    seats: &[String],
) -> String {
    let heads_a_group = session.outline_prefix.as_deref().is_some_and(|prefix| {
        yggterm_core::session_outline::outline_prefix_heads_a_group(
            prefix,
            seats.iter().map(String::as_str),
        )
    });
    compose_outline_prefix(
        session.outline_prefix.as_deref(),
        &live_session_derived_label(remote_session_index, session, short_ids),
        heads_a_group,
    )
}

/// Every seat currently on the live list — the input the group-head question is
/// answered from.
///
/// ⚠ The row builders below see only the SUBSET they are drawing, so their
/// answer is a first cut. `enrich_sidebar_rows_with_live_titles` re-composes
/// every row from the WHOLE list and is the documented last writer of a label,
/// so the authoritative answer is always its own. That is why the composer
/// accepts both spellings of a seat as already-composed: the two passes may
/// legitimately disagree for one frame, and the second must be able to redraw
/// the first rather than number it twice.
fn live_session_seats<'a>(
    live_sessions: impl IntoIterator<Item = &'a ManagedSessionView>,
) -> Vec<String> {
    live_sessions
        .into_iter()
        .filter_map(|session| session.outline_prefix.clone())
        .collect()
}

/// `prefix + " " + label`, and the ONE place the two are joined.
///
/// The outline number and the title are separate facts with separate owners:
/// the CLI rewrites the title whenever it likes, the prefix says where the row
/// sits. Composing them here means a CLI rename can never destroy a number,
/// which is what made the user's sidebar outline decay on every session.
///
/// `heads_a_group` decides only how the number is DRAWN — see
/// [`yggterm_core::session_outline::render_outline_prefix`]. It is derived from
/// the seats that exist right now, never stored.
fn compose_outline_prefix(prefix: Option<&str>, label: &str, heads_a_group: bool) -> String {
    let Some(prefix) = prefix.map(str::trim).filter(|value| !value.is_empty()) else {
        return label.to_string();
    };
    // A prefix the outline cannot parse is composed VERBATIM. The setter
    // refuses those today, but a row stored before it existed may still carry
    // one (`2. cogs:`), and dropping its number to punish its spelling would
    // lose the only thing the user put there by hand.
    let rendered = yggterm_core::session_outline::render_outline_prefix(prefix, heads_a_group)
        .unwrap_or_else(|| prefix.to_string());
    // Idempotent: re-composing a label that already carries its seat must not
    // stutter (`2. cogs: 2. cogs: …`), because a row is relabelled on every
    // snapshot. Both spellings of the same seat count as already-composed — the
    // trailing dot appears and disappears as the group gains and loses members,
    // and a row caught mid-change must be RE-drawn, not double-numbered.
    //
    // ⛔ The remainder must begin with WHITESPACE or be empty. A bare
    // `starts_with` reads seat `1` off the label `10 things` and would hand
    // back `1. 0 things` — the number eating a digit of the title.
    let label = label.trim_start();
    let canonical = rendered.trim_end_matches('.');
    let dotted = format!("{canonical}.");
    // BOTH spellings, whichever way this render happens to be going: the seat
    // already on the label may be the one the previous pass drew.
    let body = [rendered.as_str(), dotted.as_str(), canonical]
        .into_iter()
        .find_map(|seat| {
            label
                .strip_prefix(seat)
                .filter(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
        })
        .unwrap_or(label)
        .trim_start();
    if body.is_empty() {
        return rendered;
    }
    format!("{rendered} {body}")
}

fn live_session_derived_label(
    remote_session_index: &RemoteSessionIndex,
    session: &ManagedSessionView,
    short_ids: &HashMap<String, String>,
) -> String {
    let title = session.title.trim();
    // "Agent unnamed <kind>: <real>" holds the real title after the colon —
    // return just the real part so rows/startpage don't render the prefix.
    // Use simple prefix check so grok-build/muse (which may not be in
    // is_agent_plane composed table yet) are also handled.
    if title.starts_with("Agent ") && title.contains(" unnamed ") {
        if let Some(colon) = title.find(": ") {
            let suffix = title[colon + 2..].trim();
            if !suffix.is_empty() && !memoized_generated_fallback_title(suffix) {
                return suffix.to_string();
            }
        }
    }
    let is_unnamed_agent_title =
        yggterm_core::is_agent_plane_composed_title(title) && title.contains(" unnamed ");
    if !title.is_empty() && !memoized_generated_fallback_title(title) && !is_unnamed_agent_title {
        return session.title.clone();
    }
    if let Some(remote_title) = remote_session_index
        .generated_title_by_path
        .get(&session.session_path)
        .filter(|title| !title.trim().is_empty() && !memoized_generated_fallback_title(title))
    {
        return remote_title.clone();
    }
    let target = metadata_value(session, "Target");
    if !target.trim().is_empty()
        && target != "document"
        && target != "local-shell"
        && target != "local-codex"
        && target != "local-codex-litellm"
        && target != session.host_label
    {
        return target;
    }
    let cwd = metadata_value(session, "Cwd");
    if !cwd.trim().is_empty() {
        return humanized_terminal_title(session.kind, &cwd, Some(&session.host_label))
            .unwrap_or(cwd);
    }
    if !title.is_empty() && !memoized_generated_fallback_title(title) {
        return session.title.clone();
    }
    humanized_terminal_title(session.kind, &cwd, Some(&session.host_label))
        .or_else(|| short_ids.get(&session.session_path).cloned())
        .filter(|title| !memoized_generated_fallback_title(title))
        .unwrap_or_else(|| {
            humanized_terminal_title(session.kind, "", Some(&session.host_label))
                .unwrap_or_else(|| "Terminal Session".to_string())
        })
}
fn live_session_summary_with_index(
    remote_session_index: &RemoteSessionIndex,
    session: &ManagedSessionView,
) -> String {
    preview_summary_metadata_value(session, "Summary")
        .or_else(|| resolved_session_summary_for_search(session))
        .or_else(|| live_session_default_summary(session))
        .filter(|summary| !memoized_low_signal_generated_copy(summary))
        .or_else(|| {
            remote_session_index
                .generated_summary_by_path
                .get(&session.session_path)
                .cloned()
        })
        .unwrap_or_default()
}
/// The metadata label that carries a live session's keep-alive truth. One
/// constant so the `ManagedSessionView` and `SnapshotSessionView` readers below
/// cannot drift apart.
const RUNTIME_PERSISTENCE_LABEL: &str = "Runtime Persistence";
const RUNTIME_PERSISTENCE_KEEP_ALIVE: &str = "keep-alive";
fn live_session_keep_alive(session: &ManagedSessionView) -> bool {
    metadata_value(session, RUNTIME_PERSISTENCE_LABEL) == RUNTIME_PERSISTENCE_KEEP_ALIVE
}
/// Keep-alive as reported by a daemon SNAPSHOT (the reply to a request), which
/// carries `SnapshotSessionView` rather than `ManagedSessionView`.
fn snapshot_session_keep_alive(session: &SnapshotSessionView) -> bool {
    snapshot_metadata_value(session, RUNTIME_PERSISTENCE_LABEL) == RUNTIME_PERSISTENCE_KEEP_ALIVE
}
fn live_session_temporary_update_restore(session: &ManagedSessionView) -> bool {
    metadata_value(session, "Runtime Restore Reason") == "update-restart"
}
fn live_session_restart_protected(session: &ManagedSessionView) -> bool {
    live_session_keep_alive(session) || live_session_temporary_update_restore(session)
}
fn live_session_detail_label(summary: String, keep_alive: bool) -> String {
    if !keep_alive {
        return summary;
    }
    let summary = summary
        .trim()
        .strip_prefix("Kept alive")
        .unwrap_or_else(|| summary.trim())
        .trim_start_matches('·')
        .trim();
    if summary.is_empty() {
        "Kept alive".to_string()
    } else {
        format!("Kept alive · {summary}")
    }
}
fn live_session_enriched_detail_label(
    row_path: &str,
    summary: String,
    kept_alive_paths: &HashSet<String>,
    cwd_warned_paths: &HashSet<String>,
) -> String {
    let summary = if cwd_warned_paths.contains(row_path) {
        format!("{CWD_NOT_HERE_PREFIX} {summary}")
    } else {
        summary
    };
    live_session_detail_label(summary, kept_alive_paths.contains(row_path))
}

/// Opens the detail line of a row whose launch could not be given the
/// directory it asked for. It goes IN FRONT of whatever sentence won —
/// stored, generated, or default — because the thing being corrected is the
/// claim those sentences make, and a correction that trails a claim is read
/// after it or not at all.
const CWD_NOT_HERE_PREFIX: &str =
    "⚠ NOT in the directory this row names — it does not exist on this machine.";
/// How a row's summary should speak about its working directory.
///
/// ⛔ "rooted at X" is a claim about where the process IS, and it was made
/// unconditionally from what the launch ASKED FOR. A local launch into a
/// directory that does not exist here still starts — the launch prefix walks
/// up to an existing ancestor and falls back to `$HOME` on purpose — so the
/// row asserted a location the process had never been in, and read as healthy
/// for as long as it lived. When the daemon has marked the row, the sentence
/// says what actually happened instead.
fn session_cwd_phrase(session: &ManagedSessionView, cwd: &str) -> String {
    if metadata_value(session, "Cwd Warning").trim().is_empty() {
        format!("rooted at {cwd}")
    } else {
        format!("NOT in {cwd} — that directory does not exist on this machine, so it started elsewhere")
    }
}

fn live_session_default_summary(session: &ManagedSessionView) -> Option<String> {
    let cwd = session_cwd_for_managed_session(session)
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .map(|value| session_cwd_phrase(session, &value));
    match session.kind {
        SessionKind::SshShell => {
            let target = session
                .ssh_target
                .clone()
                .or_else(|| {
                    let target = metadata_value(session, "Target");
                    (!target.trim().is_empty()).then_some(target)
                })
                .unwrap_or_else(|| session.host_label.clone());
            Some(match cwd {
                Some(phrase) => format!("SSH terminal on {target} {phrase}."),
                None => format!("SSH terminal on {target}."),
            })
        }
        SessionKind::Shell => Some(match cwd {
            Some(phrase) => format!("Local shell {phrase}."),
            None => "Local shell terminal.".to_string(),
        }),
        SessionKind::Document => Some("Document preview.".to_string()),
        // Every agent CLI, named by its descriptor. The three shipped sentences
        // are preserved word for word — `terminal` for the codex family and
        // `session` for Claude Code, which is the vocabulary each already had —
        // and a new CLI takes `session`.
        kind => {
            let descriptor = yggterm_core::agent_cli::agent_cli_descriptor(kind)?;
            let name = match kind {
                SessionKind::CodexLiteLlm => "Codex LiteLLM",
                _ => descriptor.display_name,
            };
            let noun = if yggterm_core::agent_cli::CODEX_FAMILY.contains(&kind) {
                "terminal"
            } else {
                "session"
            };
            Some(match cwd {
                Some(phrase) => format!("Local {name} {noun} {phrase}."),
                None => format!("Local {name} {noun}."),
            })
        }
    }
}
#[cfg(test)]
fn live_session_label(
    remote_machines: &[RemoteMachineSnapshot],
    session: &ManagedSessionView,
    short_ids: &HashMap<String, String>,
) -> String {
    let remote_session_index = build_remote_session_index(remote_machines);
    let seats = live_session_seats(std::iter::once(session));
    live_session_label_with_index(&remote_session_index, session, short_ids, &seats)
}
fn is_local_tree_live_session(session: &ManagedSessionView) -> bool {
    // Every agent CLI, derived. The hand-listed triple silently answered
    // `false` for a fourth, which drops its live row out of the local cwd tree
    // altogether — the row exists and the tree does not show it.
    is_local_live_session_path(&session.session_path) && session.kind.is_agent()
}
fn is_live_local_stored_codex_terminal_session(session: &ManagedSessionView) -> bool {
    session.source == SessionSource::LiveLocal
        && matches!(session.kind, SessionKind::Codex | SessionKind::CodexLiteLlm)
        && is_local_codex_history_session_path(&session.session_path)
}
fn is_promoted_live_session(session: &ManagedSessionView) -> bool {
    matches!(
        session.source,
        SessionSource::LiveLocal | SessionSource::LiveSsh
    ) && session.kind != SessionKind::Document
        && is_hot_terminal_sidebar_path(&session.session_path)
}
fn enrich_sidebar_rows_with_live_titles(
    rows: &mut [BrowserRow],
    live_sessions: &[ManagedSessionView],
    remote_machines: &[RemoteMachineSnapshot],
    session_title_overrides: &BTreeMap<String, String>,
    generated_summaries: &BTreeMap<String, String>,
) {
    let mut title_by_path = HashMap::<String, String>::new();
    let mut summary_by_path = HashMap::<String, String>::new();
    let mut authoritative_live_paths = HashSet::<String>::new();
    let mut remote_live_direct_title_paths = HashSet::<String>::new();
    let mut kept_alive_paths = HashSet::<String>::new();
    let mut cwd_warned_paths = HashSet::<String>::new();
    let remote_session_index = build_remote_session_index(remote_machines);
    for session in live_sessions {
        if !matches!(session.source, SessionSource::Stored) {
            authoritative_live_paths.insert(session.session_path.clone());
        }
        if live_session_keep_alive(session) {
            kept_alive_paths.insert(session.session_path.clone());
        }
        // ⛔ Collected here rather than inside the summary builder because the
        // summary the sidebar shows is usually NOT built here at all: a stored
        // or LLM-generated one wins, and the birth-time default that produced
        // "rooted at <dir>" is written by a same-named function in the SERVER
        // crate. Whichever sentence wins, the warning has to survive it, so it
        // is applied where the label is finally composed.
        if !metadata_value(session, "Cwd Warning").trim().is_empty() {
            cwd_warned_paths.insert(session.session_path.clone());
        }
        let session_cwd = session_cwd_for_managed_session(session);
        let cwd = session_cwd.as_deref().unwrap_or_default();
        let summary = generated_summaries
            .get(&session.session_path)
            .cloned()
            .filter(|summary| !summary.trim().is_empty())
            .filter(|summary| !memoized_low_signal_generated_copy(summary))
            .unwrap_or_else(|| live_session_summary_with_index(&remote_session_index, session));
        if !summary.trim().is_empty() {
            summary_by_path.insert(session.session_path.clone(), summary);
        }
        if let Some(title_override) = session_title_overrides
            .get(&session.session_path)
            .filter(|title| !title.trim().is_empty())
        {
            title_by_path.insert(session.session_path.clone(), title_override.clone());
            continue;
        }
        let direct_title = session.title.trim();
        if !direct_title.is_empty()
            && !title_is_low_signal_for_copy(direct_title, cwd)
            && !title_looks_like_abbreviated_shell_label(direct_title)
        {
            title_by_path.insert(session.session_path.clone(), direct_title.to_string());
            if matches!(session.source, SessionSource::LiveSsh) {
                remote_live_direct_title_paths.insert(session.session_path.clone());
            }
            continue;
        }
        if let Some(cwd) = session_cwd
            && let Some(title) = humanized_title_for_copy_target(&CopyGenerationTarget {
                session_path: session.session_path.clone(),
                session_id: session.id.clone(),
                cwd,
                title: session.title.clone(),
                source_updated_at: None,
                remote_context: None,
                remote_machine: None,
                cached_summary: None,
                storage_path: None,
            })
        {
            title_by_path.insert(session.session_path.clone(), title);
        }
    }
    for (session_path, title) in remote_session_index.generated_title_by_path {
        title_by_path.entry(session_path).or_insert(title);
    }
    for (session_path, summary) in remote_session_index.generated_summary_by_path {
        summary_by_path.entry(session_path).or_insert(summary);
    }
    for row in rows.iter_mut() {
        let live_backed = title_by_path.contains_key(&row.full_path)
            || summary_by_path.contains_key(&row.full_path);
        let authoritative_live = authoritative_live_paths.contains(&row.full_path);
        let has_title_override = session_title_overrides
            .get(&row.full_path)
            .is_some_and(|title| !title.trim().is_empty());
        let row_cwd = row.session_cwd.clone().unwrap_or_default();
        let preserved_row_title = row
            .session_title
            .clone()
            .filter(|title| !title_is_low_signal_for_copy(title, &row_cwd));
        if preserved_row_title.is_some()
            && !has_title_override
            && !remote_live_direct_title_paths.contains(&row.full_path)
        {
            row.label = preserved_row_title.clone().unwrap_or_default();
            if let Some(summary) = summary_by_path.get(&row.full_path)
                && (!summary.trim().is_empty())
                && (live_backed || row.detail_label.trim().is_empty())
            {
                row.detail_label = live_session_enriched_detail_label(
                    &row.full_path,
                    summary.clone(),
                    &kept_alive_paths,
                    &cwd_warned_paths,
                );
            } else if kept_alive_paths.contains(&row.full_path) {
                row.detail_label = live_session_detail_label(row.detail_label.clone(), true);
            }
            continue;
        }
        let Some(mut title) = title_by_path.get(&row.full_path).cloned() else {
            if let Some(summary) = summary_by_path.get(&row.full_path)
                && (!summary.trim().is_empty())
                && (live_backed || row.detail_label.trim().is_empty())
            {
                row.detail_label = live_session_enriched_detail_label(
                    &row.full_path,
                    summary.clone(),
                    &kept_alive_paths,
                    &cwd_warned_paths,
                );
            } else if kept_alive_paths.contains(&row.full_path) {
                row.detail_label = live_session_detail_label(row.detail_label.clone(), true);
            }
            continue;
        };
        if matches!(row.kind, BrowserRowKind::Session | BrowserRowKind::Document)
            && title_is_low_signal_for_copy(&title, &row_cwd)
            && !row_cwd.trim().is_empty()
        {
            if let Some(recovered_title) = humanized_title_for_copy_target(&CopyGenerationTarget {
                session_path: row.full_path.clone(),
                session_id: row.session_id.clone().unwrap_or_default(),
                cwd: row_cwd.clone(),
                title: row.label.clone(),
                source_updated_at: None,
                remote_context: None,
                remote_machine: None,
                cached_summary: None,
                storage_path: None,
            }) {
                title = recovered_title;
            }
        }
        row.session_title = Some(title.clone());
        if matches!(row.kind, BrowserRowKind::Session | BrowserRowKind::Document)
            && (authoritative_live
                || live_backed
                || row.label.trim().is_empty()
                || memoized_generated_fallback_title(&row.label)
                || row
                    .session_cwd
                    .as_deref()
                    .is_some_and(|cwd| cwd.trim() == row.label.trim()))
        {
            row.label = title;
        }
        if let Some(summary) = summary_by_path.get(&row.full_path)
            && (!summary.trim().is_empty())
            && (live_backed || row.detail_label.trim().is_empty())
        {
            row.detail_label = live_session_enriched_detail_label(
                &row.full_path,
                summary.clone(),
                &kept_alive_paths,
                &cwd_warned_paths,
            );
        } else if kept_alive_paths.contains(&row.full_path) {
            row.detail_label = live_session_detail_label(row.detail_label.clone(), true);
        }
    }
    // ⛔ RE-COMPOSE THE OUTLINE LAST, because THIS function is the last writer
    // of a row's label.
    //
    // The prefix is composed once when the row is built
    // (`live_session_label_with_index`), and every branch above then overwrites
    // `row.label` with an enriched or generated title — so the number vanished
    // from the sidebar the moment a CLI re-titled its own session, which is
    // exactly the decay that storing the prefix apart from the title exists to
    // prevent. Caught on the live host: a probe row carrying `outline_prefix`
    // "6.9" rendered as "Local Shell Script Debugging" with no number, one
    // minute after it was created.
    //
    // One pass at the end rather than a call at each write site: there are
    // several branches here and a future one would silently drop the number
    // again. `compose_outline_prefix` is idempotent, so re-applying it to a
    // label that already carries its prefix is a no-op.
    let outline_by_path: HashMap<&str, &str> = live_sessions
        .iter()
        .filter_map(|session| {
            session
                .outline_prefix
                .as_deref()
                .map(|prefix| (session.session_path.as_str(), prefix))
        })
        .collect();
    if !outline_by_path.is_empty() {
        let seats = live_session_seats(live_sessions);
        for row in rows.iter_mut() {
            if let Some(prefix) = outline_by_path
                .get(row.full_path.as_str())
                .or_else(|| outline_by_path.get(normalize_live_session_path(&row.full_path).as_str()))
            {
                let heads_a_group = yggterm_core::session_outline::outline_prefix_heads_a_group(
                    prefix,
                    seats.iter().map(String::as_str),
                );
                row.label = compose_outline_prefix(Some(prefix), &row.label, heads_a_group);
            }
        }
    }
}
fn merge_remote_live_sessions(
    machine_rows: &mut BTreeMap<String, SidebarRemoteMachine>,
    ssh_targets: &[SshConnectTarget],
    live_sessions: &[ManagedSessionView],
) {
    for session in live_sessions {
        if session.kind == SessionKind::SshShell {
            continue;
        }
        let Some((machine_key, session_id)) = remote_identity_for_live_session(session) else {
            continue;
        };
        let machine =
            machine_rows
                .entry(machine_key.clone())
                .or_insert_with(|| SidebarRemoteMachine {
                    key: machine_key.clone(),
                    label: ssh_targets
                        .iter()
                        .find(|target| {
                            machine_key_for_ssh_target(&target.ssh_target) == machine_key
                        })
                        .map(ssh_target_machine_label)
                        .unwrap_or_else(|| format!("{machine_key} [ok]")),
                    health: MachineHealth::Healthy,
                    remote_deploy_state: RemoteDeployState::Ready,
                    scanned_sessions: Vec::new(),
                    workspace_folders: Vec::new(),
                    needs_resort: false,
                });
        if let Some(existing) = machine
            .scanned_sessions
            .iter_mut()
            .find(|existing| existing.session_path == session.session_path)
        {
            let live = remote_scanned_session_from_live(&machine_key, &session_id, session);
            if !live.title_hint.trim().is_empty() {
                existing.title_hint = live.title_hint;
            }
            if !live.recent_context.trim().is_empty() {
                existing.recent_context = live.recent_context;
            }
            if !live.cwd.trim().is_empty() {
                existing.cwd = live.cwd;
            }
            if !live.storage_path.trim().is_empty() {
                existing.storage_path = live.storage_path;
            }
            existing.user_message_count = live.user_message_count;
            existing.assistant_message_count = live.assistant_message_count;
            existing.event_count = live.event_count;
            if !live.started_at.trim().is_empty() {
                existing.started_at = live.started_at;
            }
            continue;
        }
        machine
            .scanned_sessions
            .push(remote_scanned_session_from_live(
                &machine_key,
                &session_id,
                session,
            ));
        machine.needs_resort = true;
    }
}
fn sort_remote_scanned_sessions_by_recency(sessions: &mut [RemoteScannedSession]) {
    sessions.sort_by(|a, b| {
        b.modified_epoch
            .cmp(&a.modified_epoch)
            .then_with(|| b.started_at.cmp(&a.started_at))
            .then_with(|| a.session_path.cmp(&b.session_path))
    });
}
fn is_local_live_session_path(path: &str) -> bool {
    path.starts_with("local://")
        || path.starts_with("codex://")
        || path.starts_with("codex-runtime://")
        || path.starts_with("codex-litellm://")
        || path.starts_with("document://")
}
fn remote_identity_for_live_session(session: &ManagedSessionView) -> Option<(String, String)> {
    if let Some((machine_key, session_id)) =
        parse_remote_scanned_session_path(&session.session_path)
    {
        return Some((machine_key.to_string(), session_id.to_string()));
    }
    if session.source != SessionSource::LiveSsh {
        return None;
    }
    let session_id = session.session_path.strip_prefix("live::")?.trim();
    if session_id.is_empty() {
        return None;
    }
    let target = session
        .ssh_target
        .clone()
        .map(|target| target.trim().to_string())
        .filter(|target| !target.is_empty())
        .or_else(|| {
            let target = metadata_value(session, "Target");
            let target = target.trim().to_string();
            (!target.is_empty()).then_some(target)
        })
        .unwrap_or_else(|| session.host_label.clone());
    let machine_key = machine_key_for_ssh_target(&target);
    (!machine_key.is_empty()).then(|| (machine_key, session_id.to_string()))
}
fn machine_key_for_ssh_target(target: &str) -> String {
    let host = target
        .trim()
        .rsplit('@')
        .next()
        .unwrap_or(target)
        .trim()
        .trim_end_matches(".local");
    machine_key_from_labelish(host)
}
fn remote_scanned_session_from_live(
    _machine_key: &str,
    session_id: &str,
    session: &ManagedSessionView,
) -> RemoteScannedSession {
    let cwd = metadata_value(session, "Cwd");
    let storage_path = metadata_value(session, "Storage");
    let started_at = metadata_value(session, "Started");
    let recent_context = preview_context_from_session(session).unwrap_or_default();
    // ⛔ COUNT THE CONVERSATION, NOT THE PREVIEW. These feed the metadata rail's
    // "Conversation N user · M assistant", and they used to count preview BLOCKS
    // by tone. A preview is an excerpt built for display and is routinely EMPTY
    // for a terminal-view row, so a live session holding 774 records reported
    // `0 user · 0 assistant` — a number that reads as "new session" and so never
    // announced that the instrument had nothing to measure.
    //
    // The transcript is the only thing that knows. It is read on demand for THIS
    // session and memoised on (path, len, mtime), which is what keeps it off the
    // bulk scan path: a rail describes one selected session, not a store.
    let counted = (!storage_path.trim().is_empty())
        .then(|| {
            yggterm_core::count_agent_transcript_messages_cached(Path::new(
                storage_path.trim(),
            ))
            .ok()
        })
        .flatten();
    let preview_user = session
        .preview
        .blocks
        .iter()
        .filter(|block| block.tone == PreviewTone::User)
        .count();
    let preview_assistant = session
        .preview
        .blocks
        .iter()
        .filter(|block| block.tone == PreviewTone::Assistant)
        .count();
    // Fall back to the preview only when there is no readable transcript — a
    // window is still better than nothing, and it is what was shipping.
    let user_message_count = counted.map(|c| c.user).unwrap_or(preview_user);
    let assistant_message_count = counted.map(|c| c.assistant).unwrap_or(preview_assistant);
    RemoteScannedSession {
        session_path: session.session_path.clone(),
        session_id: session_id.to_string(),
        cwd,
        started_at,
        modified_epoch: 0,
        event_count: counted.map(|c| c.total).unwrap_or_else(|| session.preview.blocks.len()),
        user_message_count,
        assistant_message_count,
        title_hint: session.title.clone(),
        recent_context,
        cached_precis: None,
        cached_summary: None,
        live_runtime: false,
        // Derived from a live row, not chosen by a human: provenance is stamped
        // by `set_session_title_explicit`, never by a projection.
        title_is_explicit: false,
        storage_path,
    }
}
#[derive(Debug)]
struct SidebarRemoteMachine {
    key: String,
    label: String,
    health: MachineHealth,
    remote_deploy_state: RemoteDeployState,
    scanned_sessions: Vec<RemoteScannedSession>,
    workspace_folders: Vec<RemoteWorkspaceFolder>,
    needs_resort: bool,
}
#[derive(Debug, Clone)]
struct RemoteWorkspaceFolder {
    cwd: String,
    title: String,
}
#[derive(Debug, Clone)]
enum TerminalLaunchContext {
    Local {
        cwd: Option<String>,
        title_hint: Option<String>,
    },
    Remote {
        ssh_target: String,
        prefix: Option<String>,
        cwd: Option<String>,
        title_hint: Option<String>,
    },
}
#[derive(Debug, Default)]
struct RemoteFolderTree {
    children: BTreeMap<String, RemoteFolderNode>,
    root_session_indices: Vec<usize>,
}
#[derive(Debug, Default)]
struct RemoteFolderNodeBuilder {
    name: String,
    full_path: String,
    title_override: Option<String>,
    workspace_folder: bool,
    child_paths: HashSet<String>,
    session_indices: Vec<usize>,
}
#[derive(Debug, Clone)]
struct RemoteFolderNode {
    name: String,
    full_path: String,
    workspace_folder: bool,
    children: BTreeMap<String, RemoteFolderNode>,
    session_indices: Vec<usize>,
    descendant_sessions: usize,
}
fn ssh_target_machine_label(target: &SshConnectTarget) -> String {
    let raw = if !target.label.trim().is_empty() {
        target.label.trim()
    } else {
        target
            .ssh_target
            .rsplit('@')
            .next()
            .unwrap_or(target.ssh_target.as_str())
            .trim()
    };
    format!("{raw} [ok]")
}
fn machine_health_attr_value(health: MachineHealth) -> &'static str {
    match health {
        MachineHealth::Healthy => "healthy",
        MachineHealth::Cached => "cached",
        MachineHealth::Offline => "offline",
    }
}
fn machine_display_health(
    health: MachineHealth,
    deploy_state: RemoteDeployState,
    session_count: usize,
) -> MachineHealth {
    if matches!(health, MachineHealth::Cached)
        && matches!(deploy_state, RemoteDeployState::Ready)
        && session_count > 0
    {
        MachineHealth::Healthy
    } else {
        health
    }
}
fn machine_indicator_color_value(health: MachineHealth) -> &'static str {
    match health {
        MachineHealth::Healthy => "#16a34a",
        MachineHealth::Cached => "#f59e0b",
        MachineHealth::Offline => "#ef4444",
    }
}
fn machine_status_detail(health: MachineHealth, deploy_state: RemoteDeployState) -> String {
    let health_text = match health {
        MachineHealth::Healthy => "reachable",
        MachineHealth::Cached => "cached snapshot",
        MachineHealth::Offline => "offline",
    };
    let deploy_text = match deploy_state {
        RemoteDeployState::Ready => "remote yggterm ready",
        RemoteDeployState::CopyingBinary => "copying yggterm binary",
        RemoteDeployState::Planned => "remote bootstrap planned",
        RemoteDeployState::NotRequired => "no remote bootstrap needed",
    };
    format!("{health_text} · {deploy_text}")
}
fn push_remote_machine_rows(
    rows: &mut Vec<BrowserRow>,
    machine: &SidebarRemoteMachine,
    expanded_paths: &HashSet<String>,
) {
    let display_health = machine_display_health(
        machine.health,
        machine.remote_deploy_state,
        machine.scanned_sessions.len(),
    );
    let machine_label = apply_machine_health_suffix(&machine.label, display_health);
    let machine_path = format!("__remote_machine__/{}", machine.key);
    let machine_expanded = expanded_paths.contains(&machine_path);
    rows.push(BrowserRow {
        kind: BrowserRowKind::Group,
        full_path: machine_path.clone(),
        label: machine_label.clone(),
        detail_label: machine_status_detail(machine.health, machine.remote_deploy_state),
        document_kind: None,
        group_kind: None,
        session_title: None,
        depth: 0,
        host_label: "live".to_string(),
        descendant_sessions: machine.scanned_sessions.len(),
        expanded: machine_expanded,
        session_id: None,
        session_cwd: None,
        session_kind: None,
    });
    if !machine_expanded {
        return;
    }
    let remote_short_ids = unique_session_short_ids_for_pairs(
        &machine
            .scanned_sessions
            .iter()
            .map(|session| (session.session_path.clone(), session.session_id.clone()))
            .collect::<Vec<_>>(),
    );
    let session_labels = machine
        .scanned_sessions
        .iter()
        .map(|session| {
            (
                session.session_path.clone(),
                remote_scanned_session_label(session, &remote_short_ids),
            )
        })
        .collect::<HashMap<_, _>>();
    let folder_tree =
        build_remote_folder_tree(&machine.scanned_sessions, &machine.workspace_folders);
    for child in folder_tree.children.values() {
        append_remote_folder_rows(rows, machine, child, expanded_paths, &session_labels, 1);
    }
    for &session_idx in &folder_tree.root_session_indices {
        if let Some(scanned) = machine.scanned_sessions.get(session_idx) {
            let label = session_labels
                .get(&scanned.session_path)
                .cloned()
                .unwrap_or_else(|| remote_scanned_session_label(scanned, &remote_short_ids));
            rows.push(BrowserRow {
                kind: BrowserRowKind::Session,
                full_path: scanned.session_path.clone(),
                label: label.clone(),
                detail_label: String::new(),
                document_kind: None,
                group_kind: None,
                session_title: Some(label),
                depth: 1,
                host_label: machine.key.clone(),
                descendant_sessions: 1,
                expanded: true,
                session_id: Some(scanned.session_id.clone()),
                session_cwd: Some(scanned.cwd.clone()),
                session_kind: None,
            });
        }
    }
}
/// The label for a scanned remote row.
///
/// ⛔ Thin wrapper ONLY: it reads the live `SessionTitleStore` and hands the
/// answer to the pure function below. Everything that decides a label lives in
/// [`remote_scanned_session_label_with_saved_title`], so a test can state the
/// store's answer instead of inheriting whatever this developer's machine
/// happens to hold.
///
/// It used to read the store inline, which made the label tests
/// environment-dependent: identical code passed on one fleet host and failed on
/// another purely because one `~/.yggterm/session-titles.db` had a row for the
/// fixture's session id and the other did not. A test that consults the live
/// store is not testing the code.
fn remote_scanned_session_label(
    session: &RemoteScannedSession,
    short_ids: &HashMap<String, String>,
) -> String {
    let saved_title = resolve_yggterm_home()
        .ok()
        .and_then(|home| yggterm_core::SessionTitleStore::open(&home).ok())
        .and_then(|store| store.get_title(&session.session_id).ok().flatten());
    remote_scanned_session_label_with_saved_title(session, short_ids, saved_title.as_deref())
}

fn remote_scanned_session_label_with_saved_title(
    session: &RemoteScannedSession,
    short_ids: &HashMap<String, String>,
    saved_title: Option<&str>,
) -> String {
    let title = session.title_hint.trim();
    if title.starts_with("Agent ") && title.contains(" unnamed ") {
        if let Some(colon) = title.find(": ") {
            let suffix = title[colon + 2..].trim();
            if !suffix.is_empty() && !memoized_generated_fallback_title(suffix) {
                return suffix.to_string();
            }
        }
    }
    if !title.is_empty() && !memoized_generated_fallback_title(title) {
        return session.title_hint.clone();
    }
    if let Some(title) = session
        .cached_summary
        .as_deref()
        .filter(|summary| !summary.trim().is_empty())
        .filter(|summary| !memoized_low_signal_generated_copy(summary))
        .and_then(best_effort_title_from_context)
    {
        return title;
    }
    if let Some(title) = best_effort_title_from_context(&session.recent_context) {
        return title;
    }
    if let Some(saved_title) = saved_title {
        if !saved_title.trim().is_empty()
            && !memoized_generated_fallback_title(saved_title)
            && !memoized_low_signal_generated_copy(saved_title)
        {
            return saved_title.to_string();
        }
    }
    if let Some(short_id) = short_ids.get(&session.session_path) {
        let lower_title = title.to_ascii_lowercase();
        if short_id.len() > 8
            || matches!(
                lower_title.as_str(),
                "yggterm codex" | "yggterm shell" | "codex session"
            )
        {
            return short_id.clone();
        }
    }
    // The kind comes from the row's own scheme. It used to be hardcoded to
    // Codex, so a muse or agy row that reached this line was humanized as a
    // Codex session — a second CLI's name on a first CLI's row.
    let kind = yggterm_core::agent_scheme::session_kind_for_path(&session.session_path)
        .unwrap_or(SessionKind::Codex);
    humanized_terminal_title(kind, &session.cwd, None)
        .filter(|title| !memoized_generated_fallback_title(title))
        // ⛔ A ROW WITH NO TURNS YET IS NOT UNTITLED — IT IS NEW, and the CLI's
        // own lifecycle has a name for that state. Three muse rows on the
        // desktop wore a 7-character hash because every title source was
        // legitimately empty: they had been spawned minutes earlier and nobody
        // had typed into them. Falling to the short id there is the shorthash
        // the title law forbids, arrived at honestly.
        //
        // It sits BELOW the cwd-derived name on purpose: "New Codex Session"
        // says less than the folder the session is rooted in, so the
        // placeholder is the answer only when nothing else has one. And the
        // placeholder IS a fallback by the recognizer's reckoning — chosen
        // here, not found upstream, so the chore keeps treating it as
        // replaceable while the row still shows a name.
        .or_else(|| {
            (session.user_message_count == 0)
                .then(|| {
                    yggterm_core::agent_scheme::session_kind_for_path(&session.session_path).map(
                        |kind| {
                            // The SAME birth rule the daemon mints a live row
                            // with, so a row that has said nothing yet reads
                            // identically whichever surface is showing it. The
                            // machine comes off the row's own path for a remote
                            // row and is this host otherwise.
                            let machine = yggterm_core::agent_scheme::remote_row_machine_key(
                                &session.session_path,
                            )
                            .map(ToOwned::to_owned)
                            .or_else(yggterm_core::local_machine_name_opt);
                            yggterm_core::agent_cli::new_session_birth_title(
                                kind,
                                machine.as_deref(),
                            )
                        },
                    )
                })
                .flatten()
        })
        .or_else(|| short_ids.get(&session.session_path).cloned())
        .unwrap_or_else(|| fallback_label_for_session_path(&session.session_path))
}
fn remote_workspace_folder_from_row(row: &BrowserRow) -> Option<(String, RemoteWorkspaceFolder)> {
    if row.kind != BrowserRowKind::Group || row.group_kind != Some(WorkspaceGroupKind::Folder) {
        return None;
    }
    let normalized = remote_workspace_virtual_path(row)?;
    let rest = normalized.strip_prefix("__remote_folder__/")?;
    let (machine_key, cwd_tail) = rest.split_once('/')?;
    if machine_key.trim().is_empty() || cwd_tail.trim().is_empty() {
        return None;
    }
    let mut cwd = format!("/{}", cwd_tail.trim_matches('/'));
    let mut title = row.label.clone();
    if remote_workspace_cwd_uses_generated_leaf(&cwd)
        && remote_workspace_bookmark_label_looks_like_path(&row.label)
        && let Some((target_path, _)) = remote_workspace_rename_target(row, &row.label)
        && let Some((_, target_cwd)) = remote_folder_machine_and_cwd_from_path(&target_path)
    {
        cwd = target_cwd;
        title = workspace_leaf_name(&cwd).unwrap_or_else(|| row.label.clone());
    }
    Some((
        machine_key.to_string(),
        RemoteWorkspaceFolder { cwd, title },
    ))
}
fn remote_workspace_cwd_uses_generated_leaf(cwd: &str) -> bool {
    workspace_cwd_uses_generated_leaf(cwd)
}
fn remote_workspace_bookmark_label_looks_like_path(label: &str) -> bool {
    let label = label.trim();
    label.starts_with('/')
        || label.split('/').any(|part| !part.trim().is_empty()) && label.contains('/')
}
fn build_remote_folder_tree(
    sessions: &[RemoteScannedSession],
    workspace_folders: &[RemoteWorkspaceFolder],
) -> RemoteFolderTree {
    let mut tree = RemoteFolderTree::default();
    let mut nodes = HashMap::<String, RemoteFolderNodeBuilder>::new();
    let mut root_child_paths = HashSet::<String>::new();
    for (session_idx, session) in sessions.iter().enumerate() {
        if !insert_remote_folder_tree_path(
            &session.cwd,
            &mut nodes,
            &mut root_child_paths,
            Some(session_idx),
            None,
        ) {
            tree.root_session_indices.push(session_idx);
        }
    }
    for folder in workspace_folders {
        insert_remote_folder_tree_path(
            &folder.cwd,
            &mut nodes,
            &mut root_child_paths,
            None,
            Some(folder.title.clone()),
        );
    }
    let mut sorted_root_child_paths = root_child_paths.into_iter().collect::<Vec<_>>();
    sorted_root_child_paths.sort();
    for path in sorted_root_child_paths {
        if let Some(node) = finalize_remote_folder_node(&path, &mut nodes) {
            tree.children.insert(path, node);
        }
    }
    compress_remote_folder_children(&mut tree.children);
    for child in tree.children.values_mut() {
        populate_remote_folder_descendant_counts(child);
    }
    tree
}
fn insert_remote_folder_tree_path(
    cwd: &str,
    nodes: &mut HashMap<String, RemoteFolderNodeBuilder>,
    root_child_paths: &mut HashSet<String>,
    session_idx: Option<usize>,
    title_override: Option<String>,
) -> bool {
    let segments = cwd
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    if segments.is_empty() {
        return false;
    }
    let mut current = String::new();
    let mut parent_path = None::<String>;
    for (ix, segment) in segments.iter().enumerate() {
        current.push('/');
        current.push_str(segment);
        let label = if ix == 0 {
            format!("/{segment}")
        } else {
            (*segment).to_string()
        };
        let node = nodes
            .entry(current.clone())
            .or_insert_with(|| RemoteFolderNodeBuilder {
                name: label,
                full_path: current.clone(),
                title_override: None,
                workspace_folder: false,
                child_paths: HashSet::new(),
                session_indices: Vec::new(),
            });
        if ix + 1 == segments.len() {
            if let Some(session_idx) = session_idx {
                node.session_indices.push(session_idx);
            }
            if let Some(title) = title_override
                .as_ref()
                .filter(|title| !title.trim().is_empty())
            {
                node.title_override = Some(title.clone());
                node.workspace_folder = true;
            }
        }
        if let Some(parent) = parent_path.as_ref() {
            if let Some(parent_node) = nodes.get_mut(parent) {
                parent_node.child_paths.insert(current.clone());
            }
        } else {
            root_child_paths.insert(current.clone());
        }
        parent_path = Some(current.clone());
    }
    true
}
fn finalize_remote_folder_node(
    path: &str,
    nodes: &mut HashMap<String, RemoteFolderNodeBuilder>,
) -> Option<RemoteFolderNode> {
    let builder = nodes.remove(path)?;
    let mut child_paths = builder.child_paths.into_iter().collect::<Vec<_>>();
    child_paths.sort();
    let mut children = BTreeMap::new();
    for child_path in child_paths {
        if let Some(child) = finalize_remote_folder_node(&child_path, nodes) {
            children.insert(child_path, child);
        }
    }
    Some(RemoteFolderNode {
        name: builder.title_override.unwrap_or(builder.name),
        full_path: builder.full_path,
        workspace_folder: builder.workspace_folder,
        children,
        session_indices: builder.session_indices,
        descendant_sessions: 0,
    })
}
fn compress_remote_folder_children(children: &mut BTreeMap<String, RemoteFolderNode>) {
    let keys = children.keys().cloned().collect::<Vec<_>>();
    for key in keys {
        if let Some(child) = children.get_mut(&key) {
            compress_remote_folder_node(child, true);
        }
    }
}
fn compress_remote_folder_node(node: &mut RemoteFolderNode, can_compress_self: bool) {
    let child_keys = node.children.keys().cloned().collect::<Vec<_>>();
    for key in child_keys {
        if let Some(child) = node.children.get_mut(&key) {
            compress_remote_folder_node(child, true);
        }
    }
    if !can_compress_self {
        return;
    }
    while !node.workspace_folder && node.session_indices.is_empty() && node.children.len() == 1 {
        let (_, child) = node.children.pop_first().expect("child exists");
        node.name = remote_folder_join_label(&node.name, &child.name);
        node.full_path = child.full_path;
        node.workspace_folder = child.workspace_folder;
        node.session_indices = child.session_indices;
        node.descendant_sessions = child.descendant_sessions;
        node.children = child.children;
    }
}
fn remote_folder_join_label(left: &str, right: &str) -> String {
    if left == "/" {
        return format!("/{right}");
    }
    if left.ends_with('/') {
        format!("{left}{right}")
    } else {
        format!("{left}/{right}")
    }
}
fn populate_remote_folder_descendant_counts(node: &mut RemoteFolderNode) -> usize {
    let mut count = node.session_indices.len();
    for child in node.children.values_mut() {
        count += populate_remote_folder_descendant_counts(child);
    }
    node.descendant_sessions = count;
    count
}
fn compressed_remote_folder_paths(sessions: &[RemoteScannedSession], cwd: &str) -> Vec<String> {
    let tree = build_remote_folder_tree(sessions, &[]);
    let mut paths = Vec::new();
    for child in tree.children.values() {
        if collect_compressed_remote_folder_paths(child, cwd, &mut paths) {
            break;
        }
    }
    paths
}
fn collect_compressed_remote_folder_paths(
    node: &RemoteFolderNode,
    cwd: &str,
    paths: &mut Vec<String>,
) -> bool {
    if cwd != node.full_path
        && !cwd
            .strip_prefix(node.full_path.as_str())
            .is_some_and(|suffix| suffix.starts_with('/'))
    {
        return false;
    }
    paths.push(node.full_path.clone());
    for child in node.children.values() {
        if collect_compressed_remote_folder_paths(child, cwd, paths) {
            return true;
        }
    }
    true
}
fn append_remote_folder_rows(
    rows: &mut Vec<BrowserRow>,
    machine: &SidebarRemoteMachine,
    node: &RemoteFolderNode,
    expanded_paths: &HashSet<String>,
    session_labels: &HashMap<String, String>,
    depth: usize,
) {
    let row_path = format!("__remote_folder__/{}{}", machine.key, node.full_path);
    let is_expanded = expanded_paths.contains(&row_path);
    rows.push(BrowserRow {
        kind: BrowserRowKind::Group,
        full_path: row_path,
        label: node.name.clone(),
        detail_label: String::new(),
        document_kind: None,
        group_kind: node.workspace_folder.then_some(WorkspaceGroupKind::Folder),
        session_title: None,
        depth,
        host_label: machine.key.clone(),
        descendant_sessions: node.descendant_sessions,
        expanded: is_expanded,
        session_id: None,
        session_cwd: Some(node.full_path.clone()),
        session_kind: None,
    });
    if !is_expanded {
        return;
    }
    for child in node.children.values() {
        append_remote_folder_rows(
            rows,
            machine,
            child,
            expanded_paths,
            session_labels,
            depth + 1,
        );
    }
    for &session_idx in &node.session_indices {
        if let Some(scanned) = machine.scanned_sessions.get(session_idx) {
            let label = session_labels
                .get(&scanned.session_path)
                .cloned()
                .unwrap_or_else(|| scanned.title_hint.clone());
            rows.push(BrowserRow {
                kind: BrowserRowKind::Session,
                full_path: scanned.session_path.clone(),
                label: label.clone(),
                detail_label: String::new(),
                document_kind: None,
                group_kind: None,
                session_title: Some(label),
                depth: depth + 1,
                host_label: machine.key.clone(),
                descendant_sessions: 1,
                expanded: true,
                session_id: Some(scanned.session_id.clone()),
                session_cwd: Some(scanned.cwd.clone()),
                session_kind: None,
            });
        }
    }
}
fn machine_key_from_labelish(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() {
                ch.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .to_string()
}
fn queue_remove_saved_ssh_target(mut state: Signal<ShellState>, row: BrowserRow) {
    let Some(machine_key) = saved_ssh_target_machine_key(&row, state.read().server.ssh_targets())
    else {
        state.with_mut_counted(|shell| {
            shell.close_context_menu();
            shell.push_notification(
                NotificationTone::Info,
                "No Saved Target",
                format!("{} is not backed by a saved SSH target.", row.label),
            );
        });
        return;
    };
    state.with_mut_counted(|shell| {
        shell.select_tree_row(&row, TreeSelectionMode::Replace);
        shell.pending_delete = Some(PendingDeleteDialog {
            document_paths: Vec::new(),
            group_paths: Vec::new(),
            session_paths: Vec::new(),
            ssh_machine_keys: vec![machine_key],
            labels: vec![row.label.clone()],
            hard_delete: false,
            live_session_close: false,
            live_session_bulk_close: false,
            live_session_unkept_paths: Vec::new(),
        });
        shell.close_context_menu();
        shell.last_action = "confirm delete".to_string();
        shell.refresh_tree_debug("open_delete_dialog_saved_ssh_target");
    });
}
fn apply_machine_health_suffix(label: &str, health: MachineHealth) -> String {
    let base = machine_label_text(label).unwrap_or_else(|| label.to_string());
    format!(
        "{} {}",
        base,
        match health {
            MachineHealth::Healthy => "[ok]",
            MachineHealth::Cached => "[cached]",
            MachineHealth::Offline => "[offline]",
        }
    )
}
fn queue_new_group_for_row(mut state: Signal<ShellState>, row: BrowserRow) {
    state.with_mut_counted(|shell| {
        shell.server_busy = true;
        shell.last_action = format!("creating group in {}", row.label);
        shell.close_context_menu();
    });
    let settings = state.read().settings.clone();
    spawn(async move {
        let row_for_task = row.clone();
        let outcome =
            task::spawn_blocking(move || -> Result<(String, yggterm_core::SessionNode)> {
                let store = SessionStore::open_or_init()?;
                let virtual_path = new_group_virtual_path_for_row(&row_for_task);
                // Deliberately NO directory creation here: the path still ends
                // in a generated `folder-<nanos>` leaf, and materializing that
                // litters the filesystem (reported 2026-07-09). The rename —
                // the moment the folder gets its real name — moves the group
                // to the real path AND creates/renames the real directory
                // (`materialize_local_folder_rename`).
                store.save_group_with_kind(
                    &virtual_path,
                    Some("New Folder"),
                    WorkspaceGroupKind::Folder,
                )?;
                Ok((virtual_path, store.load_codex_tree(&settings)?))
            })
            .await;
        state.with_mut_counted(|shell| match outcome {
            Ok(Ok((selected_path, browser_tree))) => {
                let expanded_paths = shell.browser.expanded_paths();
                shell.replace_browser_tree(browser_tree);
                shell
                    .browser
                    .restore_ui_state(&expanded_paths, Some(&selected_path));
                shell.browser.select_path(selected_path.clone());
                shell.selected_tree_paths.clear();
                shell.selected_tree_paths.insert(selected_path.clone());
                shell.selection_anchor = Some(selected_path.clone());
                shell.tree_rename_path = Some(selected_path.clone());
                shell.tree_rename_depth = shell
                    .browser
                    .rows()
                    .iter()
                    .find(|row| row.full_path == selected_path)
                    .map(|row| row.depth);
                shell.tree_rename_value = "New Folder".to_string();
                shell.tree_rename_started_at_ms = current_millis();
                shell.tree_rename_input_focused_once = false;
                shell.sync_browser_settings();
                shell.server_busy = false;
                shell.last_action = format!("added folder in {}", row.label);
                shell.refresh_tree_debug("added_folder");
            }
            Ok(Err(error)) => {
                shell.server_busy = false;
                shell.last_action = format!("folder creation failed: {error}");
                shell.push_notification(
                    NotificationTone::Error,
                    "Folder Creation Failed",
                    error.to_string(),
                );
            }
            Err(error) => {
                shell.server_busy = false;
                shell.last_action = format!("folder task failed: {error}");
                shell.push_notification(
                    NotificationTone::Error,
                    "Folder Task Failed",
                    error.to_string(),
                );
            }
        });
    });
}
fn selected_folder_creation_row_for_app_control(shell: &ShellState) -> Option<BrowserRow> {
    let rows = shell.all_sidebar_rows_for_selection();
    let mut preferred_paths = Vec::new();
    if let Some(path) = shell.selection_anchor.as_deref() {
        preferred_paths.push(path);
    }
    preferred_paths.extend(shell.selected_tree_paths.iter().map(String::as_str));
    if let Some(path) = shell.browser.selected_path() {
        preferred_paths.push(path);
    }
    for path in preferred_paths {
        if let Some(row) = rows
            .iter()
            .find(|row| row.full_path == path)
            .filter(|row| row_accepts_new_folder(row))
        {
            return Some(row.clone());
        }
    }
    rows.into_iter().find(row_accepts_new_folder)
}
fn row_accepts_new_folder(row: &BrowserRow) -> bool {
    row.full_path == "local"
        || is_workspace_row(row)
        || (row.kind == BrowserRowKind::Group && remote_folder_cwd(row).is_some())
}
